update content_bodies set title = '【京都・京丹波】 TANTAN SATOYAMA KYOTO & Super Relax Stay', description = 'JR京都駅からわずか1時間でアクセスできる里山エリアで、優雅な日本の里山生活を体験できる2泊3日の滞在プログラムです。京都の田舎でのんびりと過ごす貴重な体験を提供し、自然と共にリラックスした時間を楽しむことができます。' where id = 'IOj6Okk5dF_ijYhJXq3xk';
