update content_bodies set title = '東京からの日帰り旅行（神奈川／鎌倉）', description = '神奈川県の公式観光ウェブサイトでは、旅行計画を立てるためのリソースを提供しています。旅行の計画を整理し、行程を作成し、特に鎌倉地域の観光コースを見つけることができます。' where id = 'ZWCKKVt5KlbU8ae6fFwXg';
update content_bodies set title = 'Day Trip from Tokyo (KANAGAWA/KAMAKURA)', description = 'The official Kanagawa Tourism website offers resources to help you plan your trip. You can organize your travel plans, create your itinerary, and discover the best sightseeing courses in the Kanagawa region, particularly in Kamakura.' where id = 'qz9DYap15wkoPd58rKmSV';
update content_bodies set title = '牛鍋_神奈川での10のアクティビティ', description = '東京の南に位置する神奈川県は、多様でアクセスしやすい魅力的な旅行先です。神奈川では、さまざまな楽しい体験を楽しむことができます。' where id = 'hW6RTBp7rHlmuGV4nOGZk';
update content_bodies set title = 'Gyuunabe_10 things to do in Kanagawa', description = 'Kanagawa, located south of Tokyo, offers a variety of enjoyable experiences. This prefecture is known for its diversity and accessibility, making it an ideal destination for travelers.' where id = 'PuqDaxuHU2cx3Eom5bBZb';
update content_bodies set title = '箱根ヴェネチアンガラス美術館 - 神奈川での10のアクティビティ', description = '東京の南に位置する神奈川県は、多様性とアクセスの良さで知られています。訪れる人々は、さまざまな楽しい旅行を楽しむことができ、旅行者にとって魅力的な目的地となっています。' where id = 'VyGjSyjrv4JgsTpvTJDAX';
update content_bodies set title = 'Hakone Venetian Glass Museum - 10 Things to Do in Kanagawa', description = 'Located south of Tokyo, Kanagawa is a prefecture known for its diversity and accessibility. Visitors can enjoy a variety of delightful trips, making it an attractive destination for travelers.' where id = '0RLxoHsVsDug6yPS1yQZL';
update content_bodies set title = '大山のイベント（産業能率大学）', description = '産業能率大学の学生たちは、神奈川県が推進する「新たな観光拠点」の候補地である「大山」で行われるイベントを紹介するための動画を制作しました。' where id = 'Z3lVJCdxxa9kx9zxuAKuK';
update content_bodies set title = 'Events of Oyama (Sanno University)', description = 'Students from the SANNO Institute of Management created a video to showcase events taking place at ''Oyama.'' This location is being considered as a potential site for ''New Bases for Tourism,'' an initiative promoted by the Kanagawa Prefectural Government.' where id = 'wTYkeZx3fnCBYdT7ir32X';
update content_bodies set title = '大山の秋の紅葉（産業能率大学）', description = '産業能率大学の学生たちが、神奈川県が推進する「新たな観光拠点」の候補地である「大山」の秋の紅葉を紹介する動画を制作しました。' where id = 'ddU2F0eqpCZfQ5joebxrw';
update content_bodies set title = 'Autumn foliage of Oyama (Sanno University)', description = 'Students from SANNO Institute of Management created a video showcasing the autumn leaves of Oyama. This location is being considered as a potential site for ''New Bases for Tourism,'' an initiative promoted by the Kanagawa Prefectural Government.' where id = 'yHL7K6h_63Lcq805Mpkhy';
update content_bodies set title = 'どんちっちはまだ short.ver【島根県浜田市観光PR動画（公式）】', description = '島根県浜田市の魅力を紹介する観光プロモーション動画『どんちっちはまだ』のショート版が公開されました。この動画では、浜田市の美しい海や山、伝統的な石見神楽が紹介されており、自然と文化・歴史が息づくまちとしての魅力が詰まっています。浜田市を訪れることを促す内容となっており、観光協会の公式サイトや他の動画リンクも提供されています。' where id = 'GsT5DQIGpoUatVqvN6b5z';
update content_bodies set title = 'Donchicchi wa Mada Short Version - Official Tourism Promotion Video of Hamada City, Shimane Prefecture', description = 'The official tourism promotion video for Hamada City, Shimane Prefecture, showcases the city''s attractions, including its beautiful sea, mountains, and the traditional Iwami Kagura dance. Titled ''Donchicchi wa Mada,'' the short version of the video invites viewers to explore the natural beauty and rich cultural heritage of Hamada City. The video emphasizes the unique blend of nature, culture, and history that defines the area. For more information, viewers can access the full version and additional resources through the provided links.' where id = 'EHrFy_RT3dBD91oj2eDM-';
update content_bodies set title = '大磯　Oiso（東海大学 Tokai University）', description = '東海大学の学生たちは、神奈川県が「新たな観光の核」として推進している大磯の見所を紹介する映像を制作しました。この映像では、大磯の魅力や観光スポットが紹介されており、地域の観光振興に寄与することを目的としています。学生たちの視点から、大磯の新たな魅力を発信する取り組みが行われています。' where id = 'D9IU_WoJgMTVXsKBgApXh';
update content_bodies set title = 'Oiso (Tokai University)', description = 'Students from Tokai University have created a video showcasing the main attractions of Oiso, which is being promoted by the Kanagawa Prefectural Government as a candidate for ''New Bases for Tourism''.' where id = 'vuWSnxjDyQG-DYl9RhN4V';
update content_bodies set title = '瀬戸内海に現れる神秘的な砂の道 黒島ヴィーナスロードを歩く（瀬戸内市）【岡山観光WEB】', description = '岡山県で今話題の体験やツアーを厳選して紹介しています。臨場感あふれる体験レポートや、予約・申込みに関する情報も掲載されています。' where id = 'AZnjh9_6aGyNtDthsdk92';
update content_bodies set title = 'The Mysterious Sand Path Appearing in the Seto Inland Sea: Walking the Kuroshima Venus Road (Setouchi City)【Okayama Tourism WEB】', description = 'This article introduces popular experiences and tours currently trending in Okayama Prefecture. It features immersive experience reports along with information on reservations and applications.' where id = 'K2Pgo0TFX4Oi-X5ulgxPt';
update content_bodies set title = 'やさか村ワタブン劇場 ～制作：浜田市立弥栄中学校2年生～', description = '島根県浜田市の浜田市立弥栄中学校2年生が制作した「やさか村ワタブン劇場」は、弥栄町の観光スポットを紹介する動画です。生徒たちは、総合的な学習の時間に弥栄の魅力を発信することをテーマに取り組み、県内外から多くの訪問者がある「やさか村ワタブン」の魅力を広めたいと考えました。動画では、工房での体験や製品の魅力を詳しく伝えています。視聴者には感想をアンケートで回答してもらうよう呼びかけています。また、動画ではブランド名「ツートントン」の隠された意味にも触れ、感動的な要素を加えています。' where id = 'hfneP8gY7ydrc9YvtbtST';
update content_bodies set title = 'Yasaka Village Watabun Theater - Produced by 2nd Year Students of Hamada Municipal Yasae Junior High School', description = 'This project showcases the attractions of Yasaka Village Watabun, created by the 2nd-year students of Hamada Municipal Yasae Junior High School in Hamada City, Shimane Prefecture. The students aimed to promote the charm of Yasaka through a video during their integrated learning time. They wanted to share the experiences available at the workshop and highlight the products made there. The video invites viewers to learn more about the unique features of Yasaka Village Watabun, which attracts many visitors from both inside and outside the prefecture. Feedback is encouraged through a survey linked in the description. The video also touches on the brand name ''Tsutonton'' and its hidden meaning, which adds an emotional touch to the presentation.' where id = 'LNltPHQuYAD0WnmfO0ZJ_';
update content_bodies set title = '鳥羽の日本式ホテル ー日本の旅館を体験することを強くお勧めしますー', description = '鳥羽の旅館では、居間が女将によって快適な寝室に変わります。布団とその周りの畳の香りが、心地よい眠りへと誘います。三重県鳥羽市は、巨大なアワビやカキ、エビなどの美味しい海鮮で知られています。また、地元の温泉を楽しんだり、日本の公衆浴場の習慣について学んだりすることもできます。鳥羽へのアクセスは便利で、名古屋からは1.5時間、大阪からは近鉄特急で2時間です。詳細については、鳥羽旅館組合や鳥羽市観光協会の公式ウェブサイトを訪れてください。' where id = 'KiHdtvjvOB0bqs0h3wuO4';
update content_bodies set title = 'JAPANESE-STYLE-HOTEL IN TOBA, JAPAN ーHighly recommend you experience a Japanese innー', description = 'Experience the unique charm of a ryokan in Toba, Japan, where the sitting room is transformed into a cozy bedroom by the OKAMI, the traditional landlady. The futon and the soothing scent of tatami create a perfect environment for a restful sleep. Toba, located in Mie Prefecture, is known for its delicious seafood, including giant abalones, oysters, and shrimps. Visitors can also enjoy the local hot springs and learn about the customs of Japanese public baths. Access to Toba is convenient, with a 1.5-hour journey from Nagoya and a 2-hour trip from Osaka via Kintetsu Limited Express. For more information, you can visit the official websites of the Toba Ryokan Association and the Toba Tourism Association.' where id = 'Xp6ill1C6VCB0lji27Kvt';
update content_bodies set title = 'フェリーで鳥羽を楽しもう - フェリーが素晴らしい旅を提供します', description = '三重県の鳥羽の離島をフェリーで巡る旅を楽しみましょう。この旅では、鳥羽の美しい風景や温泉、伝統的な日本の宿を体験することができます。鳥羽へのアクセスは便利で、名古屋からは近鉄特急で約1.5時間、大阪からは約2時間で到着します。チケット購入は近鉄の公式ウェブサイトで可能です。また、日本式ホテルや地元の観光協会に関する情報もあり、鳥羽の豊かな文化や観光名所についての洞察を得ることができます。' where id = '_mbpgyC0i0egYJg0NaVkj';
update content_bodies set title = 'ENJOY TOBA BY FERRY - Ferry will make you a wonderful journey', description = 'Explore the remote island of Toba in Mie Prefecture, Japan, by ferry. The journey offers a unique opportunity to experience the beauty of Toba, including its hot springs and traditional Japanese inns. Accessing Toba is convenient, with travel options from Nagoya and Osaka via Kintetsu Limited Express. The trip from Nagoya takes about 1.5 hours, while from Osaka, it takes around 2 hours. For more information, you can visit the Kintetsu railway official website to purchase tickets. Additionally, resources are available for those interested in Japanese-style hotels and local tourism associations, providing insights into the rich culture and attractions of Toba.' where id = '409dmVtt6e2-UN6z7sNI2';
update content_bodies set title = '自転車で鳥羽を楽しもう！ーレンタル自転車ー', description = '三重県鳥羽市の観光スポットを自転車で巡りましょう。鳥羽の名物である大アワビやカキ、エビなどの海鮮を楽しむことができます。また、日本の温泉を体験し、公衆浴場の入り方を学ぶこともできます。宿泊には、伝統的な日本の旅館をおすすめします。鳥羽へのアクセスは、名古屋駅から近鉄特急で約1.5時間、大阪駅からは約2時間です。詳細は近鉄の公式ウェブサイトや鳥羽市観光協会のサイトを訪れてください。' where id = 'DKzwVVT-HEZsaPCId4Klg';
update content_bodies set title = 'Enjoy TOBA BY BICYCLE! - rental bicycle -', description = 'Explore the beautiful sights of Toba, Mie Prefecture in Japan by bicycle. Discover local attractions such as seafood delicacies, including giant abalones, oysters, and shrimps. Experience the relaxing Japanese hot springs and learn how to enter a public bath. For accommodation, consider staying at a traditional Japanese inn, which is highly recommended. Toba is easily accessible from Nagoya station in about 1.5 hours and from Osaka station in about 2 hours via Kintetsu Limited Express. For more information, visit the Kintetsu railway official website and the tourism association in Toba.' where id = 'K160rtDE_gWVuPkT40KN8';
update content_bodies set title = 'スパイニーロブスターと脂ののったサバ - 鳥羽のおすすめ料理', description = '三重県鳥羽市では、冬季限定のおすすめ料理が多数用意されています。特に注目すべきは、巨大アワビやカキ、エビなどの海産物です。また、伝統的な日本の温泉を楽しんだり、日本式の宿に宿泊する体験もできます。鳥羽へのアクセスは便利で、名古屋からは1.5時間、大阪からは2時間で近鉄特急を利用して訪れることができます。詳細については、近鉄の公式ウェブサイトや地元の観光協会を訪れてください。' where id = 'JAL8Dwah3cQv1dqaW_Rre';
update content_bodies set title = 'SPINY LOBSTER & FATTY SPANISH MACKEREL - Recommended dish in TOBA', description = 'Toba, located in Mie Prefecture, Japan, offers a variety of recommended dishes, particularly during the winter season. Notable seafood options include giant abalones, oysters, and shrimps. Visitors can also enjoy traditional Japanese hot springs and experience staying at a Japanese-style hotel. Access to Toba is convenient, with travel times of 1.5 hours from Nagoya and 2 hours from Osaka via Kintetsu Limited Express. For more information, you can visit the official Kintetsu railway website and local tourism associations.' where id = 'mZLeXPSuwQgOOQv1G-I-R';
update content_bodies set title = 'TOBA IS YOUR OYSTER（short.ver）', description = 'この動画は「TOBA IS YOUR OYSTER（short.ver）」の簡潔な紹介を行っており、その主要なテーマや内容を強調しています。' where id = '1lkWXxd8nfrQ_7ZuC3FcF';
update content_bodies set title = 'TOBA IS YOUR OYSTER (short.ver)', description = 'This video presents a brief introduction to ''TOBA IS YOUR OYSTER (short.ver)'', highlighting its key themes and content.' where id = 'vHcsose4GI00D3dfBDyrf';
update content_bodies set title = '東北の海岸から海岸へ：日本の隠れた魅力', description = '東北の海岸から海岸へのルートは、宮城県の太平洋沿岸と山形県の日本海沿岸を結び、両地域の美しい自然と文化、食の魅力を紹介するイメージ動画です。このルートでは、自然の中を歩き、地元の味を楽しみながら、日本の「深い北」の人々や文化とつながることができます。観光地から離れた本物の体験を求める旅行者にとって、理想的な目的地です。' where id = 'U3hCiJEiLbwu7LXDR10bs';
update content_bodies set title = 'Coast to Coast in Tohoku: Off the beaten track Japan', description = 'The coast-to-coast route in Tohoku connects the Pacific coast of Miyagi Prefecture with the Japan Sea coast of Yamagata Prefecture. This route highlights the stunning natural beauty of both coastal and mountainous regions, as well as the unique cultural and culinary experiences they offer. Travelers can immerse themselves in nature, enjoy local delicacies, and engage with the communities in Japan''s ''deep north'', making it a perfect destination for those seeking an authentic experience away from the usual tourist paths.' where id = 'vwHyamC3tj5cFUf6LhT3l';
update content_bodies set title = '2017年6月5日 霧多布湿原サンセットカヌー', description = '広く穏やかに流れる琵琶瀬川の静かな河口で、カヌーに乗りながら美しい夕日を眺める体験ができます。霧多布湿原ならではの「カヌーと夕日」の映像をお楽しみください。' where id = 'Pos-4uzfkuwgcoBfogte8';
update content_bodies set title = 'Sunset Canoeing at Kitahiroshima Wetlands on June 5, 2017', description = 'Experience the beauty of the sunset while canoeing on the calm and wide flowing Bibase River at its tranquil estuary. Enjoy the unique visuals of ''canoeing and sunset'' that can only be found in the Kitahiroshima Wetlands.' where id = 'DivKu24mpLiSwOxeRqYnt';
update content_bodies set title = '霧多布湿原 琵琶瀬川カヌー', description = '北海道の霧多布湿原を流れる琵琶瀬川でのカヌーツーリングです。穏やかに流れる湿原の川とその美しい風景を楽しむことができます。' where id = 'y-V7W-8zaS0JmDHhquyan';
update content_bodies set title = 'Canoeing on the Bibase River in the Kiritappu Wetland', description = 'This is a canoe touring experience on the Bibase River flowing through the Kiritappu Wetland in Hokkaido. Enjoy the serene flow of the wetland river and its beautiful scenery.' where id = 'Hwcr5ZuWprBNUSdSwp4Lb';
update content_bodies set title = '日本の田舎での一年間（後悔しているのか？）', description = '東京から日本の田舎に移住する決断は不安に満ちたものであり、過去一年間には多くの浮き沈みがありました。この要約では、季節の移り変わりがもたらした独自の生活の段階と、私たちの経験がどのように展開したかを振り返ります。春、夏、秋、冬の各季節がもたらした挑戦や喜びが、田舎での生活にどのように影響を与えたのかを考察し、最終的にこの移住が後悔すべきものだったのか、価値あるものだったのかを問いかけています。' where id = 'ZUKJglw1WzRI0m8EBj9ad';
update content_bodies set title = 'One Year Living in Japan’s Countryside (Do we regret it?)', description = 'The decision to move from Tokyo to the Japanese countryside was filled with uncertainty, leading to a year of various experiences. This recap highlights the changing seasons and their impact on life, detailing the ups and downs faced throughout the year. Each season brought unique challenges and joys, shaping the overall experience of living in the countryside. The narrative reflects on how these seasonal changes influenced daily life and personal growth, ultimately questioning whether the move was regrettable or rewarding.' where id = 'y_6IQroCN-MXyBVrHKTtS';
update content_bodies set title = '日本の田舎での春 🇯🇵 | 桜を追いかけました…それは価値がありましたか？', description = '桜は日本の春に欠かせない存在ですが、これまでこの季節に旅行することにあまり力を入れていませんでした。この動画では、身延久遠寺、富士市、高田城址公園、安曇野の4つの新しいスポットを訪れ、それぞれの独自の美しさを探求します。各地の桜の魅力を楽しみながら、田舎の春の風景を堪能する様子をお届けします。日本での体験を振り返りながら、これらの美しい場所を一緒に探検しましょう。' where id = 'tYvXutgf1ER8VAKkex870';
update content_bodies set title = 'Springtime in Countryside Japan 🇯🇵 | We Chased Cherry Blossoms... Was It Worth It?', description = 'In this video, we delve into the beauty of cherry blossoms, a quintessential aspect of spring in Japan. Previously, we hadn''t prioritized traveling during this season, but that changes now as we visit four distinct locations: Minobu Kuonji Temple, Fuji City, Takada Castle Site Park, and Azumino. Each site offers its own unique charm and scenic views, showcasing the splendor of cherry blossoms in the countryside. Join us as we explore these beautiful spots and reflect on our experiences in Japan.' where id = '7CVG1vQo2l6I7F3xilW83';
update content_bodies set title = '東京と京都を超えて：混雑の少ない日本の風景旅行プラン', description = 'この旅行プランは、東京や京都といった主要都市を超えて日本を探索したい旅行者のために設計されています。公共交通機関の利用が容易で、英語に対応した場所が含まれているため、日本を初めて訪れる方にも適しています。草津温泉、長野、松本、日本アルプス、高山、金沢、中仙道など、さまざまな目的地が含まれており、各地は独自の体験を提供しながら、大都市でよく見られる混雑を避けることができます。' where id = '5xvrEN1YlCDyNKPWJzqLz';
update content_bodies set title = 'Beyond Tokyo & Kyoto: A Scenic Japan Itinerary with Less Crowds', description = 'This itinerary is designed for travelers seeking to explore Japan beyond its major cities like Tokyo and Kyoto. It emphasizes accessibility via public transport and features English-friendly locations, making it suitable for first-time visitors. The itinerary includes various destinations such as Kusatsu Onsen, Nagano, Matsumoto, the Japanese Alps, Takayama, Kanazawa, and the Nakasendo Trail. Each location offers unique experiences while avoiding the crowds typically found in larger cities.' where id = 'SHaBPBH_dHCnQj5RhedNV';
update content_bodies set title = '日本の秘境の山の宿での一夜 - 電気はなく、ランプだけ', description = '青森県の山中に位置するランプイン青荷温泉は、石油ランプだけで照らされる秘境の温泉宿です。ここでは電気も携帯電話の電波もなく、静かで穏やかな雰囲気が漂います。動画では宿への旅の様子、歴史や温泉の紹介、夕食や朝食の詳細が紹介されています。また、地元の方言である津軽弁についても触れられており、この隠れた場所での文化体験が一層深まります。' where id = 'q5smQ_yHtkE74s45llbZy';
update content_bodies set title = 'A Night in Japan’s Remote Mountain Inn – No Electricity, Just Lamps', description = 'Lamp Inn Aoni Onsen, located in the mountains of Aomori Prefecture, offers a unique experience as a remote hot spring inn illuminated solely by kerosene lamps. Visitors will find no electricity or cell phone reception, creating a serene and tranquil atmosphere. The video includes a travel journey to the inn, insights into its history and onsen baths, and details about dinner and breakfast. Additionally, it features a glimpse into the local dialect, Tsugaru-ben, enhancing the cultural experience of staying in this secluded location.' where id = 'z4tOixoEGXV-fmPK6XLTX';
update content_bodies set title = '世界一雪の多い街での24時間', description = '日本に位置する青森市は、年間約8メートルの雪が降る世界一雪の多い街として知られています。この動画では、青森の冬の旅を紹介し、八甲田山や弘前雪灯籠祭り、地元の料理を楽しむ様子が描かれています。雪の中でのバンライフや、古川魚市場の訪問を通じて、独特の冬のライフスタイルを体験できます。また、青森のアップルパイも登場し、地域の食文化が強調されています。' where id = 'YAKtBaTQmH-Zws7FyhOaI';
update content_bodies set title = '24 Hours in the World''s Snowiest City', description = 'Aomori city, located in Japan, is recognized as the snowiest city in the world, receiving approximately 8 meters of snow annually. This video showcases a winter journey through Aomori, highlighting attractions such as the Hakkoda mountains, the Hirosaki Snow Lantern Festival, and local culinary delights. Viewers can experience the unique winter lifestyle, including van life in snowy conditions and a visit to the Furukawa Fish Market. The video also features a delicious Aomori apple pie, emphasizing the region''s local food culture.' where id = 'odhtxINJll0uIrzCT_KuX';
update content_bodies set title = '日本の山小屋での一夜', description = 'この短い冬のハイキングは、日本の山の小屋へのもので、寒い冬の日を過ごす素晴らしい方法となりました。' where id = 'kZyHNL8WR1cDD8q_-Xxj0';
update content_bodies set title = 'Overnight in a Cozy Mountain Hut in Japan', description = 'This short winter hike to a hut in the Japanese mountains offered a delightful way to enjoy a cold winter''s day.' where id = 'rDuud4U1hl8ddFWv3LoDN';
update content_bodies set title = '日本の田舎で過ごす静かな冬の日', description = '寒い冬の週末に日本の田舎で行われる新年の伝統を体験します。動画では、「お土産」や「書き初め」、「初詣」といった様々な習慣を紹介します。また、2025年に向けた私たちの目標や、今後の展望についても触れています。さらに、日本の無人・キャッシャーレスショップのユニークな体験についても語り、田舎の生活における伝統と現代性の融合を示しています。' where id = 'ZJeHfdpWy8-jdta8zwRdH';
update content_bodies set title = 'A Quiet Winter’s Day Living in Japan’s Countryside', description = 'Join us as we explore Japanese New Year traditions during a chilly winter weekend in the countryside. The video highlights various customs, including ''Omiyage'' (souvenirs), ''Kakizome'' (first calligraphy of the year), and ''Hatsumode'' (the first shrine visit). We also share our aspirations for 2025 and provide glimpses of what''s to come. Additionally, we discuss the unique experience of unmanned, cashierless shops in Japan, showcasing the blend of tradition and modernity in rural life.' where id = '0wVyg1P7csDyjDoAT38dw';
update content_bodies set title = '「日本のエーゲ海」牛窓・前島シーカヤックツアー（瀬戸内市）', description = '岡山県で今注目されている体験やツアーを厳選して紹介しています。臨場感あふれる体験レポートや、予約・申し込みに関する情報も掲載されています。' where id = 'erWmIz7vwvZwTG-bgmo6c';
update content_bodies set title = 'Kayaking Tour in Ushimado and Maejima: The ''Aegean Sea of Japan'' (Setouchi City)', description = 'This article introduces selected experiences and tours that are currently popular in Okayama Prefecture. It provides immersive experience reports along with information on reservations and applications.' where id = '-bjWDuWUQTaeCoRB_mQ5u';
update content_bodies set title = 'KANAGAWA LU-LU-LUN♪ - 三浦半島エリアに移動~', description = '「KANAGAWA LU-LU-LUN♪」は、神奈川県の旅行体験を紹介し、心躍るような楽しさを提供します。三浦半島エリアでは、相模湾と富士山が夕焼けに染まる美しい景色を楽しむことができます。この動画では、横須賀美術館、猿島、千代ヶ崎砲台跡、長井海の手公園ソレイユの丘、三崎のマグロ、京急オープントップバス三浦、そして城ヶ島などの地元の美味しい料理やフォトジェニックなスポットが紹介されています。神奈川県の旅行情報については、提供されたリンクから東京の日帰り旅行ガイドを参照できます。この動画に関するお問い合わせは、観光課へのお問い合わせフォームを利用するように促されています。' where id = 'rm1P2-fD9jX5K2dGiERUb';
update content_bodies set title = 'KANAGAWA LU-LU-LUN♪ - Moved in Miura Peninsula area~', description = 'KANAGAWA LU-LU-LUN♪ highlights the best travel experiences in Kanagawa, designed to evoke joy and excitement. In the Miura Peninsula area, visitors can enjoy breathtaking views where Sagami Bay meets Mt. Fuji, especially during sunset. The video showcases local delicacies and picturesque spots, including the Yokosuka Museum of Art, Sarushima, Chiyogasaki Gun Battery Site, Nagai Umite Park, Soleil Hill, Misaki Tuna, and the Keikyu Open Top Bus Miura. Additionally, Jogashima is featured as a must-visit location. For more travel information about Kanagawa, a Tokyo day trip guide is available at the provided link. For inquiries regarding the video, viewers are encouraged to use the contact form for the tourism department.' where id = '-_8TOY4nnwmvI3ooddIl6';
update content_bodies set title = '究極の日本のBBQ対決 - 山梨でのキャンプ @KonnichiwaMyDudeと共に', description = 'この動画では、山梨での夏のBBQ対決を紹介し、キャンプとアウトドア料理の楽しさを強調しています。冒険は食材の買い出しから始まり、続いてエキサイティングなBBQチャレンジが行われます。さらに、雄大な大柳川渓谷を散策することで、料理の競技と自然探検が見事に融合した体験が楽しめます。' where id = 'T9T1mCz5W52zZdCpD3HC6';
update content_bodies set title = 'Ultimate JAPANESE BBQ Cookoff - Camping in Yamanashi, Japan w/@KonnichiwaMyDude', description = 'This video showcases a summer BBQ competition in Yamanashi, Japan, highlighting the joys of camping and outdoor cooking. The adventure begins with shopping for ingredients, followed by an exciting BBQ challenge. The experience is enriched with a scenic walk through Oyanagawa Gorge, making it a perfect blend of culinary competition and nature exploration.' where id = 'OlZztA3G0-HoQGKQtovS_';
update content_bodies set title = '日本の学校での宿泊（温泉プール付き！）', description = '日本には廃墟が多く存在しますが、静岡の古い小学校がホテルに生まれ変わり、温泉プールが併設されています。この動画では、ユニークな宿泊施設の様々な側面を探ります。近くの古い天城トンネルや、学校の環境での宿泊体験、伝統的な日本食や地元の酒などのアメニティについて紹介されています。この再利用された学校の魅力と周辺の観光スポットを発見することができる、興味深い旅行先です。' where id = '0uquuoaZ3drO5pMVrukat';
update content_bodies set title = 'Sleeping in a Japanese School (With Onsen Pool!)', description = 'In Japan, abandoned buildings are common, but an old elementary school in Shizuoka has been transformed into a unique hotel featuring an onsen pool. The video explores various aspects of this unusual accommodation, including the nearby Old Amagi Tunnel, the experience of staying in a school setting, and the amenities offered, such as traditional Japanese meals and local sake. Viewers are invited to discover the charm of this repurposed school and the surrounding attractions, making it an interesting travel destination.' where id = '4gKMNq2Srtwhw9tDBlEuA';
update content_bodies set title = '西日本最高峰の山をハイキング（大山、鳥取）', description = '鳥取県にある大山は、日本の名山100選の一つであり、私たちは予想外に雪や氷の条件に出くわしました。この山は美しい景色とユニークなハイキング体験を提供し、アウトドア愛好者にとって人気のある目的地となっています。' where id = 'oU9iiGtCIO_ystp_0mruq';
update content_bodies set title = 'Hiking Western Japan''s Tallest Mountain (Mt. Daisen, Tottori)', description = 'Mt. Daisen, located in Tottori, Japan, is recognized as one of the country''s 100 famous mountains. During our hike, we encountered unexpected snowy and icy conditions, adding an element of surprise to our adventure. This mountain offers stunning views and a unique hiking experience, making it a popular destination for outdoor enthusiasts.' where id = 'nRS4dcUDQ76WxZLHA_hvn';
update content_bodies set title = '「かながわ　るるるん♪」溢れる。箱根エリア（ロングバージョン）', description = '心を動かし、思わず口ずさみたくなる旅「かながわ　るるるん♪」の紹介です。箱根エリアは日本有数の温泉湧出量を誇り、大地のエネルギーに満ちた魅力的な場所です。訪れる人々は温泉や歴史、文化、食を通じて心が喜びで「溢れる。」体験ができます。紹介されている場所には、cu-mo 箱根、箱根ロープウェイ、小田原漁港、小田原おさかな通り、江之浦測候所、彫刻の森美術館、箱根神社、仙石原すすき草原、宮城野の桜、箱根十七湯が含まれています。情報は令和6年3月時点のもので、変更される可能性があるため、最新情報は公式サイトで確認してください。' where id = 's3WqaXh7bC46Lsu2_SaLd';
update content_bodies set title = 'Overflowing ''Kanagawa Rururun♪'' - Hakone Area (Long Version)', description = 'The journey ''Kanagawa Rururun♪'' is designed to move your heart and make you want to hum along. This introduction highlights the abundant attractions of the Kanagawa region, particularly the Hakone area, known for its rich hot spring resources and vibrant energy from the earth. Visitors can experience the joy of the region through its hot springs, history, culture, and cuisine, all centered around the theme of overflowing happiness. Featured locations include cu-mo Hakone, Hakone Ropeway, Odawara Fishing Port, Odawara Fish Street, Enoura Observatory, Hakone Open-Air Museum, Hakone Shrine, Sengokuhara Susuki Grassland, Miyagino Cherry Blossoms, and Hakone Seventeen Springs. Please note that the information is accurate as of March 2024 and may change; check official sites for the latest updates.' where id = 'rCS1V4k3PiTpfHKhUD29e';
update content_bodies set title = '日本旅行、一週間のホテルなしチャレンジ - 無料キャンプと車中泊', description = 'ゴールデンウィークは日本で最も混雑する休日の一つであり、予算を抑えた旅行の方法として無料キャンプと車中泊に挑戦することにしました。この動画では、鳥取でのキャンプや鳥取砂丘の探索、マンガカフェの訪問など、さまざまなアクティビティが紹介されています。また、姫路での観光やコンビニでの夕食、道の駅での車中泊体験も取り上げられています。視聴者にはInstagramでの交流を促し、日本の無料キャンプや温泉に関するリソースへのリンクも提供されています。' where id = '6AvitwU6x9agTvUokFcjD';
update content_bodies set title = 'Japan Travel, One Week NO HOTEL CHALLENGE - Free Camping and Car Camping', description = 'During Japan''s Golden Week, a peak holiday season, the creators embark on a budget-friendly adventure by engaging in free camping and car camping. The video showcases various activities, including camping in Tottori, exploring the Tottori Sand Dunes, and visiting a manga cafe. It also highlights sightseeing in Himeji, enjoying convenience store dinners, and experiencing car camping at a roadside station. The creators encourage viewers to connect with them on Instagram and provide links to resources for free camping and hot springs in Japan.' where id = '72YERTAWZ4Gzm0fJfA__N';
update content_bodies set title = '日本で最も危険な寺院をハイキングしました', description = '日本で最も危険な寺院は本当に危険で、一部のハイカーはヘリコプターで救助される必要があります。単独での訪問や適切な靴を履いていない場合は、登山が許可されません。しかし、準備が整った人にとっては、旅と頂上からの景色は素晴らしいものです。' where id = 'V0TVxn0YcXkB0NMAamOyo';
update content_bodies set title = 'We Hiked Japan''s MOST DANGEROUS Temple', description = 'Japan''s most dangerous temple presents significant challenges for hikers, with some requiring helicopter rescues. Solo hikers or those without appropriate footwear are not permitted to attempt the hike. However, for those who are prepared, the trek offers breathtaking views and a rewarding experience at the summit.' where id = 'fB8PUaB6M8Be7OTxkX-mT';
update content_bodies set title = '群馬県の本物の「千と千尋の神隠し」の温泉を訪れる', description = '群馬県の嬬恋温泉は、スタジオジブリの映画「千と千尋の神隠し」にインスパイアされた実在の場所です。この動画では、温泉街のツアーが紹介され、私たちが宿泊した関善館やプライベート温泉の体験が語られています。また、群馬の名物である豚カツを味わい、日本の和菓子である揚げ饅頭やメロディー道路についても触れています。旅行情報や宿泊先のリンクも提供されており、舞台裏コンテンツのためのSNSの接続もあります。' where id = 'y1KKOtN9Iw9NZPIrfq94A';
update content_bodies set title = 'Visiting the REAL SPIRITED AWAY ONSEN in Gunma, Japan', description = 'Shima Onsen in Gunma, Japan, is a real-life location that inspired Studio Ghibli''s film ''Spirited Away.'' The video showcases a tour of the onsen town, highlighting the Sekizenkan onsen, where visitors can enjoy a private bath. Additionally, the hosts sample local cuisine, specifically Gunma''s specialty, pork tonkatsu. The video also features Japanese sweets called agemanju and discusses Japan''s unique melody roads. For more information, links to accommodations and travel details are provided, along with social media connections for behind-the-scenes content.' where id = '0T1CbNJjuVhJ6U3F-ZAtF';
update content_bodies set title = '日本の餃子祭りに行ってきました', description = '私たちは日本の餃子祭りに参加し、31種類の餃子を楽しみました。たくさんの餃子を食べる中で、食の楽しさを満喫しました。祭りの後は、古い日本の宿場町である馬籠宿に一泊しました。この旅では、餃子チャレンジや地元の川沿いのレストランでの食事など、さまざまなアクティビティを体験しました。この冒険は、私たちの味覚を満たすだけでなく、日本の古い町の魅力を探る機会にもなりました。' where id = 'gcKMqSVKNsuh7ROhpq9y5';
update content_bodies set title = 'We Went to Japan''s DUMPLING Festival', description = 'We attended a dumpling festival in Japan featuring 31 different varieties of gyoza. The experience was filled with delicious food as we indulged in numerous dumplings. After the festival, we spent the night in Magome-Juku, a historic post-town that showcases traditional Japanese culture. The trip included various activities, such as a gyoza challenge and dining at a local river restaurant. This adventure not only satisfied our taste buds but also allowed us to explore the charm of Japan''s old towns.' where id = '5vd9NVZFSuSxbtoK9aduz';
update content_bodies set title = '東京でのソフトウェアエンジニアと英語教師の生活', description = 'この動画では、東京で生活するソフトウェアエンジニアと英語教師の日常を紹介しています。普段は旅行の様子をシェアしているカップルですが、今回は日常生活を記録することにしました。動画には、朝のルーティン、テニスをする様子、シェアハウスでの生活、ソフトウェアエンジニアとしての仕事、英語教師としての仕事などが含まれています。また、昼食の時間、午後5時のチャイム、地震警報、夕食の時間など、東京での生活の一端を垣間見ることができます。' where id = '2xFLuTnsnxdvixSBBz3or';
update content_bodies set title = 'Life in Tokyo as a Software Engineer and English Teacher', description = 'This video showcases the daily life of a software engineer and an English teacher living in Tokyo, Japan. While the couple usually shares their travel experiences, they decided to document their everyday routines as well. The video includes segments on their morning routine, playing tennis, living in a share house, and their respective jobs as a software engineer and an English teacher. It also features moments like lunchtime, the 5 PM chime, an earthquake alarm, and dinner time, providing a glimpse into their life in the bustling city of Tokyo.' where id = 'iWwBhVLiYk5p8lMRaeSNE';
update content_bodies set title = '日本の侍の町 - 福島県会津若松の冬の旅行', description = '福島県は美しい冬の旅行先として知られていますが、特に侍の町である会津若松は魅力的です。ここでは、鶴ヶ城を探索したり、温泉町の心地よい雰囲気を楽しんだり、日本で最もユニークな寺院の一つである佐賀堂を訪れたりできます。宿泊施設には、田ごとの料理宿や東山パークホテル、より高級な向滝温泉があります。この旅行ガイドでは、会津若松の地元料理、歴史的な名所、文化体験を紹介し、冬の季節に訪れるべき場所であることを強調しています。' where id = 'Tj9-_Zhz7cYm9s9KYbDMG';
update content_bodies set title = 'Japan''s SAMURAI TOWN - Winter Travel in Aizuwakamatsu, Fukushima', description = 'Fukushima, Japan, is a beautiful winter travel destination, particularly the samurai town of Aizuwakamatsu. Visitors can explore Tsuruga Castle, enjoy the cozy atmosphere of an onsen town, and visit one of Japan''s most unique temples, Sazaedo. The area offers various accommodations, including the Tagoto Cuisine Inn and the Higashiyama Park Hotel, as well as the more luxurious Mukaitaki Onsen. This travel guide highlights the local cuisine, historical sites, and cultural experiences that make Aizuwakamatsu a must-visit during the winter season.' where id = '1O-ps5FUUV-_6aSmGis5s';
update content_bodies set title = '日本の廃線をサイクリング - 高山、岐阜', description = '日本には多くの廃墟がありますが、この田舎町は廃線をサイクリング観光地に変える素晴らしいアイデアを持っています。この動画では、視聴者を日本の美しい田園風景をサイクリングしながら、飛騨牛を味わい、高山の古い町を訪れる旅に招待します。体験には、レールバイクに乗ること、高山の古い町を訪れること、そして飛騨民俗村を探索することが含まれ、地域の豊かな文化と歴史を紹介しています。' where id = '27aqi0tb4-qejRTfwrGRl';
update content_bodies set title = 'We Cycled an ABANDONED Railway in Japan - Takayama, Gifu', description = 'In Japan, many abandoned places exist, but a countryside town has creatively transformed an abandoned railway into a cycling tourist attraction. This video invites viewers to join a cycling journey through the picturesque Japanese countryside, where they can enjoy local delicacies like Hida beef and explore the historic old town of Takayama. The experience includes riding a rail bike, visiting Takayama''s old town, and exploring the Hida Folk Village, showcasing the region''s rich culture and history.' where id = '1xY7FKyWh8aPkyxE2hLKj';
update content_bodies set title = '草津温泉、寺院とハイキング - 群馬のトップ観光地！', description = '草津温泉は日本で最も人気のある温泉地の一つです。この24時間の旅では、群馬県の神秘的な寺院、美しい温泉、そして山登りを楽しむことができます。旅程には、駒ヶ根の大手門、停車場ガーデン、釈尊寺、そして有名な草津温泉が含まれ、最後には四阿屋山のハイキングが待っています。群馬のトップ観光地を一緒に探訪しましょう！' where id = 'tpUeNKHzJn0yCP5RmnJsn';
update content_bodies set title = 'Kusatsu Onsen, temples and hiking - Gunma Japan''s TOP destinations!', description = 'Kusatsu Onsen is a renowned onsen area in Japan, attracting many visitors. This 24-hour journey through Gunma showcases various attractions, including mysterious temples, stunning onsens, and a mountain hike. The itinerary features stops at Komoro Otemon, Teishaba Garden, Shakusonji Temple, and the famous Kusatsu Onsen, culminating with a hike up Azumayasan. Join us to explore these top destinations in Gunma!' where id = '-8i6XUhlgakd91SfE-af-';
update content_bodies set title = '谷川岳登山 - 日本の百名山', description = '谷川岳は群馬県に位置し、日本の百名山の一つとして知られています。美しい景色が広がる素晴らしい日帰りハイキングが楽しめます。さらに、山の途中までロープウェイを利用できるため、ハイカーにとって魅力的な体験となっています。' where id = 'hfNkmR39DJCfRTi7WyCc2';
update content_bodies set title = 'Hiking Mt. Tanigawa - Japan''s 100 Famous Mountains', description = 'Mt. Tanigawa, located in Gunma, Japan, is recognized as one of Japan''s 100 Famous Mountains. It offers an excellent day hike with stunning scenery. A unique feature of this hike is the availability of a ropeway that takes you partway up the mountain, enhancing the experience for hikers.' where id = 'zBCyyvdIgxs-lix82Fn2Z';
update content_bodies set title = '「かながわ　るるるん♪」夢見る。横浜・川崎エリア（ロングバージョン）', description = '心を動かされ、思わず口ずさんでしまいたくなる旅「かながわ　るるるん♪」は、夢見る要素が満載の神奈川の旅を紹介します。横浜・川崎エリアには、誰もが「夢見る。」ことができる魅力があり、全体がアミューズメントパークのような雰囲気です。紹介されているスポットには、YOKOHAMA AIR CABIN、MARINE&WALK YOKOHAMA、横浜赤レンガ倉庫、山下公園、大さん橋、横浜中華街、横浜イングリッシュガーデン、生田緑地、川崎市岡本太郎美術館、川崎市立日本民家園、工場夜景、川崎大師、川崎市制記念多摩川花火大会などがあります。情報は令和6年3月時点のもので、変更される可能性があるため、最新情報は公式サイトで確認してください。' where id = '41icdOFrMBDMizRJjKO0W';
update content_bodies set title = 'Kanagawa Rururun♪: Dreaming in Yokohama and Kawasaki Area (Long Version)', description = 'The journey ''Kanagawa Rururun♪'' is designed to move your heart and make you want to hum along. This introduction showcases a travel experience filled with ''ru'' in Kanagawa. The Yokohama and Kawasaki area is a place where all elements of dreaming exist, allowing everyone to ''dream.'' The video highlights attractions that make this area feel like an amusement park, including YOKOHAMA AIR CABIN, MARINE&WALK YOKOHAMA, Yokohama Red Brick Warehouse, Yamashita Park, Osanbashi, Yokohama Chinatown, Yokohama English Garden, Ikuta Ryokuchi, Kawasaki City Taro Okamoto Museum of Art, Kawasaki City Japanese Farmhouse Museum, factory night views, Kawasaki Daishi, and the Kawasaki City Tamagawa Fireworks Festival. Please check the official sites for the latest information as details may change.' where id = 'J-a-OdRUKsOIlA8A6WQfy';
update content_bodies set title = 'かながわ　るるるん♪　全県版', description = '心を動かされ、思わず口ずさんでしまいたくなる旅「かながわ　るるるん♪」は、神奈川県の魅力を紹介するガイドです。このダイジェスト版では、神奈川県の7つのエリアの魅力をまとめています。情報は令和6年3月時点のもので、変更されている可能性がありますので、最新情報は公式サイトでご確認ください。紹介されているエリアは、横浜・川崎、箱根、湘南、丹沢大山、相模湖・相模川流域、三浦半島、足柄の7つです。それぞれのエリアには、魅力を伝える動画へのリンクもあります。詳細は神奈川県の公式観光サイトをご覧ください。' where id = 'Vw8BA6LfQv6r3Ge_oGWov';
update content_bodies set title = 'Kanagawa Rururun♪ All Prefecture Edition', description = 'Experience the captivating journey of ''Kanagawa Rururun♪'', a travel guide filled with the charm of Kanagawa. This digest version highlights the attractions of seven areas in Kanagawa Prefecture. Please note that the information is accurate as of March 2024 and may have changed. For the latest updates, check the official websites. The seven areas featured include: Yokohama-Kawasaki, Hakone, Shonan, Tanzawa-Oyama, Sagamiko-Sagamigawa, Miura Peninsula, and Ashigara. Each area is linked to videos showcasing its unique offerings. For more information, visit the official Kanagawa tourism site.' where id = 'goZvSHswYBR9Vn5COnjDd';
update content_bodies set title = '日本のグランピング - 新潟の田舎キャンプ', description = '日本ではグランピングが非常に人気で、特に有名なキャンプスポットは数ヶ月前から予約でいっぱいです。私たちは新潟に旅行し、田舎でリラックスした一夜を過ごしました。グランピングは自然の美しさと快適さを兼ね備えたユニークなキャンプスタイルで、リラックスして心身を癒す理想的な getaway です。' where id = 'zJq-s95QolOHmDgIXaLB2';
update content_bodies set title = 'Glamping in Japan - Countryside Camping in Niigata', description = 'Glamping has gained immense popularity in Japan, with many sought-after camping locations fully booked months in advance. Our recent trip took us to Niigata, where we enjoyed a peaceful night in the countryside, experiencing the charm of glamping. This unique form of camping combines the beauty of nature with the comforts of home, making it an ideal getaway for those looking to relax and unwind.' where id = 'xUr6zn-zEJfRh49YRz_04';
update content_bodies set title = '山梨県のハイキング - 秩父国立公園', description = '東京近郊に位置する秩父国立公園は、都市を離れ自然の中で過ごすのに最適な場所です。この公園では、特に西沢渓谷のハイキングが人気で、日本の名水百選に選ばれた滝が点在しています。美しい風景とハイキングの機会を提供するこの場所は、都市に近いながらもアウトドアの美しさを楽しみたい人々にとって理想的な目的地です。' where id = 'R5g756A1mB9iwiN31rBKI';
update content_bodies set title = 'Hiking in Yamanashi, Japan - Chichibu National Park', description = 'Chichibu National Park, located near Tokyo, offers a serene escape into nature. The park is known for its stunning landscapes and hiking opportunities, particularly the Nishizawa Valley trail. This hike features several waterfalls, including some that are listed among Japan''s top 100 waterfalls. It''s an ideal destination for those looking to enjoy the beauty of the outdoors while being close to the city.' where id = 'l6TmcB8pyhL-Xp08pUaP3';
update content_bodies set title = 'この幸せをずっと、福井で', description = '「福井」と呼ばれる場所をご存知ですか？福井は日本一の幸福度を誇る地域です。福井に移住したばかりのカップルが、日々の生活を通じてその幸福の意味を少しずつ見出していきます。説明には、東尋坊や水島、大野城など、福井の美しい観光スポットが紹介されています。カップルの体験を通じて、福井が特別な場所である理由が描かれています。このプロジェクトは、日常の思い出を発信し、福井を広めることを目的とした映像クリエイターチーム「Aithra」によるものです。' where id = 'YOEgk73ukZ8KI5hK3P2Vq';
update content_bodies set title = 'Finding Happiness in Fukui', description = 'Have you heard of a place called Fukui? This region is known for having the highest happiness level in Japan. A couple who recently moved to Fukui gradually discovers the meaning of this happiness as they go about their daily lives. The description also highlights various scenic spots in Fukui, such as Tojinbo, Mizushima, and Ono Castle, among others. The couple''s journey is documented through their experiences and the beauty of the region, showcasing why Fukui is a special place to live. The project is part of a larger initiative by Aithra, a video creator team that aims to share daily memories and promote Fukui through various media.' where id = 'uBRUTpwKaJuQZFIa7cToD';
update content_bodies set title = '新幹線で行けるハワイ？どこにあるの？', description = 'まるで本物のハワイのような美しいビーチが楽しめます。海外旅行も良いですが、国内で最高のビーチを堪能するのはいかがでしょうか？撮影場所は水島です。' where id = 'hHRk3np32VELgnUD6UonD';
update content_bodies set title = 'Hawaii Accessible by Shinkansen? Where is it?', description = 'Experience a beautiful beach that feels just like Hawaii. While overseas travel is great, why not enjoy the best beaches right here in Japan? The filming location is Mizushima.' where id = 'C7oG6alox4njnVch7FBwg';
update content_bodies set title = '美しさに満ちた村、ミサト【360VR】', description = 'この紹介は、徳島の村ミサトの独自の「地域資源」、つまり食、風景、伝統的なイベントに焦点を当てています。地域資源を活用した農泊や都市と農村の交流を促進する方法について説明しています。地域の美しさや魅力を強調し、訪問者に地元の文化や環境を探求し、楽しむことを促しています。' where id = 'qABit6SJvmGC-OD7YAZG2';
update content_bodies set title = 'Misato, a Village Filled with Beauty【360VR】', description = 'This introduction highlights the unique local resources of Misato, a village in Tokushima, including its food, landscapes, and traditional events. The focus is on how these resources are utilized for farm stays and fostering interactions between urban and rural areas. The description emphasizes the beauty and attractions of the region, encouraging visitors to explore and appreciate the local culture and environment.' where id = 'XP52FKjA6HysQ3H9_tiS8';
update content_bodies set title = '風の中の空に近い村、フチミョ【360VR】［徳島］', description = 'この動画では、食材や風景、伝統行事など、地域特有の「地元資源」を活用し、農泊や都市と農村の交流を促進する取り組みを紹介するフチミョ村の魅力を紹介しています。徳島の自然の美しさや文化遺産を探求することを促す内容となっており、地域の魅力を広めることを目的としています。' where id = 'isbhmA2e4BvKWk5shy3gu';
update content_bodies set title = 'Fuchimyo, a village close to the sky in the breeze【360VR】［Tokushima］', description = 'This video introduces Fuchimyo, a village that showcases unique local resources such as food, landscapes, and traditional events. It highlights the region''s efforts to utilize these resources for farm stays and to foster interaction between urban and rural areas. The video aims to promote the attractions of Tokushima and encourage visitors to explore its natural beauty and cultural heritage.' where id = 'H5c78yvMQDPOXlAvAWNDQ';
update content_bodies set title = '善入寺島、阿波野菜の宝庫【360VR】', description = 'このコンテンツは、地域ごとに特有の「地域資源」、つまり食べ物や風景、伝統的なイベントを紹介しています。地域資源を活用した農泊や都市と農村の交流を促進する地域の魅力を紹介するものです。善入寺島とその阿波野菜の美しさや魅力を映し出し、地域文化と農業の重要性を強調しています。' where id = 'SWVUts6-8wvpPc457YyPm';
update content_bodies set title = 'Zennyuji Island, a Treasure Trove of Awa Veggies【360VR】', description = 'This content highlights the unique ''local resources'' of various regions, including food, landscapes, and traditional events. It serves as an introduction to the attractions of areas that are leveraging their local resources for farm stays and fostering interactions between urban and rural communities. The video showcases the beauty and charm of Zennyuji Island and its Awa vegetables, emphasizing the importance of local culture and agriculture.' where id = '9JfWQx6Xd9KTgV7s01358';
update content_bodies set title = '日本のドライブ体験 - 日本での旅行のためのレンタカー', description = '日本でレンタカーを利用することで、都市を離れ、美しい田舎を探索することができます。静岡県の伊豆スカイラインは、日本で最も素晴らしいドライブの一つとされており、絶景を楽しむことができます。また、城連の滝は日本の自然の美しさを示す必見のスポットです。この記事では、日本での運転に関する便利なヒントや、通行料、ガソリンスタンドについての情報も提供されており、スムーズな旅行体験をサポートします。全体として、このガイドは車で日本を探索する楽しみを高めることを目的としています。' where id = '8MO7cydFu2496RCHNLY00';
update content_bodies set title = 'The Japan Driving Experience - Renting a Car for Travel in Japan', description = 'Renting a car in Japan allows travelers to escape the urban environment and discover the stunning countryside. The Izu Skyline in Shizuoka is highlighted as one of the best scenic drives in the country, offering breathtaking views. Additionally, Joren Falls is a must-visit destination, showcasing Japan''s natural beauty. The content provides useful tips for driving in Japan, including information about tolls and petrol stations, ensuring a smooth travel experience. Overall, this guide aims to enhance the enjoyment of exploring Japan by car.' where id = '58WJf_KTmp0Fgx_mJ5O-T';
update content_bodies set title = '日本の温泉テーマパークに行ってきました', description = '群馬県には、18種類の温泉が楽しめる旅館があり、プライベートでリラックスできる場所です。このユニークな目的地では、訪れる人々がそれぞれ異なる体験を提供する温泉でくつろぐことができます。旅館は、静けさを求める人や日本の伝統文化を味わいたい人にとって理想的なスポットです。また、近くには榛名神社やアシマカフェレストランなどの観光名所もあり、地域の旅行体験をさらに充実させています。' where id = '-7GbVJfELsW2Nnvo9OfFP';
update content_bodies set title = 'We Went to Japan''s ONSEN THEME PARK', description = 'In Gunma, Japan, there is a ryokan featuring 18 different onsen for private relaxation. This unique destination offers visitors a chance to unwind in various hot springs, each providing a distinct experience. The ryokan is an ideal spot for those seeking tranquility and a taste of traditional Japanese culture. Additionally, nearby attractions include Haruna Shrine and Asima Cafe Restaurant, enhancing the overall travel experience in the region.' where id = 'EXxsQRZpiEB9zi24RfZgA';
update content_bodies set title = '東京近くのプライベート温泉 - 箱根、日本', description = '箱根は東京から近い美しい温泉町で、日帰り旅行に最適な場所です。特に、箱根湯寮温泉はリラックスしたい訪問者に強くおすすめされます。また、近くの小田原には小田原城や人気のあるおでん屋もあり、旅行体験をさらに充実させてくれます。' where id = 'ydfKa4fTNJDix36TSIkJP';
update content_bodies set title = 'Private Onsen Near Tokyo - Hakone, Japan', description = 'Hakone is a beautiful hot spring town located close to Tokyo, making it an ideal destination for a day trip. The Hakone Yuryo Onsen is highly recommended for visitors seeking a relaxing experience. Additionally, nearby Odawara offers attractions such as Odawara Castle and a popular oden restaurant, enhancing the overall travel experience.' where id = 'QJkFNqjx0TB2pWyf01rfL';
update content_bodies set title = '神奈川県での日本のBBQとキャンプ', description = '夏の日本でのキャンプは素晴らしい体験であり、BBQや花火を楽しむことを忘れないでください。神奈川県にある新堂キャンプ場は、テントサイトが1人あたり1泊1500円、車1台あたり1泊500円です。自然の美しさを楽しみながら、伝統的な日本のBBQを堪能したいアウトドア愛好者にとって、素晴らしいスポットです。' where id = 'QF7Lb1Jf55ZjcPMmpP7Ig';
update content_bodies set title = 'Japanese BBQ and Camping in Kanagawa, Japan', description = 'Camping in Japan during the summer offers a wonderful experience, especially with BBQ and fireworks. The Shindo campground, located in Kanagawa prefecture, charges ¥1500 per person per night for a tent site and ¥500 per car per night. It''s a great spot for outdoor enthusiasts looking to enjoy the beauty of nature while indulging in traditional Japanese BBQ.' where id = '33J43x-_6kqYnligZ88dK';
update content_bodies set title = '徳島の輝く村の宝物【360VR】', description = 'この動画は、360VRシリーズのダイジェストであり、徳島の村々の美しさと魅力を紹介しています。特に、絶景で知られる美郷、空に近いユニークな体験を提供する風知妙、そして阿波野菜の豊富な種類で称賛される善入寺島の3つの場所に焦点を当てています。この動画は、視聴者にこれらの宝物を探求するよう促し、関連動画や徳島を訪れる際の観光情報へのリンクも提供しています。' where id = 'zPi3V-1kqYP9Yldy9eSn1';
update content_bodies set title = 'Tokushima’s Sparkling Village Treasures【360VR】', description = 'This video serves as a digest of the 360VR series, showcasing the beauty and charm of Tokushima''s villages. It highlights three specific locations: Misato, known for its stunning scenery; Fuchimyo, a village that offers a unique experience close to the sky; and Zennyuji Island, celebrated for its rich variety of Awa vegetables. The video invites viewers to explore these treasures and provides links to related videos and tourist information for those interested in visiting Tokushima.' where id = 'l_Wo1r3EA-mwzphCGJ-Oq';
update content_bodies set title = '日本の野湯 - 長野の川温泉', description = '日本は温泉文化で知られていますが、全国には野湯も点在しています。私たちは長野県の川温泉を訪れ、素晴らしい体験をしました！' where id = 'iCbntwmP5UG2OEAt1FbAz';
update content_bodies set title = 'Wild Onsen in Japan - Nagano''s River Hot Spring', description = 'Japan is famous for its onsen culture, but there are also wild onsens scattered throughout the country. We explored a river hot spring in Nagano prefecture and had an amazing experience!' where id = '4s_gwRdY4X1uijO3Hw9mT';
update content_bodies set title = '珠洲市観光ＰＲ動画（食と人）', description = '珠洲市観光PR動画特設サイトでは、地域の食文化や人々の魅力を紹介しています。取り上げられている名物には、天然岩牡蠣（黄金岩牡蠣）、加能ガニ、あんこう、能登牛、海藻しゃぶしゃぶ、のとてまり、松茸、揚浜式製塩、大浜大豆、地酒、能登丼などがあります。この動画は株式会社SCARAMANGAによって制作され、音楽はDJ Yoshimitsuが担当しています。' where id = 'aYmHWyU-lMWa-eSUFQNFt';
update content_bodies set title = 'Suzu City Tourism PR Video (Food and People)', description = 'The Suzu City tourism PR video special site showcases the region''s culinary delights and local culture. Featured attractions include natural rock oysters (Kogane rock oysters), Kanazawa crabs, anglerfish, Noto beef, seaweed shabu-shabu, Noto Temari, matsutake mushrooms, traditional salt production methods, Ohama soybeans, local sake, and Noto rice bowls. The video is produced by SCARAMANGA, with music directed by DJ Yoshimitsu.' where id = '-WrqkxNjMPANERE7-EGrC';
update content_bodies set title = '珠洲市観光ＰＲ動画（体験）', description = '珠洲市観光PR動画特設サイトでは、狼煙灯台や須須神社、道の駅すずなりなど、珠洲市のさまざまな観光名所や体験を紹介しています。見附島でのシーカヤック体験や鉢ヶ崎海水浴場でのSUP体験、刺し網漁体験などが楽しめます。また、珠洲焼づくりや吉祥寺での坐禅体験、道の駅すず塩田村での塩づくり体験などの文化体験も紹介されています。さらに、奥能登国際芸術祭の作品『時を運ぶ船』や『記憶への回廊』なども取り上げられています。この動画は株式会社SCARAMANGAが制作し、音楽はDJ Yoshimitsuが担当しています。' where id = '-fOu6vAytKCzjuFBK2pqh';
update content_bodies set title = 'Suzu City Tourism PR Video (Experience)', description = 'The Suzu City tourism PR video special site showcases various attractions and experiences in Suzu City, including the Noroshi Lighthouse, Susu Shrine, and the Suzu Nari roadside station. Visitors can enjoy activities such as sea kayaking at Mitsuke Island, SUP at Hachigasaki Beach, and fishing experiences. The site also highlights cultural experiences like making Suzu pottery, Zen meditation at Kichijoji, and salt production at the Suzu Salt Village roadside station. Additionally, the video features the Oku Noto International Art Festival with installations like ''The Ship that Carries Time'' and ''Corridor to Memory.'' The video is produced by SCARAMANGA, with music directed by DJ Yoshimitsu.' where id = 'EpwgyEzFPMw8C_MTZC6_y';
update content_bodies set title = '日本の究極の休日 - ゴールデンウィークの無料キャンプ', description = 'ゴールデンウィークは日本で非常に混雑する旅行シーズンですが、私たちはこの機会を利用して田舎で無料キャンプを楽しみました。日本は多くの無料キャンプ場があり、キャンプに最適な国です。詳細については、下記のFacebookグループをご覧ください。また、私たちの冒険をInstagramでフォローして最新情報をチェックしてください。' where id = 'cBQS0S7GU09cumSt6LxDG';
update content_bodies set title = 'Japan''s Ultimate Holiday - Free Camping During Golden Week', description = 'Golden Week in Japan is typically a peak travel period, but this year, we opted for free camping in the countryside. Japan offers numerous free campsites, making it an excellent destination for camping enthusiasts. For more information, you can join the Facebook group linked below. Additionally, you can follow us on Instagram to stay updated on our adventures.' where id = 'uJ8BkY4yDJ7vnFYhzxXlK';
update content_bodies set title = '富山県となみ市の素晴らしい季節の変化と散在する集落', description = '富山県に位置するとなみ市は、素晴らしい季節の変化と独特の散在する集落で知られています。この街は、四季折々の美しい風景と活気あるコミュニティ生活から「行くべき場所」としてしばしば称されています。' where id = 'xfLJMo0k6kTg0f5xHY2qG';
update content_bodies set title = 'The Amazing Seasonal Changes and Scattered Settlements of Tonami-Tonami City, Toyama Prefecture', description = 'Tonami City, located in Toyama Prefecture, is renowned for its remarkable seasonal changes and its unique scattered settlements. This city is often referred to as ''the place to be'' due to its picturesque landscapes and vibrant community life throughout the year.' where id = 'L8ctjHY25JdxPsLISk8WI';
update content_bodies set title = '春の日帰り旅行 - 東京近郊の秩父の寺院と桜', description = '秩父は東京から西武池袋線でわずか90分の距離にあり、春の日帰り旅行に最適な場所です。4月と5月には、羊山公園で桜と芝桜（ピンクのモスフラワー）を楽しむことができます。この美しい公園は、自然愛好者や写真家にとって理想的なスポットで、ユニークな花の体験を提供します。' where id = 'ZT5udypZEbDu8swx9Keei';
update content_bodies set title = 'Spring Day Trip in Chichibu, Japan - Temples & Sakura near Tokyo', description = 'Chichibu, located just 90 minutes from Tokyo via the Seibu Ikebukuro line, is an ideal destination for a spring day trip. Visitors can enjoy the beauty of sakura (cherry blossoms) and shibazakura (pink moss flowers) at Hitsujiyama Park during April and May. This picturesque park offers a unique floral experience, making it a perfect spot for nature lovers and photographers alike.' where id = 'rq1H4-lvFBnBvnApMeUvR';
update content_bodies set title = '日本の近所に住むとはどのようなものか？', description = 'この動画では、東京の郊外にある日本の近所での生活を体験することができます。自転車でのツアーを通じて、鯉のぼりなどの伝統的な日本の装飾や、地域にある自動販売機の数を紹介しています。日本の日常生活をリアルに感じられる内容で、文化的な要素や地元の便利さを強調しています。また、撮影に使用したカメラ機材のリンクや、SNSでのつながりを促す内容も含まれています。さらに、アフィリエイトリンクに関する免責事項があり、リンクを通じて購入された場合に小額の手数料が発生する可能性があることが説明されています。' where id = 'I6GEybcQvM2e_8iwc50hE';
update content_bodies set title = 'What is it like living in a Japanese neighborhood?', description = 'This video invites viewers to experience life in a Japanese neighborhood located on the outskirts of Tokyo. It features a cycling tour that showcases traditional Japanese decorations, such as carp streamers, and highlights the abundance of vending machines in the area. The content aims to provide an authentic glimpse into daily life in Japan, emphasizing cultural elements and local amenities. Additionally, the video includes links to camera gear used for filming and encourages viewers to connect on social media. There is a disclaimer regarding affiliate links, indicating that the creators may earn a small commission from purchases made through those links.' where id = 'w3SWlM6AbtGL2Xf-bXoSG';
update content_bodies set title = '富山県砺波市の素晴らしい季節の変化と散在する集落', description = '富山県の砺波市は、素晴らしい季節の変化と独特の散在する集落で知られています。この市は、四季折々の自然の美しさと地域の魅力を体験できる魅力的な場所です。訪れる人々は、砺波の多様な風景や文化遺産を探索し、この特別な目的地の魅力を感じることができます。' where id = 'c7g0jfHQ3p2l2LH-Xp2WE';
update content_bodies set title = 'The Amazing Seasonal Changes and Scattered Settlements of Tonami-Tonami City, Toyama Prefecture', description = 'Tonami City, located in Toyama Prefecture, is renowned for its remarkable seasonal changes and unique scattered settlements. The city offers a captivating experience throughout the year, showcasing the beauty of nature and the charm of its communities. Visitors can explore the diverse landscapes and cultural heritage that make Tonami a special destination.' where id = 'vp19C7Y4DI--OJBZzeurw';
update content_bodies set title = 'TOKYO NATURE SPOTS - 都会を逃れて！', description = '東京は忙しい人々やコンクリートの建物で溢れる都市以上の存在です。実際、世界的に有名な公園や日本で最も美しい自然スポットがいくつかあります。この動画では、新宿にある新宿御苑、立川にある昭和記念公園、そして等々力渓谷公園を訪れました。これらの公園は、東京の中にある自然の美しさを強調しており、都会の喧騒からの完璧な逃避を提供しています。' where id = '8aHy78huM_1SEGUodP3DS';
update content_bodies set title = 'TOKYO NATURE SPOTS - Escape the city!', description = 'Tokyo is not just a bustling metropolis filled with concrete structures; it also boasts some of Japan''s most beautiful natural spots. This video showcases three notable locations: Shinjuku Gyoen Park, a serene oasis in the heart of Shinjuku; Showa Kinen Park, located in Tachikawa, known for its expansive greenery; and Todoroki Valley, a picturesque gorge that offers a peaceful retreat from urban life. Each of these parks highlights the natural beauty that can be found within Tokyo, providing a perfect escape from the city''s hustle and bustle.' where id = '-t1sz7pj0l9_1TNJCoKAM';
update content_bodies set title = 'NWWA ウォーターボール & 神戸スイーツ', description = '12月10日から始まった志摩自然学校のクリスマス期間限定企画です。このイベントでは、ホテル プライムリゾート賢島のプールでウォーターボール体験ができ、さらにホテル自慢の神戸スイーツも楽しめます。参加者はウォーターボールの中で立つ挑戦を楽しむことができます。詳しくは、志摩自然学校のホームページをご覧ください。' where id = 'HC5gQ8_-nsxoMwt5Q35NO';
update content_bodies set title = 'NWWA Water Ball & Kobe Sweets', description = 'Starting from December 10, the Shima Nature School is hosting a limited-time Christmas event. This event features a water ball experience at the pool of Hotel Prime Resort Kashikojima, combined with the hotel''s signature Kobe sweets. Participants can enjoy the challenge of standing in the water ball. For more details, please visit the Shima Nature School''s website.' where id = 'fDSPssHf-PLKSu5vPBqvS';
update content_bodies set title = '珠洲市観光PR動画（ダイジェスト版）', description = 'この動画は、石川県能登半島の最先端に位置する珠洲市の観光をPRするためのものです。珠洲市の魅力や特徴を紹介しており、観光PR動画の特設サイトで詳細を確認できます。制作は株式会社SCARAMANGAが行い、音楽ディレクターはDJ Yoshimitsuが担当しています。' where id = 'YgSMx1TPM7W3AUnCKaOMV';
update content_bodies set title = 'Suzu City Tourism PR Video (Digest Version)', description = 'This is a promotional video for tourism in Suzu City, located at the tip of the Noto Peninsula in Ishikawa Prefecture. The video highlights the attractions and unique features of Suzu City. For more information, you can visit the special website for the Suzu City tourism PR video. The video was produced by SCARAMANGA, and the music director for the project is DJ Yoshimitsu.' where id = 'zeE6340nNzDsH1BiCdK8F';
update content_bodies set title = '自由自在', description = 'ボギーボードでの楽しさを存分に味わえる内容です。' where id = 's22ZWV2h9WkPplu7fp_fW';
update content_bodies set title = 'Freedom at Will', description = 'Experience the thrill of riding a boogie board like never before!' where id = 'SotPcwXP_WJOs5Tev0-po';
update content_bodies set title = '島根県プロモーションショート', description = 'この動画は、島根県の特徴や魅力を簡潔に紹介しています。' where id = 'MppOXnu0-LjtunOW2hS_3';
update content_bodies set title = 'Shimane Pref Promo SHORT', description = 'This video provides a brief introduction to Shimane Prefecture, highlighting its unique features and attractions.' where id = 'cbwVUrjsKVVPASdPHUSON';
update content_bodies set title = 'ヨシムラ８耐パドック', description = 'やっぱりヨシムラです！' where id = 'UX5K19UGrN1YovKbhl25n';
update content_bodies set title = 'Yoshimura 8-Hour Paddock', description = 'It''s Yoshimura after all!' where id = 'hMUkHs_3kzllgAJ3CznQK';
update content_bodies set title = '８耐', description = '夏といえば鈴鹿８耐。熱いバトルが繰り広げられ、最高の体験でした。' where id = 'eDYBXTDDn008TIcwWxP9e';
update content_bodies set title = '8-Hour Race', description = 'Summer means the Suzuka 8-Hour Race. The intense battles were fantastic.' where id = 'CxtHPaoM6OmBgltd3Dj04';
update content_bodies set title = '伊勢えび祭り', description = '5日に浜島で開催された伊勢えび祭りでは、踊りや巨大な伊勢えび、そして多くの人々に驚かされました。' where id = 'g0V-0-GAethy5VxMJBWHH';
update content_bodies set title = 'Ise Lobster Festival', description = 'The Ise Lobster Festival took place on the 5th in Hamajima. Attendees were amazed by the dancing, the giant Ise lobsters, and the large crowd.' where id = 'azbaFEOAP8AI8KUsbFjmf';
update content_bodies set title = 'NWWA ウォーターボール de 自然体験', description = '志摩自然学校の新しいプログラム『ウォーターボール』で、海上での浮遊体験をしてみませんか。波静かな英虞湾で、心身ともに癒されるひとときをお楽しみください。詳しい情報は、ホームページをご覧ください。' where id = '3rdwMXnLB8gW445icVUg9';
update content_bodies set title = 'NWWA Water Ball Nature Experience', description = 'Experience floating on the sea with the new program ''Water Ball'' at Shima Nature School. Enjoy the tranquility of Ago Bay and find relaxation. For more details, please visit our website.' where id = 'yTHo8JSrnNpWBvJriXgEK';
update content_bodies set title = '三重県観光プロモーション　日本語ダイジェスト版', description = '三重県の観光地を簡潔に紹介する内容です。' where id = 'UksU4-8Rs0Pl2ASZspQg4';
update content_bodies set title = 'Mie Prefecture Tourism Promotion - Japanese Digest Version', description = 'This is a digest introduction to the tourist attractions in Mie Prefecture.' where id = 'd1pZwoct3wP8_VCkS9aBM';
update content_bodies set title = '松江城の朝日', description = '松江城は島根県に位置し、朝日の美しい景色を提供しています。手つかずの自然と日本の美しい精神を感じることができる場所です。朝日が昇る際の劇的な光景は、城の威厳を一層引き立て、訪れる人々にとって魅力的な光景となっています。' where id = 's8oG4T4HE8D-6wz9WvBVw';
update content_bodies set title = 'Sunrise at Matsue Castle', description = 'Matsue Castle, located in Shimane Prefecture, offers a stunning view of the sunrise, showcasing the untouched landscapes and the beautiful spirit of Japan. The dramatic lighting during sunrise enhances the castle''s majestic presence, making it a captivating sight for visitors.' where id = 'YPnpwjFtWrA0fBK4GGFLW';
update content_bodies set title = '石見の伝統工芸', description = '石見の伝統工芸は、島根県の豊かな文化遺産と職人技を示しています。この地域は、美しい風景で知られ、手つかずの自然が日本の美しさを反映しています。これらの工芸品は、地元の職人の技術を表すだけでなく、日本人の精神や伝統を体現しています。' where id = 'BN_0cMhHJi-OFHC1K7EJ7';
update content_bodies set title = 'Traditional Crafts of Iwami', description = 'The traditional crafts of Iwami in Shimane Prefecture showcase the region''s rich cultural heritage and craftsmanship. The area is known for its beautiful landscapes, which remain largely untouched, reflecting the essence of Japan''s natural beauty. These crafts not only represent the skills of local artisans but also embody the spirit and traditions of the Japanese people.' where id = 'iHzm8D2ELoFisjfdYDYOn';
update content_bodies set title = '御在所ロープウエイの四季', description = '御在所ロープウエイと御在所岳の四季を紹介しています。季節ごとに訪れることで、新たな感動に出会うことができます。なお、映像内の「日本カモシカセンター」は閉鎖されていることをご了承ください。' where id = 'PQLVmi3PMRgEu1zNWdOuI';
update content_bodies set title = 'The Seasons of Gozaisho Ropeway', description = 'This text introduces the Gozaisho Ropeway and Mount Gozaisho throughout the seasons. Each visit in a different season offers new and exciting experiences. (Please note that the ''Japanese Serow Center'' mentioned in the video has been closed.)' where id = 'lMvS5vG7EpwjE9m1mrk0n';
update content_bodies set title = '大橋川と宍道湖の朝日', description = '島根県の大橋川と宍道湖での朝日は、水面に映る光のドラマチックな景色を提供します。この場所は手つかずの自然景観と日本の美しい精神を体現しており、自然愛好者や写真家にとって理想的なスポットです。' where id = 'Th5-2-6tflERtK15-0sbE';
update content_bodies set title = 'Sunrise at Ohashi River and Lake Shinji', description = 'The sunrise at Ohashi River and Lake Shinji in Shimane Prefecture offers a dramatic view of the lights reflecting on the water. This location showcases the untouched landscapes and the beautiful spirit of Japan, making it a perfect spot for nature lovers and photographers.' where id = 'n4dPqTq1RnuHr_3j0tNz6';
update content_bodies set title = 'Visit SAITAMA PR VIDEO「See You in SAITAMA」', description = '東京のすぐ外にある埼玉を探索し、ユニークな食文化、美しい自然、文化的なアクティビティを楽しむことができます。この動画では、SOLABASEや月の石もみじ公園、長瀞の岩畳でのボート体験など、さまざまな観光スポットが紹介されています。蔵の町並みや川越氷川神社などの歴史的な場所も訪れることができます。また、大宮盆栽美術館で盆栽の芸術を体験したり、三峰神社の美しい景色を楽しんだりできます。その他にも、秩父蒸留所やトーベ・ヤンソンあけぼの子どもの森公園、角川文化博物館など、埼玉には多様なアクティビティが用意されています。' where id = 'BVsNvyMwOa7NMrYvY5JZb';
update content_bodies set title = 'Visit SAITAMA PR VIDEO「See You in SAITAMA」', description = 'Explore Saitama, a hidden gem just outside Tokyo, offering a variety of unique experiences. Enjoy delicious local cuisine, stunning natural landscapes, and rich cultural activities. The video highlights various attractions, including SOLABASE, Tsuki no Ishi Momiji Park, and Nagatoro Iwadatami Rocks for boating. Discover historical sites like the Townscape of kura warehouses and Kawagoe Hikawa Shrine. Experience the art of bonsai at the Omiya Bonsai Art Museum and visit the scenic Mitsumine Shrine. Other notable spots include Chichibu Distillery, Tove Jansson Akebono Children’s Forest Park, and the Kadokawa Culture Museum. Saitama promises a diverse range of activities for all visitors.' where id = 'uTI9c5kmsP_4PuceYWT4d';
update content_bodies set title = '埼玉を巡る旅：埼玉に焦点を当てた日本の車旅動画', description = 'この動画は、秋の季節に埼玉県を車で巡る旅を紹介しています。多くの旅行者が東京から新幹線を利用して旅を始める中、この動画では公共交通機関ではアクセスが難しい隠れた地域を車で探索することを推奨しています。東京から埼玉、群馬、新潟へのルートには、それぞれの県にユニークな魅力があります。動画では、埼玉の美しい蔵の町並みや地元の料理、クラフトビール、フォトジェニックなスポットなどが紹介されています。埼玉は発展した交通網を持ち、「小江戸」として知られる川越や、秩父・長瀞の自然美など、多彩な観光資源があります。また、動画では、着物レンタルの「むかでや」や、川越氷川神社、秩父ジオグラビティパークなど、いくつかの注目スポットも紹介されています。' where id = 'ItjQu1oQjB8WHTfJ-XyXJ';
update content_bodies set title = 'Journey through SAITAMA: Car trip video through Japan, focused on ''SAITAMA''', description = 'This video showcases a car trip through Saitama Prefecture in Japan during the autumn season. While many travelers start their journey in Tokyo using the Shinkansen, this video encourages exploring lesser-known local areas by car, which provides access to destinations that are difficult to reach via public transportation. The route from Tokyo to Saitama, Gunma, and Niigata offers unique attractions in each prefecture. The video highlights Saitama''s beautiful townscapes, including kura warehouses, local cuisine, craft beer, and various photogenic spots. Saitama is well-connected with a robust transportation network and features attractions like Kawagoe, known as ''Little Edo,'' and the natural beauty of Chichibu and Nagatoro. The video also lists several notable spots, including Mucadeya for kimono rentals, Kawagoe Hikawa Shrine, and Chichibu Geo Gravity Park, among others.' where id = '59wOaCNiT43VYU7B3upqb';
update content_bodies set title = '宍道湖の夕日', description = '宍道湖は島根県に位置し、夕日の美しい景色を提供します。手つかずの自然景観と日本の美しい精神が融合したこの場所では、夕暮れ時のドラマチックな光が魅力的なシーンを生み出し、地域の自然の美しさを際立たせています。' where id = '-p2BvgJ-JxQuYFwjntWAI';
update content_bodies set title = 'Sunset at Lake Shinji', description = 'Lake Shinji in Shimane Prefecture offers a stunning view of sunsets, showcasing the untouched landscapes and the beautiful spirit of Japan. The dramatic lighting during sunset creates a captivating scene that highlights the natural beauty of the area.' where id = 'xF6qkB4JHRCOzRAjKnwvH';
update content_bodies set title = '信じられないほど急な橋', description = 'このタイトルは、日本の島根県に位置する非常に急な橋を指しています。この橋は、手つかずの美しい自然景観を背景にしており、島根の地域の魅力を強調しています。説明では、島根の風景の美しさが強調されており、日本の美しい精神を反映した純粋な環境が描かれています。「ペダルを金属に押し付けろ！」というフレーズは、冒険心を呼び起こし、訪問者にこの急な橋を渡りながら息をのむような景色を楽しむことを促しています。' where id = 'nBmYTTMPPwD0zUEf5cQRj';
update content_bodies set title = 'An Unthinkably Steep Bridge', description = 'The title refers to a remarkably steep bridge located in Shimane Prefecture, Japan. This bridge is set against the backdrop of the region''s stunning natural landscapes, which are characterized by their untouched beauty. The description highlights the scenic charm of Shimane, emphasizing the pristine environments that reflect the beautiful spirit of Japan. The phrase ''Put the Pedal to the Metal!'' suggests an adventurous spirit, inviting visitors to experience the thrill of crossing this steep bridge while enjoying the breathtaking views.' where id = 'VTZAIknecbT930YOjv3mj';
update content_bodies set title = '長瀞川ボート | 360 VR動画 | 埼玉県日本', description = '長瀞川ボートは、訪問者が長瀞エリアを観光するための楽しいアクティビティです。この水上アクティビティでは、伝統的な和船が長瀞渓谷を流れる荒川を約3km下ります。ゲストは、荒川に沿ってスリリングに滑りながら、周囲のダイナミックな自然を楽しむことができます。地域の美しさを体感する素晴らしい方法です。' where id = 'LsR-OwgSWNNYOtlUHR6FV';
update content_bodies set title = 'Nagatoro River Boating | 360 VR Video | Saitama Japan', description = 'Nagatoro River Boating is an enjoyable activity for visitors to explore the Nagatoro area. This water activity features traditional Japanese-style boats that travel approximately 3 km down the Arakawa River, which flows through the scenic Nagatoro valley. As guests glide along the river, they can experience the vibrant natural surroundings, making it a thrilling way to appreciate the beauty of the region.' where id = 'HHVF9HNfzRHQAGVYNKKzx';
update content_bodies set title = 'フォトジェニックな人気の埼玉スポットを訪れよう！', description = 'この動画では、埼玉のフォトジェニックな人気スポットを紹介しています。美しい風景や魅力的な場所が取り上げられ、訪れる価値のあるスポットが紹介されています。' where id = 'dcBX_9mXgUAaH6J-8sy8k';
update content_bodies set title = 'Let''s visit photogenic popular saitama spots!', description = 'This video showcases popular and photogenic locations in Saitama, highlighting the beauty and appeal of these spots.' where id = 'TGzhem4zZSi2fwLrTmzA1';
update content_bodies set title = '川越氷川神社 縁結び風鈴祭り', description = '川越氷川神社は「恋愛の神社」として知られ、古くから愛や良い結婚を求める人々が祈りに訪れています。この祭りは、夢のパートナーへの思いを届けるために開催されます。風鈴の音色は、夏の暑さの中で心地よい涼しさを提供してくれます。' where id = 'cLyCSdrXzWgtozfrS0jRZ';
update content_bodies set title = 'Kawagoe Hikawa Shrine Enmusubi Wind Chime Festival', description = 'Kawagoe Hikawa Shrine, known as a ''love shrine'', has been a place where people pray for love and good marriages since ancient times. The Enmusubi Wind Chime Festival is held to express heartfelt wishes to one''s ideal partner. During the festival, the soothing sounds of wind chimes create a refreshing atmosphere, providing a cool respite during the summer heat.' where id = 'zLYSGQF8UvzcTtmM4C9mw';
update content_bodies set title = 'ミソツチ氷柱', description = 'ミソツチ氷柱は、1月から2月にかけて岩から流れ落ちる水が凍り、見事な氷の造形を作り出す自然現象です。この冬の間、訪れる人々は自然の芸術作品を目の当たりにすることができます。' where id = 'XMjK8UAK11Z63qNfwnWvK';
update content_bodies set title = 'Misotsuchi Icicles', description = 'The Misotsuchi Icicles are a natural phenomenon that occurs from January to February, where water trickling from rocks freezes and creates stunning ice formations. Visitors can witness this unique display of nature''s artistry during the winter months.' where id = 'N8w1qAdEzy-kU4OH5ZxB9';
update content_bodies set title = '長瀞川のボート遊び', description = '長瀞川のボート遊びは20世紀初頭から楽しまれており、町の主要な観光名所の一つです。毎年約20万人の訪問者を迎えています。熟練の船頭が操るボートに乗り、力強い急流や穏やかな流れを下りながら、自然の記念物である美しい渓谷の景色を楽しむことができます。' where id = '72-NoA6y99D9P-PBt-kWZ';
update content_bodies set title = 'Nagatoro River Boating', description = 'Nagatoro River boating has been a popular activity since the early 20th century, attracting around 200,000 visitors annually. Tourists can enjoy a boat ride guided by a skilled boatman, navigating through both powerful rapids and gentle currents. This experience allows visitors to take in the stunning natural beauty of the valley, which is recognized as a natural monument.' where id = '-WAKqJBehFhE0Yh5BELn0';
update content_bodies set title = 'ケーキのようなかき氷 浦和つた', description = '浦和つたは、かき氷専門のカフェで、さまざまなシロップやトッピングを提供しています。このカフェでは、冬でも一年中、典型的なかき氷を楽しむことができます。JR浦和駅から徒歩2分の便利な場所にあり、営業時間は11:00から19:00までで、月曜日は定休日です。詳細は公式ウェブサイトをご覧ください。' where id = 'n-FOcC-pl62Mq4iiJ-PfE';
update content_bodies set title = 'Shaved Ice like Cake Urawa Tsuta', description = 'Urawa Tsuta is a specialty cafe dedicated to shaved ice, offering a wide variety of syrups and toppings. This cafe allows customers to enjoy traditional shaved ice throughout the year, even during the winter months. It is conveniently located just a 2-minute walk from JR Urawa Station and operates from 11:00 AM to 7:00 PM, closing on Mondays. For more information, you can visit their website.' where id = 'LX-wWVQ3eO5v2Jp8ian-b';
update content_bodies set title = '春日部の藤「牛島の藤」', description = '牛島の藤にある藤の木は1200年以上の歴史を持ち、重要な観光名所です。花が満開になるのは4月下旬から5月上旬が最適です。この公園は2ヘクタールの広さを持ち、藤の美しい景観は世界で最も美しいと称されています。埼玉県春日部市牛島786に位置し、東武アーバンパークラインの藤の牛島駅から徒歩10分でアクセス可能です。詳細は公式ウェブサイトをご覧ください。' where id = '5UIAFWu9nSTKL7dDkAabi';
update content_bodies set title = 'Wisteria in Kasukabe ''Ushijima no Fuji''', description = 'The wisteria trees at Ushijima no Fuji are over 1,200 years old, making them a significant attraction. The best time to visit and see the flowers in full bloom is from late April to early May. The park, which spans two hectares, is renowned for its breathtaking display of wisteria, often described as the most beautiful in the world. Located at 786 Ushijima, Kasukabe-shi, Saitama, Japan, it is easily accessible, being just a 10-minute walk from Fujino Ushijima Station on the Tobu Urban Park Line. For more information, visit their website.' where id = 'b_r05ld8Pp0CmzUuKisS-';
update content_bodies set title = '比嘉愛未｜広島・竹原を巡るさんぽ旅 15秒Ver', description = '比嘉愛未さんが映画『吟ずる者たち』のロケ地である広島・竹原を巡る旅に出かけます。レトロな街並みを散策し、野生のうさぎに出会う様子を楽しむことができます。まるで一緒に旅をしているかのような気分を味わえる内容です。' where id = '_Uo_RfI_h3jQ_fNfGBy5c';
update content_bodies set title = 'Manami Higa''s Walking Trip in Takehara, Hiroshima - 15 Seconds Version | Tabiiro Movie', description = 'Join Manami Higa on a journey through Takehara, Hiroshima, a filming location for the movie ''Ginzuru Monotachi.'' Experience the charm of the retro streets and encounter wild rabbits. Enjoy the feeling of traveling together!' where id = 'bOz9bJXX7JlVBVG0dbACh';
update content_bodies set title = '踏み込んで急坂を越える', description = '島根の美しい景色を称賛する内容です。穏やかで文化的な深みを感じさせる表現が使われています。車が急坂を駆け上がる様子は、まるでジェットコースターのようで、ドライブのスリルと興奮を強調しています。' where id = 'pmhACdFEmUv-ZDKgkVIh4';
update content_bodies set title = 'Accelerating Over Steep Slopes', description = 'The description highlights the beautiful scenery of Shimane, Japan. It captures the essence of the region with phrases that evoke a sense of tranquility and cultural depth. The imagery of a car speeding over a steep slope likens the experience to a roller coaster, emphasizing the thrill and excitement of the drive.' where id = '7DBztZlhaaez_0-9YwyC0';
update content_bodies set title = '秩父の芝桜の丘（ちちぶのしばざくらの丘）', description = '秩父市のパノラマビューを楽しめる羊山公園には、壮大な新しい景観である芝桜の丘があります。この場所は関東地方で最大級の芝桜の植栽を誇り、9種類の芝桜、約40万株が17600平方メートルを覆い、見事な色彩のショーを演出しています。芝桜は4月中旬から5月初旬にかけて満開を迎えます。公園へのアクセスは、西武秩父駅または秩父駅から徒歩20分です。' where id = '18uQO6ZbuZZYSpigHGQVh';
update content_bodies set title = 'Chichibu Moss Pink Hill (Shibazakura Hill)', description = 'Hitsujiyama Park features the stunning Moss Pink Hill, offering a panoramic view of Chichibu city. This site boasts one of the largest moss pink plantings in the Kanto region, showcasing a vibrant color display with nine varieties of moss pink, totaling around 400,000 plants across 17,600 square meters. The moss pink flowers bloom beautifully from mid-April to early May. Visitors can access the park by a 20-minute walk from either Seibu Chichibu Station or Chichibu Station.' where id = 'kbeRVqst0EKbM4hB2DeDS';
update content_bodies set title = '川越氷川神社：恋愛成就の神社', description = '川越氷川神社は、6世紀から存在すると言われる歴史ある神社で、特に結婚運をもたらす神社として知られています。恋愛や人間関係のご利益を求める多くの参拝者が訪れます。アクセスは、川越駅からバスでの短い移動か、本川越駅から徒歩20分で可能です。また、川越氷川神社の公式サイトや小江戸川越、むすびカフェに関する情報も提供されており、東京からの短い旅行に最適なスポットです。' where id = 'C0BOoQxZhew7dcGPFYAuW';
update content_bodies set title = 'Kawagoe Hikawa Shrine Lucky Shrine for Love', description = 'Kawagoe Hikawa Shrine is a historic shrine believed to have been established in the 6th century. It is renowned as a lucky shrine for marriage, attracting many visitors seeking blessings for love and relationships. The shrine is accessible from Kawagoe Station via a short bus ride or a 20-minute walk from Hon-Kawagoe Station. For those interested in exploring the area, additional resources include links to the Kawagoe Hikawa Shrine website and information about Koedo Kawagoe and Musubi Cafe, making it a perfect destination for a short trip from Tokyo.' where id = 'BV_6uQvs7nzNQVN7Bu4JT';
update content_bodies set title = '珠洲市　安幸キャンペーン', description = 'この動画は珠洲市の安幸キャンペーンについて紹介しています。' where id = 'slOJpPt46w43eKHie-Yw7';
update content_bodies set title = 'Suzushi City Anko Campaign', description = 'This video introduces the Anko Campaign in Suzushi City.' where id = 'J_XOSiM6IYVVPrVdDAcBu';
update content_bodies set title = '飯田燈籠山祭り', description = '飯田燈籠山祭りは、石川県珠洲市飯田町で開催されます。詳細については、珠洲市の観光PR動画特設サイトを訪れることができます。この祭りは株式会社SCARAMANGAによって制作されており、音楽ディレクターはDJ Yoshimitsuです。' where id = 'k45d3rM-ElBiFlfU0IHIp';
update content_bodies set title = 'Iida Lantern Mountain Festival', description = 'The Iida Lantern Mountain Festival is located in Iida Town, Suzu City, Ishikawa Prefecture. For more information, you can visit the special site for the Suzu City tourism promotional video. The festival is produced by SCARAMANGA, and the music director for the event is DJ Yoshimitsu.' where id = 'YlM4Fv1bsqgUkFprgxCbR';
update content_bodies set title = '松江城の朝陽', description = '松江城は島根の絶景を提供し、日本の美しさを体現しています。朝陽が照らす風景は詩や絵画のようで、光の壮麗さを際立たせています。' where id = 'oJTwZM9W86HX1fISEK4ki';
update content_bodies set title = 'The Morning Sun at Matsue Castle', description = 'Matsue Castle offers breathtaking views in Shimane, embodying the beauty of Japan. The morning sun creates a picturesque scene, reminiscent of poetry and art, showcasing the splendor of light.' where id = 'IM6ID_4ZFljl13I0jY5Ug';
update content_bodies set title = '宝立七夕キリコ祭り', description = '宝立七夕キリコ祭りは、石川県珠洲市宝立町鵜飼で開催されます。詳細については、珠洲市観光PR動画特設サイトを訪れることができます。この祭りは株式会社SCARAMANGAによって制作されており、音楽ディレクターはDJ Yoshimitsuです。' where id = 'dAl0y5EDaT0X4IE3xgiDB';
update content_bodies set title = 'Takarada Tanabata Kiriko Festival', description = 'The Takarada Tanabata Kiriko Festival is held in Hakurakucho, Suzu City, Ishikawa Prefecture. For more information, you can visit the Suzu City tourism promotional video special site. The festival is produced by SCARAMANGA, and the music director for the event is DJ Yoshimitsu.' where id = '0sbfgd9coTOUoXbEdBgGL';
update content_bodies set title = '稻佐海滨の夕陽', description = '稻佐海滨は島根の絶景を提供し、その美しさを堪能できます。ここでの夕陽は詩的で絵のような光景と表現され、心を魅了する光の饗宴として描かれています。' where id = 'XnzBI6WlfOCNVMUF7BWMy';
update content_bodies set title = 'Sunset at Inasa Beach', description = 'Inasa Beach offers breathtaking views, showcasing the beauty of Shimane. The sunset here is described as a poetic and picturesque spectacle, likened to a feast of light that captivates the heart.' where id = 'legiVUzUd0hMqutL5kax0';
update content_bodies set title = '宍道湖的夕阳', description = '島根の美しい景色を堪能できる宍道湖。夕陽は詩のように美しく、絵画のような光景を提供します。光の饗宴とも称されるこの夕陽は、見る者の心を魅了します。' where id = 'k0djM2R4S0zBQtQ9R-6at';
update content_bodies set title = 'Sunset at Lake Shinji', description = 'Lake Shinji offers breathtaking views, showcasing the beauty of Shimane. The sunset here is described as a poetic and picturesque spectacle, likened to a feast of light that captivates the heart.' where id = 'q723LcrFyQatlV6fXZcKX';
update content_bodies set title = '稲佐の浜の夕日', description = '稲佐の浜は島根県に位置し、夕日の美しい景色を提供しています。手つかずの自然が広がるこの場所は、日本の美しい精神を体現しています。夕暮れ時の色彩のドラマティックな変化は息をのむような光景を生み出し、自然愛好者や写真家にとって完璧なスポットとなっています。' where id = '1BUACHz5BAK_XCQGzhdpB';
update content_bodies set title = 'Sunset at Inasa Beach', description = 'Inasa Beach, located in Shimane Prefecture, offers a stunning view of the sunset, showcasing the untouched landscapes that embody the beautiful spirit of Japan. The dramatic interplay of colors during sunset creates a breathtaking scene, making it a perfect spot for nature lovers and photographers alike.' where id = 'ubPt8Rj6ho_6k77I-sxKd';
update content_bodies set title = '日本の120ドル完全プライベートファーストクラスバスに乗る | 東京 - 大阪', description = 'この動画では、東京から大阪への豪華なプライベートバスの旅、特にドリームスリーパーというバスを紹介しています。この特別な体験の料金は18,000円（約120ドル）です。旅は東京の池袋から始まり、バスの設備の詳細なツアーが含まれています。部屋やトイレのツアーもあり、乗車中には夕食のセグメントも楽しめます。動画は、イントロダクション、ルートと料金の詳細で構成されており、最後には視聴者への感謝のメッセージで締めくくられています。' where id = 'BMOMiQ7b1290QeLrFGJx-';
update content_bodies set title = 'Riding Japan’s $120 Completely Private First Class Bus | Tokyo - Osaka', description = 'This video showcases a luxurious private bus ride from Tokyo to Osaka, specifically the Dream Sleeper bus. The fare for this exclusive experience is 18,000 JPY (approximately 120 USD). The journey begins in Ikebukuro, Tokyo, and includes a detailed tour of the bus''s amenities, including a room and bathroom tour. Viewers can also enjoy a dinner segment during the ride. The video is structured with an introduction, route and fee details, and concludes with a thank you message for viewers.' where id = 'BcU4ZMtIQI0pvYBz9l9Ce';
update content_bodies set title = '日本の豪華な夜行バスでの1夜 🇯🇵 | My Flora', description = 'この動画では、徳島から東京までの豪華なコンパートメントバス「My Flora」での旅を紹介しています。この体験の料金は12,000円（約90ドル）です。バスは海部バスが運行しており、ユニークなカプセルデザインが特徴です。動画には、導入部、ルートと料金の詳細、ラウンジのツアー、バス内部の様子、座席のレビュー、トイレのレビューが含まれています。個人用の赤じゅうたんを含む豪華なアメニティが強調されています。' where id = 'As8FHU5kS9c91Cjo0Bdql';
update content_bodies set title = '1 Night on Japan’s Luxury Overnight Bus 🇯🇵 | My Flora', description = 'This video showcases a journey on the Luxury Compartment Bus, My Flora, traveling from Tokushima to Tokyo. The fare for this experience is 12,000 JPY (approximately 90 USD). The bus, operated by Kaifu Bus, features a unique capsule design. The video includes an introduction, details about the route and fees, a tour of the lounge, an inside look at the bus, a review of the seating, and a washroom review. The experience is highlighted by the luxurious amenities, including a personal red carpet.' where id = 'SCpv0G7ZpfF9CNHFRKjth';
update content_bodies set title = '日本の36ドル完全プライベートバスに乗る 🇯🇵 | 大阪 - 城崎温泉', description = 'この動画では、大阪から城崎温泉までの日本の完全プライベートバス、LuxRea GreenRoomの旅を紹介しています。バスの料金は約36ドルで、ユニークなプライベートルーム体験が提供されます。動画には、イントロダクション、地図と費用の内訳、Zentan LuxReaバスのツアー、朝食の詳細、城崎温泉への到着が含まれています。また、昼食や観光活動、列車移動、夕食、宿泊施設も紹介されています。このバスには、拡張現実やテレビなどのアメニティが備わっており、旅行体験を向上させています。動画の最後には、視聴者への感謝の言葉が述べられています。' where id = 'aZ_3i_KHxVtfYl3piljdh';
update content_bodies set title = 'Riding Japan’s $36 Completely Private Bus 🇯🇵 | Osaka - Kinosaki Onsen', description = 'This video showcases a journey on Japan''s Completely Private Bus, the LuxRea GreenRoom, from Osaka to Kinosaki Onsen. The bus fare is approximately $36, and it offers a unique private room experience. The video includes an introduction, a map and cost breakdown, a tour of the Zentan LuxRea bus, breakfast details, and the arrival at Kinosaki Onsen. Viewers can also see lunch and exploration activities, as well as train travel, dinner, and hotel accommodations. The bus features amenities like augmented reality and a TV, enhancing the travel experience. The video concludes with a thank you to the audience for watching.' where id = '_ruig7UaFKRQ_5OQRzSO2';
update content_bodies set title = '日本のカプセル夜行バスでの17時間 | ウィラードーム 🇯🇵', description = 'この動画では、日本のカプセル夜行バスを利用して、17時間の旅を体験します。予算型から高級型まで、東京から名古屋、名古屋から大阪、大阪から東京へのルートを紹介します。各区間の料金は、東京から名古屋のリラックスバスが¥3,000、名古屋から大阪のプライムバスが¥3,100、大阪から東京の高級ドームバスが¥8,900です。快適さを重視したこの体験は、日本を横断する新しい旅行スタイルを提供します。' where id = '2nLqjpVSsJpf0VbWHQtFb';
update content_bodies set title = '17 Hours on Japan’s Overnight Capsule Bus | Willer Dome 🇯🇵', description = 'In this video, we embark on a 17-hour journey on three different capsule overnight buses in Japan, showcasing options from budget to luxury. The trip covers routes from Tokyo to Nagoya, Nagoya to Osaka, and Osaka back to Tokyo. The fares for each leg are as follows: ¥3,000 for the Relax bus from Tokyo to Nagoya, ¥3,100 for the Prime bus from Nagoya to Osaka, and ¥8,900 for the luxury Dome bus from Osaka to Tokyo. The experience promises comfort without discomfort, making it an interesting way to travel across Japan.' where id = 'K9tb2-EZk-RbSH3HV7scZ';
update content_bodies set title = '松江城の朝陽', description = '島根の絶景を紹介するこの作品は、美しい日本の精神と原風景を表現しています。松江城の朝陽は、詩のように美しい光景であり、静かな風景の中で光の美しさを際立たせています。' where id = 'zjKmofaIyinEJMX03crkm';
update content_bodies set title = 'The Sunrise at Matsue Castle', description = 'A stunning view in Shimane, showcasing the beautiful Japanese spirit and natural scenery. The sunrise at Matsue Castle is described as picturesque, highlighting the beauty of light in this serene landscape.' where id = '-HJysx1h4dB7OvqATsj7_';
update content_bodies set title = '大橋川、宍道湖的朝陽', description = '島根の絶佳美景を紹介します。美しい日本の精神と原風景が感じられる場所であり、大橋川と宍道湖の朝陽は詩のように美しい光景です。' where id = 'fNYhnyPn8mgLDSNzwVT3K';
update content_bodies set title = 'Dawn at Ohashi River and Lake Shinji', description = 'A stunning view in Shimane, showcasing the beautiful Japanese spirit and natural scenery. The picturesque beauty of the sunrise over Ohashi River and Lake Shinji is truly breathtaking.' where id = 'C8yGrjAlhVYAVnzOztQnh';
update content_bodies set title = '日本のカプセル寝台列車での2日間！ | 🇯🇵 サンライズエクスプレスの旅', description = 'この動画では、東京から讃岐うどんで有名な高松へ向かうサンライズ瀬戸寝台列車の旅を紹介します。香川県の新しい島を訪れ、新しい食べ物や美しい景色を楽しむ予定です。往復の運賃は44,110円（約290ドル）で、行きはシングルルーム、帰りはソロルームを利用します。旅の中で、香川県の小豆島で32kmのサイクリングも行います。動画では、列車の乗車、食事、観光など、旅のさまざまな側面をカバーしています。最後は東京駅に戻り、視聴者への感謝の言葉で締めくくります。' where id = 'oqJAW98aFKL0x-4iF9hdI';
update content_bodies set title = '2 Days on Japan’s Capsule Sleeper Train! | 🇯🇵 Sunrise Express Journey', description = 'In this video, we embark on a journey aboard the Sunrise Seto Express Sleeper Train from Tokyo to Takamatsu, known for its delicious Udon. The trip includes a visit to a new island in Kagawa Prefecture, where we will explore new foods and beautiful scenery. The total round trip fare is ¥44,110 (approximately US$290). The route features a single room for the outbound journey and a solo room for the return. During the trip, we will cycle 32 km on Shodoshima Island. The video covers various aspects of the journey, including boarding the train, meals, and sightseeing. The experience concludes with our return to Tokyo Station, thanking viewers for joining the adventure.' where id = '-_VaM4of3yHG8CETNiu3S';
update content_bodies set title = '東京🇯🇵からソウル🇰🇷までの最長新幹線とフェリーの旅 | 4日間/1800kmの旅', description = 'この動画では、東京からソウルまでの4日間にわたる1800キロ以上の旅を記録しています。旅程には京都、福岡、釜山が含まれ、陸と海の移動が組み合わされています。旅の総費用は46,430円（約320ドル）です。東京から京都までのN700A、京都から福岡までのN700S、福岡から釜山までの新カメリアフェリー、釜山からソウルまでのKTXを利用しています。動画には、旅の各区間の詳細なセグメントが含まれ、最後に感想が述べられています。撮影は、協立メンテナンスの許可を得て行われました。' where id = '-P0vHKcuGjjx6UuzKZOSh';
update content_bodies set title = 'Riding the LONGEST Bullet Train and Ferry Route from Tokyo🇯🇵 to Seoul🇰🇷 | 4 Day/1800km Journey', description = 'This video documents a four-day journey covering over 1,800 kilometers from Tokyo to Seoul, combining both land and sea travel. The route includes stops in Kyoto, Fukuoka, and Busan, utilizing various trains and a ferry. The total cost of the trip is ¥46,430 (approximately $320). The journey features the N700A and N700S bullet trains from Tokyo to Kyoto and Kyoto to Fukuoka, respectively, followed by the New Camellia ferry from Fukuoka to Busan, and finally the KTX train from Busan to Seoul. The video includes an introduction, detailed segments of each leg of the journey, and concludes with final thoughts. Filming was conducted with permission from Kyoritsu Maintenance.' where id = 'VhGRYoXCjdeBfNJ_P7GeG';
update content_bodies set title = '日本の寝台列車での24時間 | 🇯🇵サンライズエクスプレスツイン', description = 'この動画では、日本のサンライズエクスプレス寝台列車での24時間の旅を紹介しています。東京から出雲まで「シングル」ルームで移動し、「サンライズツイン」ルームで帰る様子が描かれています。両方のルームタイプの料金は¥23,210で、ツインは2人で利用しても同じ料金です。動画には、イントロダクション、地図とスケジュールの概要、シャワー設備を含む詳細なルームツアーが含まれています。また、出雲と有名な出雲大社への訪問も紹介されています。この体験は rejuvenating（若返る）と表現され、旅行者は5歳若返ったように感じるとされています。動画は視聴者への感謝のメッセージで締めくくられています。' where id = 'OIoFA_4lcp4T70RWt9RkI';
update content_bodies set title = '24 Hours on Japan’s Sleeper Train | 🇯🇵Sunrise Express Twin', description = 'This video showcases a 24-hour journey on Japan''s Sunrise Express sleeper train, traveling from Tokyo to Izumo in a ''Single'' room and returning in a ''Sunrise Twin'' room. The cost for both room types is ¥23,210, which is the same for two people in the Twin. The video includes an introduction, a map and schedule overview, and a detailed room tour, including the shower facilities. It also features a visit to Izumo and the famous Izumo Taisha shrine. The experience is described as rejuvenating, making travelers feel five years younger. The video concludes with a thank you message to viewers.' where id = 'sMArdvbHXzX9yce25dlfH';
update content_bodies set title = '稻佐之濱的夕陽', description = '島根に位置する稻佐之濱は、日本の精神と原風景を体現した美しい景色を提供します。ここでの夕陽は詩のように美しく、光に満ちた素晴らしい光景を作り出します。' where id = 'AaBf1dKX24MIwyKCydofR';
update content_bodies set title = 'The Sunset at Inasa Beach', description = 'Inasa Beach in Shimane offers breathtaking views that embody the beauty of Japan''s spirit and its natural landscapes. The sunset here is picturesque, creating a stunning scene filled with light.' where id = 'fsuzU00zhYDq2LBoeoRfZ';
update content_bodies set title = '宍道湖的夕陽', description = '島根の美しい風景を代表する宍道湖の夕陽は、まるで詩のように美しく、日本の精神と原風景を感じさせる絶景です。光が織りなす美しい景色は、訪れる人々に感動を与えます。' where id = 'uMx8K8v_z-6cSUgCOWuhE';
update content_bodies set title = 'Sunset at Lake Shinji', description = 'Lake Shinji offers breathtaking views, showcasing the beauty of Japan''s spirit and its natural landscapes. The sunset at Lake Shinji is described as picturesque, creating a stunning visual experience.' where id = '0G2BCGGF0TVxw4mdV7Acz';
update content_bodies set title = '2日間の富士山観光列車旅行 | 東京から富士山へ 🇯🇵', description = 'この2日間の旅では、日本の山々を通り、春の富士山の美しさを体験します。地元の食事や絶景が楽しめる内容です。料金は新宿から河口湖までが4,130円、甲府から河口湖までが1,770円です。利用する列車は富士急行と富士山ビュー特急で、最適な景色を楽しむための座席が推奨されています。旅程は富士山と河口湖周辺の観光スポットを2日間にわたってカバーしており、象徴的な風景を楽しむのに最適な方法です。' where id = 'vIn-gt8G5w4APuM3vJsD3';
update content_bodies set title = '2 Day Scenic Mount Fuji Train Trip | Tokyo to Mount Fuji 🇯🇵', description = 'This 2-day journey takes you through Japan''s mountains to experience the beauty of Mount Fuji in spring. The trip includes local food and breathtaking views. The travel fees are ¥4,130 from Shinjuku to Kawaguchiko and ¥1,770 from Otsuki to Kawaguchiko. The train options are the Fuji Excursion and Fujisan View Express, with a recommended seat for optimal views. The itinerary covers scenic spots around Mount Fuji and Kawaguchiko over two days, making it an ideal way to enjoy the iconic landscape.' where id = '8OfuAi_ux5r9a8-CW8env';
update content_bodies set title = '春の日本初のファーストクラス寝台列車での10時間 | 🇯🇵 サンライズエクスプレス', description = 'この動画では、日本初のファーストクラス寝台列車「サンライズ瀬戸」に乗り、春の桜の季節に東京から岡山、姫路、神戸までの10時間の旅を記録しています。東京から岡山までの料金は27,950円（約190ドル）です。動画では、サンライズシングルデラックスの部屋やアメニティ、シャワールームのツアーが紹介され、桜を楽しみながらの夕食や岡山、姫路、神戸の美しい景色も見どころです。旅の途中で不快感を訴えつつ、最後には視聴者への感謝の言葉が述べられています。' where id = 'WfAmt6GNis9ffMLiBHlh1';
update content_bodies set title = '10 Hours on Japan’s First-Class Sleeper Train in Spring | 🇯🇵 Sunrise Express', description = 'This video documents a 10-hour journey on Japan''s first-class sleeper train, the Sunrise Seto Sleeper Express, during the spring cherry blossom season. The trip starts in Tokyo and includes stops in Okayama, Himeji, and Kobe. The fare for the Tokyo-Okayama route is ¥27,950 (approximately $190). The experience features a tour of the Sunrise Single Deluxe room, amenities, and a shower room. The video also showcases a dinner with cherry blossoms and highlights the scenic views of Okayama, Himeji, and Kobe. The creator expresses discomfort during the journey but thanks viewers at the end.' where id = 'LL-T79T3hDf6ej2JXBMSP';
update content_bodies set title = '日本で最も雪の多いファーストクラス寝台列車での22時間 | 🇯🇵 サンライズエクスプレス', description = 'この動画では、日本で最も雪の多いファーストクラス寝台列車、サンライズ出雲とサンライズ瀬戸を利用した24時間の旅を紹介しています。東京から出雲へ、そして再び東京へ戻る旅の中で、ファーストクラスでの寿司や、期待以上の味のそばを楽しむ様子が描かれています。動画では、ルームツアーや列車ツアー、出雲大社などの訪問も含まれ、旅の詳細な行程が紹介されています。旅の総費用や、利用可能な異なる列車サービスや座席オプションについての情報も提供されています。雪景色の美しさと寝台列車の快適さが強調されています。' where id = 'aJkPTtsLWmTyPkdAw1w_m';
update content_bodies set title = '22 Hours on Japan’s Snowiest First-Class Sleeper Train | 🇯🇵 Sunrise Express', description = 'This video documents a 24-hour journey on Japan''s snowiest first-class sleeper train, the Sunrise Izumo and Sunrise Seto, traveling from Tokyo to Izumo and back. The journey includes various experiences such as enjoying sushi in first class, exploring train amenities, and tasting soba, which exceeds expectations. The video features a detailed itinerary, including a room tour, train tour, and visits to Izumo Taisha and other locations. The total costs for the journey are provided, along with insights into the different train services and seating options available. The experience highlights the beauty of snowy landscapes and the comfort of traveling by sleeper train.' where id = '4nR920VN4ZaDkZqEoZmpW';
update content_bodies set title = '日本の6000ドルの最も豪華な寝台列車での2日間 🇯🇵 | トレインスイート四季島', description = 'この動画では、6000ドルの日本の豪華寝台列車、四季島での旅を紹介しています。旅は31時間38分にわたり、東京から新潟、長野、山梨を経て再び東京に戻ります。乗客は、日本料理、中華料理、フランス料理などの高級料理を楽しみながら、列車の豪華な設備を体験します。動画のハイライトには、列車のツアー、新潟での芸妓のパフォーマンス、ぶどう畑での朝食が含まれています。贅沢な旅行の本質を捉え、旅の間のリラクゼーションと楽しみを強調しています。' where id = 'pgpGRRNbfPK4j7ywX7bBC';
update content_bodies set title = '2 Days on Japan’s $6000 Most Luxurious Sleeper Train 🇯🇵 | Train Suite Shikishima', description = 'This video showcases a journey on Japan''s luxurious sleeper train, the Shikishima, which costs $6000. The trip spans 31 hours and 38 minutes, covering a route from Tokyo to Niigata, Nagano, Yamanashi, and back to Tokyo. Passengers enjoy exquisite cuisine, including Japanese, Chinese, and French dishes, while experiencing the train''s opulent amenities. Highlights include a tour of the train, a performance by Geigi in Niigata, and a breakfast at a grape vineyard. The video captures the essence of luxury travel, emphasizing relaxation and enjoyment throughout the journey.' where id = 'iUdxlT15VnF2Tkw4KefQE';
update content_bodies set title = '日本の最小寝台列車ルームでの2日間 | サンライズエクスプレス', description = 'この動画では、日本の最小寝台列車であるサンライズエクスプレスの旅を紹介します。『ソロ』ルームクラスの上段と下段のベッドを利用し、出雲での美しい夏の風景や地元の料理を楽しみます。東京から出雲への往復ルートをカバーし、費用は約£210/$270です。動画は、イントロダクション、地図と費用の内訳、下段と上段のソロルームのツアー、出雲の探索、列車からの朝日など、さまざまなセグメントで構成されています。最後には視聴者への感謝のメッセージで締めくくられています。' where id = 'UxRlbEqA9GmGAZfeDhzUj';
update content_bodies set title = '2 Days on Japan’s TINIEST Sleeper Train Room | Sunrise Express', description = 'This video showcases a journey on Japan''s smallest sleeper train rooms aboard the Sunrise Express. The experience includes using both the upper and lower berths of the ''Solo'' room class while enjoying the beautiful summer scenery and local cuisine in Izumo. The trip covers a round trip route from Tokyo to Izumo and back, with a total cost of approximately £210/$270. The video features various segments, including an introduction, a map and cost breakdown, a tour of the lower and upper Solo rooms, exploration of Izumo, and a sunrise view from the train. The content concludes with a thank you message to viewers.' where id = 'GkDC3dDBg2PtU0L1bOEqp';
update content_bodies set title = 'なぜ私はこれを続けるのか？！富士宮、日本', description = '富士宮を訪れることは、特に象徴的な富士山を背景にしたユニークな体験を提供しますが、私たちの旅行中にはその姿を見ることができませんでした。それでも、この地域には訪れる価値のあるアクティビティが豊富にあります。バンジージャンプやバギーライド、さらには伝統的なハンコ作りなど、楽しめる選択肢がたくさんあります。また、地元のフルーツゼリーも美味しいおやつです。富士山のより良い景色を求めて再訪したいと思わせる魅力が富士宮にはあります。' where id = '7QYHcOKtB44DXAUQPt7tm';
update content_bodies set title = 'Why do I keep doing this?! Fujinomiya, Japan', description = 'Visiting Fujinomiya, Japan, offers a unique experience, especially with the iconic Mt. Fuji as a backdrop, although it wasn''t visible during our trip. Despite this, the area is rich in activities that make the visit worthwhile. From bungy jumping to buggy rides, and even making traditional hanko stamps, there are plenty of fun options to explore. The local fruit jelly is also a delightful treat. I found myself wanting to return for a better view of Mt. Fuji, highlighting the charm of Fujinomiya beyond just the mountain.' where id = '8CTwMChSUacVLzxeIpkv2';
update content_bodies set title = '私の餅への愛は限りない', description = '餅は最高の日本食であり、異論があれば戦うと著者は述べています。この動画はTCVBと朝日新聞社のスポンサーによって制作され、著者が東京で初めて餅つき祭りに参加した様子が紹介されています。この祭りは文化財に指定されている世田谷代田八幡神社で行われました。著者はPatreonでの支援を呼びかけ、追加コンテンツや早期アクセスを提供しています。また、Instagramのアカウントも紹介されており、個人的な投稿やパフォーマンス関連の情報が共有されています。動画にはArtlistとMusicbedからの音楽が使用されており、視聴者がこれらのリソースにアクセスできるリンクも提供されています。さらに、著者は好みの宿泊施設や撮影・編集機材のリストも共有しています。' where id = 'zJFGSMsaU3bAEw129FqDG';
update content_bodies set title = 'My love for mochi knows no bounds', description = 'Mochi is celebrated as the best Japanese food, and the author invites debate on this opinion. The video is sponsored by TCVB and Asahi Shinbun Publications, showcasing the author''s experience at their first Mochi Tsuki festival in Tokyo. This festival took place at Setagaya Daita Hachiman Jinja, a site recognized as a cultural treasure. The author encourages support through Patreon for additional content and early access, and shares their Instagram handles for personal and performance-related content. The video features music from Artlist and Musicbed, with links provided for viewers to access these resources. Additionally, the author shares their preferred accommodation options and lists their filming and editing gear.' where id = 'AUNl3NTn3nl4CqMfBSsvq';
update content_bodies set title = '石见の伝統工芸', description = '石见はその素晴らしい美しさと伝統工芸で知られています。この地域では、世代を超えて技術を受け継いできた匠たちの技が披露されており、日本の豊かな文化遺産を反映しています。' where id = 'nwfp7-9DW-K6k3gNsQNaT';
update content_bodies set title = 'Traditional Crafts of Iwami', description = 'Iwami is known for its exceptional beauty and traditional craftsmanship. The region showcases the skills of artisans who have preserved their techniques over generations, reflecting the rich cultural heritage of Japan.' where id = 'jCY7z53_NZuFkZG9GsYaV';
update content_bodies set title = '東京からの異なる日帰り旅行 - 茨城県', description = '茨城県は、東京からの日帰り旅行に最適な場所で、驚くほど多くのアクティビティを提供しています。アウトドア体験が豊富で、エアパーククーや筑波霞ヶ浦環状道路などの観光名所があります。この地域はアクセスが良く、東京の喧騒から離れたリフレッシュできる選択肢を提供しています。さらに、茨城に関する情報を得るためのリソースも利用可能です。クリエイターは、Patreonでのサポートを呼びかけており、追加コンテンツや早期アクセスを提供しています。また、SNSのハンドルも共有しており、さらなる交流を促しています。' where id = 'QyXAwZpFZJ2D0wTpNZ-mB';
update content_bodies set title = 'A different kind of Tokyo day-trip - Ibaraki, Japan', description = 'Ibaraki, Japan, offers a surprising array of activities for a day-trip from Tokyo. Visitors can enjoy various outdoor experiences in Ibaraki Prefecture, including attractions like Airpark Coo and the Tsukuba Kasumigaura Ring Ring Road. The region is easily accessible and provides a refreshing alternative to the bustling city life of Tokyo. For those looking for more information, resources such as Ibaraki Info are available. Additionally, the creator encourages support on Patreon for extra content and early access, and shares their social media handles for further engagement.' where id = '1pm4yeSQ-BIY40Nzk3uaB';
update content_bodies set title = '東北、日本：予想外の美しさ', description = '著者は、東北の美しさについて何度も耳にしていたため、実際に訪れることができたことに興奮を表しています。この旅行は東北観光局のおかげで実現し、動画は11月中旬に撮影されたことが示されています。年末に訪れると雪を見ることができると提案しています。また、著者はPatreonを通じて追加コンテンツや早期アクセスを提供していること、個人用とパフォーマンス関連のInstagramアカウントを紹介しています。動画で使用されている音楽はArtlistとMusicbedからのもので、視聴者向けにリンクが提供されています。さらに、著者は好みの宿泊施設を共有し、撮影や編集に使用している機材をリストアップしています。' where id = 'QogC2yWBuvAyuVpW_Ie34';
update content_bodies set title = 'Tohoku, Japan: Not what you’d expect', description = 'The author expresses excitement about visiting Tohoku, Japan, after hearing repeatedly about its beauty. The trip was made possible by the Tohoku tourism board, and the video was filmed in mid-November, suggesting that visiting later in the year would offer a chance to see snow. The author also promotes their Patreon for additional content and early access, along with their Instagram accounts for personal and performance-related updates. Music used in the video is sourced from Artlist and Musicbed, with links provided for viewers. Additionally, the author shares their preferred accommodation and lists filming and editing gear in a kit.' where id = 'PQ6FEnm9FGST21ejM3EtN';
update content_bodies set title = '出雲神楽の公演：火を吹くドラゴンを退治する！', description = '出雲神楽の公演は、日本の伝統文化を通じてドラマチックな物語と鮮やかな舞踏を披露します。この公演では、火を吹くドラゴンと戦う英雄的な行為が描かれ、悪や混沌に対する闘争を象徴しています。島根県の美しい風景を背景に、地域の自然の美しさと文化遺産が強調されます。出雲神楽は単なる公演ではなく、日本の豊かな伝統と自然と民話とのつながりを祝う精神を体現しています。' where id = 'hWAOZdFN2pKvL33_AwCAQ';
update content_bodies set title = 'Iwami-kagura Performance: Fighting off the fire-breathing dragons!', description = 'The Iwami-kagura performance showcases traditional Japanese culture through dramatic storytelling and vibrant dance. This performance features the heroic act of fighting off fire-breathing dragons, symbolizing the struggle against evil and chaos. Set against the backdrop of Shimane Prefecture''s stunning landscapes, the event highlights the region''s natural beauty and cultural heritage. The Iwami-kagura is not just a performance; it embodies the spirit of Japan, celebrating its rich traditions and the connection between nature and folklore.' where id = 'xSdFAnjBPbHN-hBDMRSL8';
update content_bodies set title = '東京から1時間で行ける最高の温泉 - 茨城県、日本', description = '著者は、東京からわずか1時間の茨城県にある特別な温泉を訪れた体験を共有しています。筑波山でのハイキングの後、この温泉がリラックスするのに最適な場所であると感じました。著者は日本の多くの温泉を訪れましたが、この温泉はその中でも特に素晴らしいと考えています。温泉の美しさと魅力が強調されており、アウトドア活動の後にくつろぎたい人にとって必見のスポットとなっています。' where id = 'D0NzCCqNJTLu8bgVo9PmL';
update content_bodies set title = 'The BEST onsen I''ve ever seen only 1 hr from Tokyo - Ibaraki, Japan', description = 'The author shares their experience of visiting an exceptional onsen located just an hour from Tokyo, in Ibaraki. After a day of hiking at Mt. Tsukuba, they found this onsen to be the perfect way to relax. The author has visited many onsens in Japan but considers this one to be at the top of their list. The description highlights the beauty and appeal of the onsen, making it a must-visit destination for those looking to unwind after outdoor activities.' where id = 'ExQD482XDSC1bmzFsS78W';
update content_bodies set title = '石見神楽', description = '石見神楽は、日本の伝統的な舞台芸術であり、島根県の美しい自然景観と日本の精神を表現しています。この芸能は、火を吐く大蛇との戦いを含むドラマティックな演目を特徴としており、善が悪に勝つ象徴的な物語を描いています。石見神楽は、島根の文化に深く根ざしており、その魅力的なパフォーマンスは、素晴らしい風景によって一層引き立てられています。' where id = 'vSQhfBG9rYHxzeoFENvNG';
update content_bodies set title = 'Iwami Kagura', description = 'Iwami Kagura is a traditional Japanese performing art that showcases the beauty of Japan''s spirit and natural landscapes. It features dramatic performances, including the legendary battle against the fire-breathing serpent, symbolizing the triumph of good over evil. The art form is deeply rooted in the culture of Shimane Prefecture, where stunning scenery enhances the experience of this captivating performance.' where id = 'l8B3B7Kxyh1ygwKKfHYhI';
update content_bodies set title = '知っておくべき東京の日帰り旅行', description = 'Yosshiと私は、私のお気に入りの東京の getaway である日光に旅行に行きました。私たちは多くのアクティビティを詰め込みましたが、たとえその一部だけを体験しても素晴らしい時間を過ごせるでしょう。この旅行は東武鉄道のスポンサーによるもので、日光のためのさまざまなチケットが提供されています。追加コンテンツに興味がある方は、Patreonでのサポートをお勧めします。また、Instagramでは個人的なことやパフォーマンス関連の更新を発信しています。動画にはArtlistとMusicbedの音楽が使用されており、私のお気に入りの宿泊施設や撮影機材のリンクも共有しています。' where id = '5wl2hsnsib0gT6ngM3MNn';
update content_bodies set title = 'The Tokyo day-trip you NEED to know about', description = 'Yosshi and I took a trip to Nikko, my favorite getaway from Tokyo. We packed a lot into our visit, and even if you only do a fraction of what we did, you''ll still have a great time. The trip was sponsored by Tobu Railways, which offers various tickets for Nikko. For those interested in more content, I encourage support on Patreon for early access. You can also find me on Instagram for both personal and performance-related updates. The video features music from Artlist and Musicbed, and I share my preferred accommodation options and filming gear links.' where id = 'td6BG0SDkzaxhFuZm6IQe';
update content_bodies set title = '日本の祭りは魔法のようで、餅がいっぱい！高尾山秋祭り', description = '高尾山秋祭りでは、餅や犬、秋の紅葉が織りなす美しい風景を楽しむことができます。東京からのデイトリップに最適なこの祭りでは、伝統的な祭りの雰囲気と自然の美しさが融合し、ドローンショットでその魅力が引き立てられます。参加者は、祭りの視覚と音の中で日本文化に浸ることができる、魔法のような体験を期待できます。' where id = 'LWMteckxzp0J6HycQs974';
update content_bodies set title = 'Japanese festivals are magical and full of mochi! Mt Takao Autumn Matsuri', description = 'Experience the charm of traditional Japanese festivals at the Mt Takao Autumn Matsuri, where mochi, dogs, and vibrant autumn leaves create a picturesque setting. This day trip from Tokyo offers a delightful blend of cultural festivities and natural beauty, enhanced by stunning drone shots. Attendees can expect a magical atmosphere filled with the sights and sounds of a traditional matsuri, making it a perfect getaway for those looking to immerse themselves in Japanese culture.' where id = 'Z4K0ZtQ3104ukQGMxfpxf';
update content_bodies set title = '日本最長の新幹線ルートを5日間乗る 🇯🇵 | 2300kmの長距離旅行', description = 'この動画では、鹿児島から函館までの2300kmにわたる日本最長の新幹線ルートの旅を紹介します。一度に全行程を移動するのではなく、途中で様々な食べ物や観光地を楽しむために立ち寄ります。旅の費用は約£250/$300/¥50,000で、熊本、広島、大阪、仙台などの都市を含む各区間の移動が紹介されています。旅の最後には、美味しい寿司を楽しむシーンで締めくくられます。' where id = 'HoeN6d1QUMmYVRhmQAcSk';
update content_bodies set title = '5 Days on Japan’s LONGEST Bullet Train Route 🇯🇵 | 2300km Long-Distance-Journey', description = 'This video chronicles a journey along Japan''s longest Shinkansen route, covering 2300km from Kagoshima to Hakodate. Instead of traveling the entire distance in one go, the journey includes various stops to explore local food and attractions along the way. The video outlines the cost of the trip, which is approximately £250/$300/¥50,000, and highlights the different segments of the train ride, including stops in cities like Kumamoto, Hiroshima, Osaka, and Sendai. The experience culminates with a delicious sushi meal at the end of the journey.' where id = 'QGyVAn0f0ke43JTN1mqiN';
update content_bodies set title = '島根の絶景 本編', description = '悠久の歴史と文化が息づく島根。美しい日本の原風景を高精細な4K映像で楽しむことができます。島根で本物に出会う旅を始めましょう。' where id = 'y6Js5XWJPvzGIOP4HJUzw';
update content_bodies set title = 'Breathtaking Views of Shimane', description = 'Shimane is a place where ancient history and culture continue to thrive. Experience the nostalgic and beautiful landscapes of Japan through high-definition 4K visuals. Come to Shimane for a journey to encounter authenticity.' where id = '-AXC-5zWekMyvj2b8EP8T';
update content_bodies set title = '日本の豪華個室列車での3日間の食の旅 | しまかぜエクスプレス', description = 'この動画では、日本の豪華個室列車「近鉄しまかぜエクスプレス」に乗り、京都から賢島、さらに伊勢へ向かう3日間の食の旅を紹介しています。旅行の総費用は13,350円で、大人と子供の運賃、プライベートルームの料金が含まれています。体験には松阪牛を含むさまざまな料理が登場します。動画は、列車の到着、座席ツアー、昼食、列車ツアー、賢島でのクルーズ、ホテル到着、夕食、朝食、伊勢での食ツアー、二見神社訪問、A5和牛BBQを楽しむ様子など、各セグメントがタイムスタンプ付きで構成されています。' where id = '61CWiENAalHgHKx2wG-BD';
update content_bodies set title = '3 Day Food Trip on Japan’s Luxury Compartment Train | Shimakaze Express', description = 'This video showcases a three-day food trip aboard Japan''s luxury compartment train, the Kintetsu Shimakaze Express, traveling from Kyoto to Kashikojima and then to Ise. The total cost for the trip is ¥13,350, which includes adult and child fares, as well as a private room fee. The experience features a variety of culinary delights, including MatsuSaka beef. The video includes segments such as the train''s arrival, a seat tour, lunch, a train tour, a cruise in Kashikojima, hotel arrival, dinner, breakfast, and a food tour in Ise, culminating in a visit to the Futami Shrine and enjoying A5 Wagyu BBQ. The video is structured with timestamps for easy navigation.' where id = 'Jggo47ux3B3ee6EbvG-HC';
update content_bodies set title = '日本の6,000ドルのラグジュアリースリーパートレインに乗る | トワイライトエクスプレス水風', description = 'この動画では、6,000ドルのトワイライトエクスプレス水風という豪華なスリーパートレインでの2日間の旅を紹介しています。大阪から下関までのルートをカバーし、ロイヤルツインルームでの体験が含まれています。ルームツアー、ランチ、日本式のティータイム、トレインツアーなど、さまざまなアクティビティが展開されます。また、倉敷へのミニトリップ、パブタイム、ミシュラン3つ星のディナーも紹介されます。翌朝は朝食と錦帯橋へのミニトリップ、ミシュラン2つ星のランチが続き、最後に視聴者への感謝のメッセージで締めくくられます。' where id = '4_svPD1jEtT60IdyzL--7';
update content_bodies set title = 'Riding Japan’s $6,000 Luxury Sleeper Train | Twilight Express Mizukaze', description = 'This video showcases a luxurious two-day journey on the Twilight Express Mizukaze, a sleeper train costing $6,000. The trip covers the route from Osaka to Shimonoseki, featuring a Royal Twin room. The experience includes a variety of activities such as a room tour, lunch, Japanese-style tea time, and a train tour. Viewers also get a glimpse of a mini-trip to Kurashiki, pub time, and a Michelin 3-star dinner. The next morning features breakfast and another mini-trip to Kintai Bridge, followed by a Michelin 2-star lunch. The video concludes with a thank you message to viewers.' where id = 'umICnLFPaa9A_nq0KC15a';
update content_bodies set title = '京都 - 奈良のユニークな観光列車 | 青い吉エクスプレス', description = '青い吉観光列車は、京都から奈良へのユニークな観光体験を提供します。座席はサロンセミコンパートメントとツインシートの2種類があります。京都からの運賃は2,740円（約21ドル）、帰りの運賃は1,740円（約13ドル）です。列車の旅は34分で新宮に到着します。動画では、イントロダクション、地図と費用、座席のツアー、カフェブースでの購入情報、奈良の鹿の訪問が含まれています。鹿の映像は別の日に撮影されたことに注意してください。詳細は近鉄のウェブサイトをご覧ください。' where id = '5NHL0hYxqox5tdUrpDpcp';
update content_bodies set title = 'Kyoto - Nara on Japan’s Unique Excursion Train | Aoniyoshi Express', description = 'The Aoniyoshi Tourist Train offers a unique excursion experience from Kyoto to Nara, featuring two different seat configurations: Salon Semi Compartment and Twin Seat. The fare from Kyoto is 2,740 JPY (approximately 21 USD), while the return fare is 1,740 JPY (about 13 USD). The train journey takes 34 minutes to reach Shingu. The video includes an introduction, a map with costs, a tour of the seating options, information about cafe booth purchases, and a visit to Nara to see the deer. Note that the deer footage was filmed on a different day. For more details, visit the Kintetsu website.' where id = 'bBzlByxEhTm3ygz-3Cjau';
update content_bodies set title = '日本初の寝台列車に乗る | ウエストエクスプレス銀河', description = 'この動画では、京都から新宮までのウエストエクスプレス銀河という新しい寝台列車の旅を紹介します。ソロプライベートコンパートメントでの移動で、315km（200マイル）の距離を12時間以上かけて移動します。このプレミアム体験の料金は30,000円（約200ドル）です。動画には、イントロダクション、地図と料金の概要、部屋のツアー、夕食、朝食、風景のハイライト（滝の神社や地元のマグロなど）が含まれています。ルート沿いの澄んだ水の美しさが強調されています。' where id = 'NWeLErK9pggn3AtgOklKc';
update content_bodies set title = 'Riding on Japan’s First Class Sleeper Train | West Express Ginga', description = 'This video showcases a journey on Japan''s new sleeper train, the West Express Ginga, traveling from Kyoto to Shingu in a solo private compartment. The trip covers a distance of 315 km (200 miles) and takes over 12 hours. The fare for this premier experience is 30,000 JPY (approximately 200 USD). The video includes various segments such as an introduction, a map and cost overview, a room tour, dinner, and breakfast, as well as highlights of the scenic views, including a waterfall shrine and local tuna. The experience emphasizes the beauty of clear waters along the route.' where id = 'adz-QYyYFBKtbxBmXqjFL';
update content_bodies set title = '日本の新しい最安値寝台列車シートに乗る | ウエストエクスプレス銀河', description = 'この動画では、ウエストエクスプレス銀河の最安値寝台列車シートである「のびのびカウチットシート」に乗る様子を紹介しています。料金は非ツアー価格で約80ドル、ホテルを含む往復ツアーは約240ドルです。ルートは新宮から京都までです。動画には、導入部、ルートと料金の詳細、シートツアー、旅の途中での風景や食事のハイライトが含まれています。また、広告の休憩もあり、京都からの感謝のメッセージで締めくくられています。2022年現在、これらのシートはツアーでのみ利用可能で、片道のチケット価格は明記されていません。' where id = 'HRcrsOX0xsQjAStNb7oA9';
update content_bodies set title = 'Riding on Japan’s New Cheapest Sleeper Train Seat | West Express Ginga', description = 'This video showcases a ride on the West Express Ginga, featuring the Nobi Nobi Couchette Seats, which are the cheapest sleeper train seats in Japan. The fare for these seats is approximately 80 USD for non-tour prices, while a round trip including hotel can cost around 240 USD. The route taken is from Shingu to Kyoto. The video includes an introduction, details about the route and fees, a tour of the seats, and highlights of the scenery and food experienced during the journey. It also features breaks for advertisements and concludes with a thank you from Kyoto. As of 2022, these seats are only available through tours, and the one-way ticket price is not specified.' where id = 'qhTUqcH84vvujZvmtm-VE';
update content_bodies set title = '日本の素晴らしい夜行列車に乗る 🇯🇵 | サンライズ瀬戸「シングル」', description = 'この動画では、日本の夜行列車、サンライズ瀬戸スリーパーエクスプレスに乗り、東京から高松までの旅を紹介します。料金は22,540円（約150ドル）です。動画では、ルートや価格、ショッピングオプションについての詳細が含まれています。部屋のツアーや夕食、朝食を楽しむ様子が紹介されており、 onboardで提供される美味しい食事が強調されています。列車のツアーでは、利用可能なアメニティについての情報が提供され、高松（四国）への到着で締めくくられます。動画の最後には視聴者への感謝のメッセージがあります。' where id = 'GaLOqZ17-sT5emal5DICk';
update content_bodies set title = 'Riding Japan’s Amazing Overnight Train 🇯🇵 | Sunrise Seto “Single”', description = 'This video showcases a journey on Japan''s overnight train, the Sunrise Seto Sleeper Express, traveling from Tokyo to Takamatsu. The fare for this experience is 22,540 JPY (approximately 150 USD). The video includes details about the route, pricing, and shopping options. Viewers can enjoy a room tour, dinner, and breakfast, highlighting the delicious food served on board. The train tour provides insights into the amenities available, culminating in the arrival at Takamatsu in Shikoku. The video concludes with a thank you message to the audience.' where id = '3XCcL02JI_JRQoswrJ-mI';
update content_bodies set title = '世界最速の列車に乗る | 🇯🇵 603km/h 磁気浮上式 L0', description = 'この動画では、世界最速の列車である超伝導磁気浮上式L0に乗る様子が紹介されています。この列車は603km/h（375mph）に達することができます。東京から大阪までの運賃は約16,000円（約120ドル）と見積もされています。全体のプロジェクト費用は約10兆円（750億ドル）と予測されています。東京から大阪までのルートは430km（270マイル）で、わずか67分で移動します。動画には、イントロダクション、地図と価格の詳細、磁気浮上技術の説明、テスト走行のコンピレーション、乗車の様子、秘密のプロトタイプ走行が含まれています。将来的には、2027年に東京から名古屋、2045年に名古屋から大阪へのルートが計画されています。' where id = 'W1Qs-_ySljQziKw_a-3K9';
update content_bodies set title = 'Riding the World’s Fastest Train | 🇯🇵 603km/h Maglev L0', description = 'This video features a ride on the Superconducting Maglev L0, the fastest train in the world, capable of reaching speeds of 603 km/h (375 mph). The estimated fare for a trip from Tokyo to Osaka is 16,000 JPY (approximately 120 USD). The overall project cost is projected to be around 10 trillion JPY (75 billion USD). The train operates on a route from Tokyo to Osaka, covering 430 km (270 miles) in just 67 minutes. The video includes an introduction, a map and pricing details, an explanation of how Maglev technology works, a compilation of test runs, boarding footage, and a secret prototype run. Future expansions include a route from Tokyo to Nagoya by 2027 and from Nagoya to Osaka by 2045.' where id = 'E5p-sRqPywTjt2zuB2M5j';
update content_bodies set title = '日本の素晴らしい夜行ファーストクラス列車に乗る | 西エクスプレス銀河「ファーストシート」', description = 'この動画では、日本の新しい夜行ファーストクラス列車、西エクスプレス銀河の「ファーストシート」に乗る旅を紹介しています。ルートは京都から出雲までの往復で、料金は45,000円（約340ドル）です。体験には、列車のツアーやファーストクラスの座席の詳細、そばのスープなどの食事が含まれています。動画では、列車の入口、夕食、深夜の食事、2日目の朝食、出雲到着、温泉のおすすめなど、旅のさまざまな側面がカバーされています。このユニークな列車での旅行の贅沢さと快適さが強調されています。' where id = '4U5S5PcsFdzq-wTPN3ogJ';
update content_bodies set title = 'Riding on Japan’s Amazing Overnight First Class Train | West Express Ginga “First Seat”', description = 'This video showcases a journey on Japan''s new overnight first-class train, the West Express Ginga, specifically in the ''First Seat'' section. The round trip route is from Kyoto to Izumo, with a fare of 45,000 JPY (approximately 340 USD). The experience includes a tour of the train, a detailed look at the first-class seating, and meals such as buckwheat soup. The video covers various aspects of the trip, including the entrance to the train, dinner, a midnight meal, breakfast on the second day, and arrival at Izumo, along with recommendations for hot springs. The overall experience highlights the luxury and comfort of traveling by this unique train.' where id = 'S58Nuu2s0YKsPDN7F3vtH';
update content_bodies set title = '日本の素晴らしい豪華列車に乗る | サフィール踊り子プレミアムグリーン', description = 'この動画では、日本の最も豪華な列車、サフィール踊り子に乗り、東京から熱海までの旅を紹介しています。料金はグリーンクラスが6,640円（50ドル）、プレミアムグリーンクラスが8,140円（60ドル）です。ルートには伊東と品川が含まれています。体験のハイライトには、列車のツアー、車内で提供される美味しいパスタの食事、温泉で知られる熱海の訪問が含まれています。動画は、イントロダクション、列車の入口、座席の詳細、食事体験などのさまざまなセグメントで構成され、最後に視聴者への感謝のメッセージで締めくくられています。' where id = 'YMPxGqMg_OWp3JgUcvEpf';
update content_bodies set title = 'Riding on Japan’s Amazing Luxurious Train | Saphir Odoriko Premium Green', description = 'This video showcases a journey on Japan''s most luxurious train, the Saphir Odoriko, traveling from Tokyo to Atami. The ticket prices are 6,640 JPY (50 USD) for Green Class and 8,140 JPY (60 USD) for Premium Green Class. The route includes stops at Ito and Shinagawa. The experience highlights include a tour of the train, a delicious pasta meal served on board, and a visit to Atami, known for its hot springs. The video features various segments, including an introduction, train entrance, seat details, and dining experiences, concluding with a thank you message to viewers.' where id = 'lENw1FTZfaASDDfik4-Jn';
update content_bodies set title = '日本初のファーストクラス夜行列車に乗る | ウエストエクスプレス銀河プレミア', description = 'この動画では、日本のファーストクラス夜行列車「ウエストエクスプレス銀河」のプレミアルームに乗車し、出雲から京都までの旅を紹介します。料金は1人あたり30,000〜40,000円（約250〜300ドル）です。動画には、イントロダクション、スケジュールとルートの詳細、列車と個室のツアー、夕食や深夜のおやつを含む食事体験のハイライトが含まれています。旅は朝のセグメントと視聴者への感謝のメッセージで締めくくられます。' where id = 'PH70hgUSd7i27iSChA5d9';
update content_bodies set title = 'Riding on Japan’s First Class Overnight Train | West Express Ginga Premier', description = 'This video showcases a journey on Japan''s first-class overnight train, the West Express Ginga, specifically in its Premier room, traveling from Izumo to Kyoto. The fare ranges from 30,000 to 40,000 JPY (approximately 250 to 300 USD) per person. The video includes an introduction, details about the schedule and route, a tour of the train and the private compartment, and highlights of the dining experience, including dinner and a midnight snack. The journey concludes with a morning segment and a thank you message to viewers.' where id = 'XYEVRcYP8yXEX1lJzR-_f';
update content_bodies set title = '日本最安の夜行列車に乗る | サンライズエクスプレス', description = 'この動画では、東京から琴平までのサンライズ瀬戸エクスプレスの旅を紹介します。料金は15,000円（約110ドル）で、ノビノビ寝台を利用したユニークな睡眠体験ができます。動画には、イントロダクション、券売機のラーメンスタンド訪問、座席紹介、連結解除イベント、瀬戸大橋の美しい景色、朝食、シャワー体験などのセグメントが含まれています。琴平に到着する前に、視聴者への感謝のメッセージで締めくくられます。' where id = 'jVlhODf0UQIZ_SKbnyDAW';
update content_bodies set title = 'Riding on Japan’s Cheapest Overnight Train | Sunrise Express', description = 'In this video, we embark on a journey aboard the Sunrise Seto Express, traveling from Tokyo to Kotohira. The fare for this trip is 15,000 JPY (approximately 110 USD). The train features Nobi Nobi Berths, providing a unique sleeping experience. The video includes various segments such as an introduction, a visit to a vending machine ramen stand, a seat introduction, an uncoupling event, and a scenic crossing over the Great Seto Sea. Additionally, viewers can enjoy breakfast and a shower experience before arriving at Kotohira. The video concludes with a thank you message for the audience.' where id = '16XBIEln9VDfO5jlU1Kzp';
update content_bodies set title = '日本の最も豪華なプライベートコンパートメントに乗る | サフィール踊り子', description = 'この体験では、サフィール踊り子の特急列車に乗車し、豪華なプライベートコンパートメントを楽しみます。料金は27,750円（210ドル）で、東京から伊豆急下田までのルートです。プライベートファーストクラスコンパートメントは最大6人まで収容可能で、特別な旅行体験を提供します。動画には、イントロ、列車の到着、部屋のツアー、メニューの確認、ランチ、伊豆の海岸線の景色、デザート、結論が含まれています。また、体験の一部として400円のオレンジジュースも提供されます。' where id = 'wAmVAtpnqGrc3qmaUmvKw';
update content_bodies set title = 'Riding on Japan''s Most Luxurious Private Compartment | Saphir Odoriko', description = 'This experience features a ride on the Saphir Odoriko limited express, known for its luxurious private compartments. The journey costs 27,750 JPY (210 USD) and travels from Tokyo to Izukyu Shimoda. The private first-class compartment accommodates up to six passengers and offers a unique travel experience. The video includes an introduction, the train''s arrival, a room tour, a menu check, lunch, views of the Izu shoreline, dessert, and a conclusion. An orange juice priced at ¥400 is also part of the experience.' where id = 'Se5rOo6dk1daSziylRBiS';
update content_bodies set title = '日本の素晴らしい夜行列車に乗る | ツインベッド個室', description = 'この動画では、日本のサンライズ出雲号のツインベッド個室での旅を紹介しています。料金は30,000円（230ドル）で、東京から出雲までのルートです。体験内容には、サンライズエクスプレスキットの詳細なツアー、弁当探し、部屋のツアーが含まれています。夕食ツアー、列車ツアー、朝の体験も楽しめます。また、サンライズ列車の切り離し、朝食の選択肢、沿線の美しい風景も紹介されています。旅のまとめでは、このユニークな夜行列車の旅を総括しています。' where id = 'mWVEzPQpFjHiIywYFj1xO';
update content_bodies set title = 'Riding on Japan’s Amazing Overnight Train | Twin Bed Compartment', description = 'This video showcases a journey on Japan''s Sunrise Izumo Express, featuring a Twin bed compartment. The trip costs 30,000 JPY (230 USD) and runs from Tokyo to Izumo. The experience includes a detailed tour of the Sunrise Express Kit, bento hunting, and a room tour. Viewers can enjoy a dinner tour, a train tour, and a morning experience on the train. The video also highlights the uncoupling of the Sunrise train, breakfast options, and the beautiful scenery along the route. The trip summary wraps up the experience, providing a comprehensive look at this unique overnight train journey.' where id = 'shCNzV4MRv-DL6mcBpg1D';
update content_bodies set title = '日本の素晴らしい自動販売機列車に乗る | Hinotori Express', description = 'この動画では、近鉄鉄道のHinotori列車に乗る様子を紹介しています。新幹線の代わりに、より手頃でありながら豪華な体験を提供します。大阪から名古屋までの料金は4,540円（40ドル）で、普通席が用意されています。視聴者は、ナビゲーション、乗車、座席レビュー、ロッカー、そして自動販売機や食事のオプションなど、列車の設備の詳細な体験を期待できます。また、トイレのレビューもあり、味噌カツを含むランチで締めくくられます。この列車のユニークな特徴を魅力的に紹介しています。' where id = 'nRV85q6VGvSJf84ObBi-X';
update content_bodies set title = 'Riding Japan’s Incredible Vending Machine Train | Hinotori Express', description = 'This video showcases a journey on the Kintetsu Railway''s Hinotori train, which offers a luxurious yet affordable alternative to the shinkansen. The trip from Osaka to Nagoya costs 4,540 JPY (40 USD) and features ordinary class seating. Viewers can expect a detailed experience, including navigation, boarding, a seat review, and a tour of the train''s amenities such as lockers, vending machines, and food options. The video also highlights a bathroom review and concludes with a lunch featuring Miso Katsu. Overall, it provides an engaging look at the unique features of this train.' where id = 'LoTuDjIdVt5KPPMukDdOR';
update content_bodies set title = '日本の最も豪華な新幹線シートに乗る | グランクラス', description = 'この動画では、日本の新幹線で最も豪華なファーストクラスシートであるグランクラスを体験します。このシートは最も高価なオプションで、料金は17,900円（155ドル）で、特定の路線でのみ提供されています。具体的には、東京から仙台までのE5やまびこ59号で利用可能です。動画には、イントロダクション、ファーストクラスラウンジのツアー、乗車、シートレビュー、弁当ランチの楽しみ、ファーストクラスのトイレの探検、雪景色を楽しむシーンなどが含まれています。全体的な体験は、グランクラスの静けさによって強調されています。' where id = 'R7mqqPAK6lSNqLjj5mXnn';
update content_bodies set title = 'Riding Japan''s Most LUXURIOUS Shinkansen Seat | Gran Class', description = 'In this video, the presenter experiences the most luxurious first-class seat on the Japanese Shinkansen, known as Gran Class. This exclusive seat is the most expensive option available, priced at 17,900 JPY (155 USD), and is offered on select routes, specifically from Tokyo to Sendai on the E5 Yamabiko 59 train. The video includes various segments such as an introduction, a tour of the first-class lounge, boarding the train, a detailed seat review, enjoying a bento lunch, exploring the first-class washroom, and taking in the scenic views of snow-covered landscapes during the journey. The overall experience is highlighted by the tranquility of the Gran Class environment.' where id = 'TIGWmiXoSLzffw7Yx3k6G';
update content_bodies set title = '日本の雪景色を走る寝台列車エクスプレス | サンライズ出雲', description = 'この動画では、東京から日本の雪景色へ向かうサンライズ出雲寝台列車の旅を紹介しています。列車の部屋のツアー、夕食、シャワー、夜景を楽しむ様子が含まれています。また、連結解除のシーンや朝食、雪景色の美しさも捉えています。料金は23,210円（200ドル）で、シングルシートの旅を提供し、新年を楽しく迎えることを目的としています。' where id = 'Gh_ll1_5h2oZc1zz_umH2';
update content_bodies set title = 'Riding Japan''s Snowy Sleeper Train Express | Sunrise Izumo', description = 'This video showcases a journey on the Sunrise Izumo Sleeper Train, traveling from Tokyo to the snowy landscapes of Japan. The experience includes a tour of the train room, dinner, a shower, and enjoying night views. The video captures moments such as the uncoupling scene and breakfast while highlighting the beautiful snow scenery. The trip is priced at 23,210 JPY (200 USD) for a single seat, and it aims to provide viewers with a joyful start to the New Year.' where id = 'ZUHzScmGXUZ09mPOFDIVK';
update content_bodies set title = '東京からの4,000円の日帰り旅行：長野を探索 | 新幹線、ストリートフード、温泉', description = '今日は東京から長野への日帰り旅行をしました。新幹線を含むさまざまな列車を利用し、歴史的な観光スポットを訪れ、温泉を楽しみ、たくさんの食べ物を味わいました。旅行の総費用は18,120円（約160ドル）ですが、JRパスを利用すれば25〜40ドルに抑えることができます。ルートは東京から長野、松本、諏訪を経て再び東京（新宿）に戻るものでした。使用した列車はE7新幹線、383しなの、E353あずさで、普通席を利用しました。また、卵を茹でるのが得意だとも述べています。' where id = 'EwbCTUsy8JIGeVbqxYRM0';
update content_bodies set title = '$40 Day Trip from TOKYO Exploring NAGANO, Japan | Shinkansen, Street Food, Hot Spring', description = 'This day trip from Tokyo to Nagano involved various train rides, including the shinkansen. The journey included visits to historic sightseeing spots, enjoying a hot spring, and indulging in local street food. The total cost for the trip was 18,120 JPY (approximately 160 USD), but it can be reduced to between 25-40 USD with a JR Pass. The route taken was from Tokyo to Nagano, then Matsumoto, Suwa, and back to Tokyo (Shinjuku). The trains used were the E7 Shinkansen, 383 Shinano, and E353 Azusa, with an ordinary seat. The traveler also mentioned a personal skill in boiling eggs.' where id = 'Mt7seqkK_oZeMxAe46lfA';
update content_bodies set title = '$21で東京から大阪へ（ローカル列車、11時間の旅）', description = '私は東京から大阪まで、ローカル列車を利用して11時間の旅をし、料金はわずか21ドルでした。この旅は、JRのローカル列車が無制限に利用できる1日用の休日パス「青春18きっぷ」を使って実現しました。旅の総費用は2410円（約21ドル）で、ルートは東京から浜松、京都を経由して大阪のJR難波駅に到着しました。座席は2 + 2のボックスシートでした。全体的に、非常に安価な体験であり、予算を気にする旅行者にとっては価値のある選択肢です。' where id = '4GlkFmbqcBnpk17ZITi_M';
update content_bodies set title = '$21 TOKYO to OSAKA by Local Train (11Hour Journey)', description = 'I took an 11-hour journey from Tokyo to Osaka for just $21 using the Local Train. The trip was made possible with the Seishun 18 ticket, which is a one-day holiday pass allowing unlimited travel on all JR local trains. The total fee for the journey was 2410 JPY (approximately 21 USD). The route included stops at Hamamatsu and Kyoto before arriving in Osaka at JR Namba station. I traveled in a box seat configuration of 2 + 2. Overall, the experience was quite economical, making it a worthwhile option for budget travelers.' where id = 'QEPQV4JNQugR1pwv46SEN';
update content_bodies set title = '日本の豪華なファーストクラス寝台列車に乗る', description = '私は高松から東京まで、豪華なファーストクラス寝台列車であるサンライズ瀬戸号に乗りました。この旅の料金は28,820円（約250ドル）でした。ルートは高松から東京までで、ファーストクラスシングルデラックスの座席に座りました。体験の興奮があまりにも大きく、旅の詳細をほとんど思い出せないほどでした。時刻表の詳細についてはjprail.comを、JRパスの情報についてはjapanrailpass.netを訪れてください。' where id = 'zPIXEoWa2IIiFsijwGkIM';
update content_bodies set title = 'Riding Japan''s Luxurious FIRST CLASS Sleeper Train', description = 'I experienced the Sunrise Seto Express Train, traveling from Takamatsu to Tokyo on a luxurious first-class sleeper train. The fare for this journey was 28,820 JPY (approximately 250 USD). The route taken was from Takamatsu to Tokyo, and I was seated in a First Class Single Deluxe compartment. The excitement of the experience was so overwhelming that I found myself unable to recall many details of the journey. For more information on the timetable, you can visit jprail.com, and for JR Pass details, check japanrailpass.net.' where id = 'U5eLCMNHpGVv1hgmrjDK3';
update content_bodies set title = '日本のハロウィンの楽しみ方 - 東京 2018', description = '著者は、東京の渋谷での初めてのハロウィン体験を共有し、活気あるパーティーの雰囲気と驚くべきコスチュームが特徴的なイベントであることを強調しています。このお祭りを非常に楽しんでおり、他の人にもおすすめしています。しかし、ハロウィンの祭りには奇妙な人々がいる可能性があるため、安全に過ごすように注意を促しています。また、著者はPatreonを通じて追加コンテンツや早期アクセスの支援を呼びかけ、個人用とパフォーマンス用のInstagramアカウントへのリンクを提供しています。さらに、動画で使用した音楽や撮影・編集機材のリンクも共有しています。' where id = 'uuYw1g5sdh7isZ_KqIOoG';
update content_bodies set title = 'HOW JAPAN DOES HALLOWEEN - Tokyo 2018', description = 'The author shares their first experience of Halloween in Shibuya, Tokyo, highlighting the vibrant party atmosphere and the incredible costumes that characterize the event. They express their enthusiasm for the celebration, recommending it to others. However, they also caution viewers to stay safe, noting that unusual individuals may be present during Halloween festivities. The author encourages support through Patreon for additional content and early access, and provides links to their Instagram accounts for both personal and performance-related content. Additionally, they share links to the music used in their videos and their filming and editing gear.' where id = 'wdp3vdMNOUy-liP9QWeLB';
update content_bodies set title = '【ドローン映像】長崎ばーどアイ4K　「牧場の里あづま」', description = '『長崎ばーどアイ』では、四季折々の長崎の風景を4Kドローン映像で楽しむことができます。この映像は、2020年の夏に雲仙市吾妻町にある牧場の里あづまを撮影したもので、長崎の美しい景色を堪能できる内容となっています。' where id = '-MfHdVUJfT05p0DDp3SfF';
update content_bodies set title = 'NAGASAKI Bird''s Eye - 4K Drone Footage: BOKUJOU NO SATO AZUMA', description = 'Experience the stunning landscapes of Nagasaki through 4K drone footage. This video showcases the beauty of BOKUJOU NO SATO AZUMA, located in Unzen City, Nagasaki, during the summer of 2020. Enjoy the breathtaking views and discover the amazing places that Nagasaki has to offer.' where id = 'Otu9-HW7RgOM8j4CYPyH8';
update content_bodies set title = '食事サービス付きの日本のプライベートラグジュアリーコンパートメント列車に乗る | 大阪から三重へ', description = '私は近鉄しまかぜの日本式プライベートルームを体験しました。この部屋は非常に人気があるため、早めの予約が必要です！料金は11,130円（約100ドル）で、大阪難波から賢島までのルートを走る特急列車です。この体験は、プレミアムなサービスにしては手頃な価格であり、プライベートルームの特別感が旅をより思い出深いものにしています。' where id = 'jqV3BnLR8ooBWhVrjoN9y';
update content_bodies set title = 'Riding Japan''s Private Luxury Compartment Train with Food Service | Osaka to Mie', description = 'I had the opportunity to experience the Kintetsu Shimakaze, a luxury train offering a private Japanese-style room. This unique travel experience runs from Osaka Namba to Kashikojima and is highly sought after, so booking in advance is essential. The fee for this journey is 11,130 JPY (approximately 100 USD), which is considered affordable for such a premium service. The train is a limited express, and the private room adds an exclusive touch to the trip, making it a memorable way to travel in Japan.' where id = 'z2RKUnvsjGAn7NI2Cadnp';
update content_bodies set title = '東京から九州への最長の片道新幹線ルート | 東京 - 鹿児島中央', description = '本日は、日本の広大な鉄道網を利用して、最南端の新幹線駅である鹿児島中央駅へ向かいます。このファーストクラスの体験の運賃は40,000円（約350ドル）です。ルートは東京から鹿児島中央までで、N700SおよびN700の列車を利用します。この体験は、寝台列車の懐かしさを呼び起こすことを目的としています。' where id = '4eXMkbpOk8K0CcEhprgbL';
update content_bodies set title = 'LONGEST One-way Shinkansen Route from Tokyo in FIRST CLASS | Tokyo - Kyushu', description = 'This journey takes us on Japan''s extensive rail network to the southernmost Shinkansen station, Kagoshima-chuo. The fare for this first-class experience is 40,000 JPY (approximately 350 USD). The route spans from Tokyo to Kagoshima-Chuo, utilizing the N700S and N700 trains. The experience aims to evoke the nostalgia of sleeper trains.' where id = 'njP5dmLkv1evNjyj01xKI';
update content_bodies set title = '【ドローン映像】長崎ばーどアイ4K　「向後崎警備所跡」', description = '『長崎ばーどアイ』では、4Kドローン映像を通じて四季折々の長崎の風景を楽しむことができます。この映像は、2020年の夏に佐世保市俵ケ浦町で撮影されました。特別な許可のもとで撮影されており、向後崎警備所跡の美しい景観が映し出されています。' where id = 'el8yZuwl4MGiWDtm4frEu';
update content_bodies set title = 'NAGASAKI Bird''s Eye - 4K Drone Footage', description = 'Experience the stunning landscapes of Nagasaki through 4K drone footage in this video featuring the Kougozaki Keibisho. Filmed in Sasebo, Nagasaki during the summer of 2020, this footage showcases the beauty of the region across different seasons. Please note that the filming was conducted with special permission, as it is a restricted area.' where id = 'UHrkh0S84qLzkusFapQSD';
update content_bodies set title = '日本で最も安いプライベート寝台列車の部屋に乗る | サンライズエクスプレスソロ', description = '岡山から東京まで、日本で最も安い夜行寝台列車に乗りました。サンライズ出雲寝台特急を利用し、JRパスを持っている方には特に経済的な選択肢です。この旅の運賃は20,570円（約175ドル）でした。ソロの上段個室に宿泊し、列車の連結部分が特に印象的でした。' where id = 'mvkiqydTNuQkWrcqc73Vm';
update content_bodies set title = 'Riding Japan''s Cheapest Private Sleeper Train Room | Sunrise Express Solo', description = 'I traveled on Japan''s cheapest overnight sleeper train from Okayama to Tokyo, utilizing the Sunrise Izumo Sleeper Express. This option is particularly economical for those with a JR Pass, making it the most affordable way to travel overnight. The fare for this journey was 20,570 JPY (approximately 175 USD). I stayed in a solo upper compartment, which provided a unique experience, especially with the cool coupling of the train.' where id = 'n2G4krhsL7q0gWjqnjk06';
update content_bodies set title = '日本最後の二段寝台列車に乗る', description = '著者は、香川県の高松から東京までのサンライズ瀬戸号での二段寝台ルーメットの体験を共有しています。このユニークな宿泊施設は、ソロ旅行者やペアに最適です。料金は、1人の場合24,110円（約210ドル）、2人の場合は1人あたり20,410円（約180ドル）です。この旅は、ホグワーツ特急に乗っているかのような懐かしい感覚を提供し、思い出に残る体験となります。' where id = 'JatS-8TP4csY4dbY-TD-T';
update content_bodies set title = 'Riding Japan''s LAST Double Bunk Sleeper Train', description = 'The author shares their experience on the Sunrise Seto Express, traveling from Takamatsu to Tokyo in a Double Bunker Roomette. This unique accommodation is ideal for solo travelers or pairs. The fare for a single traveler is 24,110 JPY (approximately 210 USD), while for two people, it costs 20,410 JPY (around 180 USD) per person. The journey offers a nostalgic feel, reminiscent of riding the Hogwarts Express, making it a memorable experience.' where id = 'cFJvsMsrFPvNG94yo8V84';
update content_bodies set title = '最速の新幹線に乗る | 東京-北海道', description = '私は東京駅から北海道の新函館北斗まで、最速の新幹線E5はやぶさに乗りました。この新幹線は2030年までに東京と札幌という日本の主要都市を結ぶ予定です。エコノミークラスの料金は23,400円（約200ドル）、ビジネスクラスは30,940円（約270ドル）です。旅の中で、エビ料理を楽しむことができるユニークな体験が待っています。' where id = 'T5GixQSruEl7QgDVdBl3K';
update content_bodies set title = 'Riding on the Fastest Shinkansen | Tokyo-Hokkaido', description = 'I experienced the E5 Hayabusa Shinkansen, the fastest train in Japan, traveling from Tokyo Station to Shin-Hakodate Hokuto in Hokkaido. This train is set to connect Tokyo and Sapporo, two major cities in Japan, by 2030. The fare for an Economy Class ticket is 23,400 JPY (approximately 200 USD), while a Business Class ticket costs 30,940 JPY (around 270 USD). The journey promises a unique experience, highlighted by the enjoyment of shrimp dishes.' where id = 'AQwWxQvPKj-zC2FB7NlT5';
update content_bodies set title = '東京旅行の最悪のタイミング', description = 'この動画は品質が良くないものの、制作者にとっては兄との素晴らしい思い出を思い起こさせるものであり、東京の最も混雑した日にもかかわらず愛着を持っています。制作者は、国民の祝日に東京を訪れることを避けるよう視聴者にアドバイスしています。' where id = 'pK2N1byNVPFn7vFqH2nu9';
update content_bodies set title = 'The WORST time to travel Tokyo', description = 'The video, despite its poor quality, holds sentimental value for the creator as it captures a memorable experience with their brother in Tokyo, even on one of the busiest days of the year. The creator advises viewers to avoid visiting the city during national public holidays to prevent overwhelming crowds.' where id = 'F-19LvJMRF026745O_J4z';
update content_bodies set title = 'ロボットレストランは80ドルの価値があるのか？！', description = '東京のロボットレストランは、その派手でカラフルなショーで有名ですが、1人あたり80ドルというチケット価格はその価値について疑問を投げかけます。レビュアーはそのコストに驚きを示しつつ、体験のユニークさを認めています。また、動画には日本にいる理由に関するQ&Aへのリンクや、著者のSNS、チャンネルで使用されている音楽へのリンクも含まれています。' where id = 'ttDAYR4BXrjz9byUsBp17';
update content_bodies set title = 'Is the Robot Restaurant worth $80?!', description = 'The Robot Restaurant in Tokyo is famous for its extravagant and colorful shows, but the ticket price of $80 per person raises questions about its value. The reviewer expresses surprise at the cost while acknowledging the uniqueness of the experience. The video also includes a link to a Q&A about the author''s reasons for being in Japan, as well as links to their social media and music used in the channel.' where id = 'PD6xK8i-PUnFMWr_SWCgK';
update content_bodies set title = '沖縄よりも素晴らしい - 日本の奄美大島', description = '奄美大島は、沖縄本島に似ているが、訪れる人が少ないため、より静かな環境を提供しています。著者は4日間の滞在中、ビーチをたった3人と共有し、島で出会った外国人はわずか2人でした。この体験は、奄美大島の魅力を際立たせ、混雑を避けたい人々にとって夢のような目的地であることを示しています。' where id = 'fu2LsGyU5_tfwv1U4ktOE';
update content_bodies set title = 'Better than Okinawa - Amami Island, Japan', description = 'Amami Oshima offers a serene alternative to Okinawa, featuring beautiful beaches with significantly fewer visitors. During a four-day stay, the author enjoyed the tranquility of sharing the beach with only three other people and encountered just two other foreigners on the island. This experience highlighted the charm of Amami Oshima as a peaceful getaway, making it a dream destination for those seeking a less crowded environment.' where id = 'yQ3_smAy5Ck8VhYyDk9O1';
update content_bodies set title = '実はすぐそこ！京都駅から森の京都まで【アクセス紹介動画】', description = '京都市内から自然に触れたいと思っている方の中には、遠く感じる方も多いでしょう。しかし、実は京都駅から亀岡まで電車でたったの20分、乗り換えも不要で簡単にアクセスできます。車窓からは美しい田園風景が広がり、自然の雄大さを感じながら森の京都へお越しください。' where id = 'UiCydaj5DadtY3stNlj6x';
update content_bodies set title = 'Access Guide Video: Kyoto Station to Mori no Kyoto', description = 'Many people may think that experiencing nature requires traveling far from Kyoto city. However, it is actually just a single train ride away. You can reach Kameoka, the gateway to Mori no Kyoto, in just 20 minutes without any transfers from Kyoto Station. Enjoy the beautiful rural scenery from the train window and feel the grandeur of nature as you make your way to Mori no Kyoto!' where id = 'vVc_DSYdcxsPGeWu2VuDy';
update content_bodies set title = '森の京都【春夏】', description = '森の京都は、自然と人が長い歴史の中で共生してきた場所です。豊かな水は山々から流れ出し、木々や花々に命を与えています。この景色は古代から受け継がれ、訪れる人々は自然との深い結びつきを感じることができます。清らかな水の流れに自分の鼓動を合わせることで、自然の一部であることを実感できるのです。森の京都地域振興社は、京都の知られざる魅力を世界に発信し、まだ誰も体験したことのない旅を提供することを目指しています。' where id = 'zxJjwexD62wnyDj2H6_jO';
update content_bodies set title = 'Woodland Kyoto -Homeland of Pure Nature-', description = 'Woodland Kyoto is a place where nature and humanity have coexisted harmoniously throughout history. The rich life here is nourished by abundant water that flows from the mountains, breathing life into trees and flowers. This landscape has been preserved since ancient times, allowing visitors to feel a deep connection with nature. The clear streams invite individuals to synchronize their heartbeat with the rhythm of the natural world, emphasizing the experience of being part of it. The Woodland Kyoto Regional Promotion Association aims to share the hidden charms of Kyoto with the world, offering unique travel experiences that have yet to be discovered.' where id = 'mLzJfLQxcrWzH2BE59aZP';
update content_bodies set title = '森の京都「丹波の漆かき」文化講座', description = '森の京都が主催する『丹波の漆かき』文化講座では、特定非営利活動法人丹羽漆の山内耕祐氏が講師を務め、漆かきの作業や歴史について学びます。漆かきは、漆の木の樹皮に傷をつけて樹液を採取する作業で、1300年の歴史を持つ伝統的な技術です。参加者は、実際の漆かきの現場で学び、植栽作業についてもお話を聞きます。最後には、やくの木と漆の館で文化観光サポーターによる絵付け体験も行われます。' where id = 'HfjRnFIwGJM3TWudQFurV';
update content_bodies set title = 'Cultural Lecture on ''Tamba Urushi Tapping'' in the Forest of Kyoto', description = 'The Forest of Kyoto hosts a cultural lecture on ''Tamba Urushi Tapping,'' featuring insights from Mr. Kousuke Yamauchi of the NPO Tamba Urushi. The lecture includes a video showcasing the process of urushi tapping and painting experiences. This traditional practice involves making incisions in the bark of urushi trees to collect the sap, a craft with a 1300-year history. Participants will learn about the history and techniques of Tamba urushi tapping, as well as planting activities. The event concludes with a painting experience at the Yaku no Ki and Urushi Museum, guided by cultural tourism supporters.' where id = 'wRNU3mcuXPiwIfiFwoERR';
update content_bodies set title = '日本にこんな場所があるなんて信じられない！奄美大島', description = '著者は、奄美大島がこれほど美しいにもかかわらず、まだ有名な旅行先ではないことに驚きを表しています。島全体を自分たちだけのもののように感じる体験を語り、夢のような場所だと称賛しています。続編が近く公開されることを示唆し、沖縄に競争相手が現れたかもしれないと述べています。' where id = 'HT9ZJMcFdlLoddZYCyCSv';
update content_bodies set title = 'I can''t believe this is in Japan! Amami Island, Japan', description = 'The author expresses surprise that Amami Island is not a well-known travel destination despite its incredible beauty. They describe the experience of feeling as if they had the entire island to themselves, calling it a dream. The author hints at a follow-up post and suggests that Okinawa may have competition in terms of beautiful locations.' where id = 'GN2ICCqpup-qAoo1h8u7O';
update content_bodies set title = '東京ディズニーシー初体験 - 驚愕', description = '著者は東京ディズニーシーで素晴らしい一日を過ごし、完璧な天候、魅力的なパフォーマンス、素晴らしい人々と共に楽しんだと述べています。この日が期待を超えるものであり、ディズニーパークの中でもディズニーランドよりも優れていると大胆に表現しています。投稿には、個人やパフォーマンスのコンテンツ用のインスタグラムアカウントへのリンク、動画で使用した音楽や撮影機材のリストも含まれています。' where id = 'syT4M3f826ktmHDbyR1O9';
update content_bodies set title = 'First time in Tokyo DisneySea - MIND BLOWN', description = 'The author had an incredible experience at Tokyo DisneySea, enjoying perfect weather, engaging performances, and a great crowd. They expressed that the day exceeded their expectations and boldly stated that they found it to be superior to Disneyland. The post includes links to their Instagram accounts for personal and performance content, as well as resources for music used in their videos and filming equipment.' where id = '3f_Zsuh_YXAngvZtvg8dz';
update content_bodies set title = '日本のホテルの楽しみ方', description = '日本のホテルは独特で記憶に残る体験を提供し、日本を訪れる際には誰もが体験すべきものです。この動画は、視聴者が日本のホテルに関して持つかもしれない疑問を解消することを目的としています。制作者は、新しいイントロを使用しなかった理由として、このコンテンツにはエネルギーがありすぎたためだと認めています。次回の動画では新しいイントロが合うかもしれません。また、視聴者は制作者のインスタグラムアカウント、動画で使用された音楽、撮影および編集機材のリンクも見つけることができます。' where id = 'nqoTd6lnkFds9tsQ45gJ2';
update content_bodies set title = 'How to Japanese Hotel', description = 'Japanese hotels offer a unique and memorable experience that everyone should try when visiting Japan. This video aims to address any questions viewers may have about staying in these hotels. The creator acknowledges that the new intro was not used in this video, as it was too energetic for the content. Future videos may feature the new intro. Additionally, viewers can find links to the creator''s Instagram accounts, music used in the videos, and filming and editing gear.' where id = 'yvX-J1xAeuN6u0SUIs-bY';
update content_bodies set title = '日本の自然の美', description = 'この動画は、東京の喧騒から離れた日本の美しさを捉えています。Yosshiと過ごすリラックスした雰囲気が特徴で、いつもより短いですが、思い出に満ちています。視聴者は、クリエイターのインスタグラムをチェックしてさらなるコンテンツを楽しんだり、動画で使用された音楽や撮影機材を探ったりすることが奨励されています。' where id = 'buvlahi2wNtWEVIALzEJk';
update content_bodies set title = 'Japan''s natural beauty', description = 'This video captures the beauty of Japan away from the busy life of Tokyo, featuring a more relaxed atmosphere while spending time with Yosshi. Although shorter than usual, it is filled with cherished memories. Viewers are encouraged to check out the creator''s Instagram for more content and to explore the music and filming gear used in the video.' where id = '7bANF9ez4aIdC39s79yAL';
update content_bodies set title = '県立城ケ島公園【水仙】', description = '神奈川県三浦市の県立城ケ島公園で見ごろを迎えている水仙（スイセン）を紹介します。城ヶ島には安房埼灯台、城ケ島灯台、ウミウ展望台、馬の背洞門、みはらし広場、海上イケス釣堀など多くの見どころがあります。今回は、約30万株の八重咲水仙が咲いている様子を島の映像と共にお届けします。アクセスは京浜急行三崎口駅から城ケ島行きバスで「白秋碑前」下車後、徒歩7分です。駐車場も完備されています。' where id = 'wrAz0jPkWuBaEZOja3KzN';
update content_bodies set title = 'Kenritsu Jogashima Park: Daffodils', description = 'This text introduces the daffodils in full bloom at Kenritsu Jogashima Park in Miura City, Kanagawa Prefecture. Jogashima offers numerous attractions, including Awasaki Lighthouse, Jogashima Lighthouse, Umiu Observatory, Uma no Se Cave, Mihara Wide Area, and a sea fishing pond. This time, the focus is on the double-flowered daffodils that are currently in bloom, with approximately 300,000 daffodil plants to enjoy. For more information, visit the Jogashima Park website.' where id = 'fbjxO4Wz12PdcKkemqDXh';
update content_bodies set title = '【ドローン映像】長崎ばーどアイ4K　「軍艦島」', description = '『長崎ばーどアイ』は、長崎市の軍艦島を4Kドローン映像で紹介する作品です。2020年6月24日に撮影され、四季折々の美しい風景を楽しむことができます。視聴者は、この素晴らしい場所の空撮を通じて、夢を見たり、旅行したり、発見したりすることができます。' where id = 'hnWcmP4linHiZZAaqda1Q';
update content_bodies set title = 'NAGASAKI Bird''s Eye - 4K Drone Footage', description = 'This video showcases stunning 4K drone footage of Gunkanjima, also known as Battleship Island, located in Nagasaki, Japan. Filmed on June 24, 2020, it captures the breathtaking landscapes of Nagasaki throughout the seasons. Viewers are invited to dream, travel, and discover the beauty of this remarkable location through aerial views.' where id = 'Av3Z9CjwNi6_CrB0g5FEH';
update content_bodies set title = '東京に留まらないで - 都市からの最高の日帰り旅行', description = '東京は素晴らしい場所で見どころがたくさんありますが、都市のすぐ外には本物の美しさが広がっています。わずか1時間の距離にある鎌倉は、非常に魅力的な場所です。ここには日本の自然の美しさが詰まっています。' where id = '1omHpa4PGpLXgCzEA5hHj';
update content_bodies set title = 'Don''t stay in Tokyo - the best day trip from the city', description = 'While Tokyo offers a wealth of attractions, just an hour away lies Kamakura, a destination that showcases Japan''s stunning natural beauty. Kamakura is a perfect day trip for those looking to escape the hustle and bustle of the city and experience a different side of Japan.' where id = 'CBIA4EFd5UoikT99mSMF5';
update content_bodies set title = '日本で最も雨の多い場所、屋久島で4日間のハイキングをしました', description = '屋久島は、古代の自然と手つかずの風景が広がる場所であり、ハイキングのハイライトとなりました。著者は、この特別な環境でのハイキング体験を共有し、その美しさと野生の自然を強調しています。FineTrackに感謝の意を示し、最高の雨具を提供してもらったことで、ハイキングがより快適になったと述べています。この動画はFineTrackのスポンサーによるもので、屋久島への旅行計画に役立つリソースやハイキングギア、旅行ガイドへのリンクも提供されています。また、著者は日本の隠れた名所を紹介する旅行ガイド『Beyond The Tourist Trail』も宣伝しています。' where id = 'L9d4c4gYRf9BFZOmOHVIS';
update content_bodies set title = 'I Spent 4 Days Hiking In The Rainiest Place In Japan: Yakushima', description = 'Yakushima is known for its ancient and wild landscapes, making it a remarkable hiking destination. The author shares their experience of hiking in this unique environment, highlighting the beauty and untamed nature of the area. They express gratitude to FineTrack for providing high-quality rain gear, which enhanced their hiking experience. The video is sponsored by FineTrack, and additional resources for planning a trip to Yakushima are provided, including links to hiking gear and travel guides. The author also promotes their travel guide, ''Beyond The Tourist Trail,'' which features hidden gems in Japan.' where id = 'jC_V5qhl82mRdeH5zyBib';
update content_bodies set title = '日本での私のお気に入りのハイキング - 白馬岳 // 2,932m 長野', description = 'この動画では、制作者が白馬岳のハイキング体験を共有しています。彼らはこのハイキングを人生で最高のものと表現しており、挑戦的な部分は主に持久力ですが、素晴らしい景色がその価値を1000%高めていると述べています。ハイキングは、栂池中央駐車場から始まり、ロープウェイとゴンドラを利用して登山口に到達し、通常6〜7時間かかる頂上までの8時間以上のハイキングを行います。この動画はCanvaのスポンサーによるもので、視聴者はPatreonでの追加コンテンツやInstagramでのフォローを促されています。' where id = '4mIjXZR2Is5DztThgMloL';
update content_bodies set title = 'My Favourite Hike in Japan - Mt Shirouma // 2,932m Nagano', description = 'In this video, the creator shares their experience hiking Mt Shirouma, which they describe as the best hike of their life. The hike is challenging, primarily due to the endurance required, but the stunning views make it worthwhile. The journey begins at Tsugaike Central Parking Lot, where they take a ropeway and gondola to reach the trailhead, followed by an 8+ hour hike to the summit, typically taking 6-7 hours. The video is sponsored by Canva, and viewers are encouraged to check out additional content on Patreon and follow the creator on Instagram.' where id = 'b4N7S-6rdPNXLH8YKJRTH';
update content_bodies set title = '森の京都「丹後二俣紙」文化講座', description = '森の京都が主催する『丹後二俣紙』の文化講座が、2022年3月13日（日）13:30から14:30まで福知山市大江町の和紙伝承館でライブ配信されます。この講座では、良質な地元産のコウゾを使用した手漉きの「丹後二俣紙」の伝統技術を学びます。前半では田中製紙工業所の田中敏弘氏が講師として、原料や丹後二俣紙の魅力について解説します。後半では、田中氏による紙漉きのデモンストレーションが行われ、森の京都文化観光サポーターが実際に紙漉き体験を行います。' where id = '5WuFYb7BtmOmaojLlUUvE';
update content_bodies set title = 'Cultural Lecture on TANGO Futamata Paper in the Forest of Kyoto', description = 'The Forest of Kyoto is hosting a live-streamed cultural lecture on ''Tango Futamata Paper'' on March 13, 2022, from 13:30 to 14:30 at the Washi Heritage Center in Oe Town, Fukuchiyama City. This lecture aims to teach participants about the traditional craft of hand-made ''Tango Futamata Paper'' using high-quality local Kozo. The first half of the program features Mr. Toshihiro Tanaka from Tanaka Paper Industry, who will discuss the raw materials and the significance of Tango Futamata Paper. In the second half, Mr. Tanaka will demonstrate the paper-making process, followed by a hands-on experience for the cultural tourism supporters of the Forest of Kyoto.' where id = 'vpbiHEL_3KeZrG15jurEy';
update content_bodies set title = '亀岡祭山鉾巡行～地域無形文化遺産 森育ちの文化が待っている～', description = '「森の京都」として知られる亀岡市は、豊かな森と共に発展してきました。この動画では、森と人が育んできた伝統文化の魅力を、森の京都エリアの6つの町からお届けします。亀岡祭山鉾巡行は、丹波の祇園祭とも呼ばれ、情緒ある提灯が山鉾を飾り、街全体が賑わいます。特にクライマックスの「山鉾巡行」は圧巻です。この祭りは毎年10月23日（宵々山）、24日（宵宮）、25日（鉾の巡行）の3日間にわたって開催されます。詳細は亀岡祭山鉾連合会のウェブサイトをご覧ください。' where id = 'Xs-NepSeKFaliwuRHfv66';
update content_bodies set title = 'Kameoka Festival Yamaboko Procession - A Cultural Heritage of the Region Awaits You', description = 'Kameoka, known as ''Mori no Kyoto'' or ''Forest Kyoto,'' has developed alongside its rich forests. This video showcases the traditional cultural charm nurtured by the relationship between the forest and the people in six towns of the Mori no Kyoto area. The Kameoka Festival Yamaboko Procession, often referred to as the Tanba Gion Matsuri, is a vibrant celebration featuring lanterns adorning the yamaboko (float). The climax of the festival, the ''Yamaboko Junko,'' is particularly impressive. The event takes place over three days: October 23rd (Yoi-yama), 24th (Yoi-miya), and 25th (the procession of floats). For more information, visit the Kameoka Festival Yamaboko Federation website.' where id = 'us8A-TgArAdkzt7gT3fBE';
update content_bodies set title = '日本の北アルプスをソロハイキング 4K・上高地とピークデザイン三脚', description = 'この動画は、Squarespaceのスポンサーによるもので、日本の北アルプス、上高地でのソロハイキングの冒険を紹介しています。ホストは、ピークデザインから提供されたカーボンファイバー製のトラベル三脚に感謝の意を示し、今後もこれを使用する予定です。上高地の美しさが強調され、厳しい2日間のハイキングで奥穂高岳に挑戦したことが語られています。ホストはこの挑戦を乗り越えたことに満足し、さらに多くの山を探索したいと意欲を示しています。動画には、旅行計画に使用したリソースへのリンクが含まれ、Patreonを通じてのサポートも促されています。' where id = 'Y43ogdX2WnaqBtqO-hMfs';
update content_bodies set title = 'Solo Hiking Japan''s Northern Alps 4K・Kamikochi w/Peak Design Tripod', description = 'This video, sponsored by Squarespace, showcases a solo hiking adventure in Kamikochi, Japan''s Northern Alps. The host expresses gratitude to Peak Design for their Carbon Fiber Travel Tripod, which they plan to use exclusively. Kamikochi is highlighted for its stunning beauty, and the challenging hike to Mt Oku-Hotaka is discussed, with the host managing to complete it in two days despite the difficulty. They express eagerness to explore more mountains in the area. The video includes links to resources used for trip planning and encourages support through Patreon for additional content.' where id = 'ILDMAKmurphvsIiZ8ck9m';
update content_bodies set title = 'モデルコース２「お寿司と温泉 そして能登島を満喫」', description = 'このコースでは、お寿司、温泉、そして能登島の美しい景色を楽しむことができます。新鮮なお寿司を味わい、リラックスできる温泉に浸かり、能登島のユニークな観光スポットを探索することで、食と自然を愛する人々にとって完璧な休暇を提供します。' where id = 'ey8HsqwXR_KVIyrUaodWJ';
update content_bodies set title = 'Model Course 2: Enjoy Sushi, Hot Springs, and Noto Island', description = 'This course offers a delightful experience combining sushi, hot springs, and the scenic beauty of Noto Island. Visitors can indulge in fresh sushi, relax in soothing hot springs, and explore the unique attractions of Noto Island, making it a perfect getaway for food and nature lovers.' where id = 'r11XmfFAxxDNBRdJ3OvE8';
update content_bodies set title = 'モデルコース３「奥能登の世界農業遺産をめぐる」', description = 'このコースは、奥能登地域の世界農業遺産を巡る内容です。代々受け継がれてきた独自の農業慣行や風景を探求する機会を提供します。参加者は、これらの慣行の文化的意義や地域社会や環境への影響について学ぶことができます。' where id = 'AqGgBX7GhtGsa1CyoXt5S';
update content_bodies set title = 'Model Course 3: Exploring the World Agricultural Heritage of Noto', description = 'This course focuses on the World Agricultural Heritage sites in the Noto region. It offers an opportunity to explore the unique agricultural practices and landscapes that have been preserved over generations. Participants will learn about the cultural significance of these practices and their impact on the local community and environment.' where id = 'JDMqvJiUx0094dQaGZ7v0';
update content_bodies set title = 'モデルコース４「城下町金沢定番コース」', description = 'このコースは、歴史的な重要性と美しい風景で知られる金沢の定番体験を提供します。訪問者は、保存状態の良い城や伝統的な庭園、そしてこの街の豊かな文化遺産を反映した文化的なスポットを探索できます。この旅程は、金沢の魅力を包括的に紹介するように設計されており、初めて訪れる方に最適です。' where id = 'x6xiGA9s4trn7vUUSpUC5';
update content_bodies set title = 'Model Course 4: Standard Course in Kanazawa Castle Town', description = 'This course offers a classic experience in Kanazawa, a city known for its historical significance and beautiful landscapes. Visitors can explore the well-preserved castle, traditional gardens, and cultural sites that reflect the city''s rich heritage. The itinerary is designed to provide a comprehensive overview of Kanazawa''s attractions, making it ideal for first-time visitors.' where id = 'BYVGritHTPx_sm-qn9WUP';
update content_bodies set title = 'モデルコース５「金沢の旬の味覚にふれる旅」', description = 'このコースでは、金沢の旬の味覚を体験するユニークな機会を提供します。訪問者は、地域の新鮮な食材と料理の伝統を強調した地元の料理を楽しむことができます。旅の中では、著名なレストランや市場を訪れ、本格的な料理を味わい、食の文化的意義について学ぶことができます。この体験は、味覚を満たすだけでなく、金沢の豊かな食文化を深く理解する手助けとなります。' where id = 'jk3hu5vMHnln6CmxFmvbg';
update content_bodies set title = 'Model Course 5: A Journey to Experience Seasonal Flavors of Kanazawa', description = 'This course offers a unique opportunity to explore the seasonal delicacies of Kanazawa. Visitors can indulge in local cuisine that highlights the region''s fresh ingredients and culinary traditions. The journey includes visits to renowned restaurants and markets, where travelers can taste authentic dishes and learn about the cultural significance of the food. This experience not only satisfies the palate but also provides insight into the rich culinary heritage of Kanazawa.' where id = 'KfbnZ0m95aLRqW2wZ_JC1';
update content_bodies set title = 'モデルコース６「伝統文化に親しみ工芸体験にトライ」', description = 'このコースは、参加者が伝統文化に親しむことを目的としており、実際に工芸体験を通じてその魅力を体感します。さまざまな伝統工芸に触れることで、それぞれの文化的意義を学び、理解を深めることができます。参加者は自分自身の工芸品を作成する機会があり、これらの伝統的な技術や文化遺産とのつながりを強めることができます。' where id = 'BY_JD3aNytdFrrO4-lIKS';
update content_bodies set title = 'Model Course 6: Experience Traditional Culture and Try Craft Activities', description = 'This course focuses on immersing participants in traditional culture through hands-on craft experiences. It offers an opportunity to engage with various traditional crafts, allowing individuals to appreciate and learn about the cultural significance behind them. Participants will have the chance to create their own crafts, fostering a deeper connection to the heritage and skills involved in these traditional practices.' where id = '02NAZJPZtCiZ5jbNuEuA2';
update content_bodies set title = 'モデルコース７「侍が築いた歴史にふれる旅」', description = 'このコースでは、侍が築いた豊かな歴史と文化を探求するユニークな機会を提供します。参加者は重要な歴史的な場所を訪れ、侍の生活様式について学び、彼らが日本の歴史に与えた影響を理解します。この旅は、侍時代を形作った価値観や伝統についての洞察を提供するように設計されており、日本の遺産に興味がある人々にとって、充実した体験となるでしょう。' where id = 'f4Qfwp1ZSYqxralDqSgDk';
update content_bodies set title = 'Model Course 7: A Journey to Experience the History Built by Samurai', description = 'This course offers a unique opportunity to explore the rich history and culture established by the samurai. Participants will visit significant historical sites, learn about the samurai''s way of life, and understand their impact on Japanese history. The journey is designed to provide insights into the values and traditions that shaped the samurai era, making it an enriching experience for those interested in Japan''s heritage.' where id = 'OfJjpcDyena0lhu8SZQ50';
update content_bodies set title = 'モデルコース８「歴史ある湯の街と工芸体験を楽しむ」', description = 'このコースでは、歴史ある湯の街を探索しながら、さまざまな工芸体験を楽しむことができます。訪れる人々は、地域の豊かな文化遺産に浸り、自然の美しさと伝統的な工芸技術を体験することができます。' where id = 'iEJRHx5J4q_BxtZbcA4Na';
update content_bodies set title = 'Model Course 8: Enjoying the Historic Hot Spring Town and Craft Experiences', description = 'This course offers a unique opportunity to explore a historic hot spring town while engaging in various craft experiences. Visitors can immerse themselves in the rich cultural heritage of the area, enjoying both the natural beauty and the traditional craftsmanship that the town has to offer.' where id = 'Cc9MbXCsXYPe0bwNVPTff';
update content_bodies set title = 'モデルコース９「芭蕉が愛した山中温泉をめぐる」', description = 'このコースでは、著名な詩人松尾芭蕉が愛した山中温泉を巡ります。自然の美しさと地域の文化的意義を強調し、訪れる人々に芭蕉の作品に影響を与えた静かな雰囲気を体験させることを目的としています。文学と自然を愛する人々に向けて設計されており、地域の歴史的および芸術的遺産とつながるユニークな機会を提供します。' where id = 'zpCmx3bcM4H2A1EOs_1Dt';
update content_bodies set title = 'Model Course 9: Exploring Yamanaka Onsen Loved by Basho', description = 'This course takes you through Yamanaka Onsen, a hot spring area cherished by the famous poet Matsuo Basho. The journey highlights the natural beauty and cultural significance of the region, allowing visitors to experience the serene atmosphere that inspired Basho''s works. The course is designed for those who appreciate literature and nature, providing a unique opportunity to connect with the historical and artistic heritage of the area.' where id = '_53WwBq6a1ZBb4NVgx9vT';
update content_bodies set title = 'モデルコース１０「魯山人が愛した山代温泉をめぐる」', description = 'このコースでは、著名な日本の芸術家魯山人が愛した山代温泉を巡ります。魯山人に関連する重要なスポットを訪れることで、参加者はこの地域の独特な文化と歴史を体験できます。自然の美しさや温泉における伝統的な日本のホスピタリティも強調されており、アートや歴史、静かな環境でのリラクゼーションを楽しむ人々に最適なコースです。' where id = '23Wf5K7Jq0xP6x3RIrA_E';
update content_bodies set title = 'Model Course 10: Exploring Yamashiro Onsen Loved by Rosanjin', description = 'This course takes you through Yamashiro Onsen, a hot spring area cherished by the famous Japanese artist Rosanjin. The itinerary includes visits to key sites associated with Rosanjin, allowing participants to experience the unique culture and history of the area. The course highlights the beauty of the natural surroundings and the traditional Japanese hospitality found in the onsen. It is designed for those who appreciate art, history, and relaxation in a serene environment.' where id = 'UGl0N1SNINVI_X2uIT5Q3';
update content_bodies set title = 'モデルコース11「大自然を体感 白山白川郷ホワイトロード」', description = 'このコースでは、白山白川郷エリアの美しい自然を体感することができます。訪れる人々は、風光明媚な景色を楽しみ、アウトドアアクティビティを体験し、地域の独自の文化遺産を味わうことができます。' where id = 'gNJ-mDc2vJeCM_C_qLbfc';
update content_bodies set title = 'Model Course 11: Experience Nature on the Hakusan Shirakawago White Road', description = 'This course offers an opportunity to immerse oneself in the stunning natural beauty of the Hakusan Shirakawago area. Visitors can explore scenic landscapes, enjoy outdoor activities, and appreciate the unique cultural heritage of the region.' where id = 'sARVaaUUI1QtH-ojNG85_';
update content_bodies set title = '分散型旅行を応援します！GO TO NOTO～安心・安全な旅を能登半島で～', description = '能登半島は分散型旅行を推進し、安心・安全な環境で心温まる思い出を作ることを奨励しています。コロナ禍において、しっかりとした感染対策が行われており、自然豊かな能登を満喫することができます。提案されているアクティビティには、千里浜なぎさドライブウェイのドライブ、気多大社の訪問、雨の宮古墳の探訪、能登食祭市場やのとじま水族館の見学などがあります。2日目には、のと鉄道や輪島朝市、さまざまな文化的なスポットを訪れることができ、この美しい地域で充実した体験ができます。' where id = 'bXwXgaGTiY2hE4mcTlPeN';
update content_bodies set title = 'Supporting Decentralized Travel! GO TO NOTO - Safe and Secure Travel in the Noto Peninsula', description = 'The Noto Peninsula promotes decentralized travel, encouraging visitors to create heartwarming memories in a safe and secure environment. In the era of COVID-19, strict infection control measures are in place. Visitors are invited to enjoy the rich natural beauty of the Noto Peninsula. Suggested activities include a scenic drive along the Chirihama Nagisa Driveway, visiting the Keta Taisha Shrine, exploring the Rainy Miyako Tomb, and enjoying local attractions such as the Noto Food Festival Market and Noto Aquarium. Day two features the Noto Railway, Wajima Morning Market, and various cultural sites, ensuring a fulfilling experience in this beautiful region.' where id = 'Y3FhTs3bhacqbUHywGegj';
update content_bodies set title = '兼六園・金沢城公園', description = 'この動画では、兼六園と金沢城公園について紹介しています。' where id = 'skEmEsvaA69CTLF95Bm2h';
update content_bodies set title = 'Kenrokuen and Kanazawa Castle Park', description = 'This video introduces Kenrokuen and Kanazawa Castle Park.' where id = 'OVzsZPPsdtJSuCw7C4wyp';
update content_bodies set title = '白米の千枚田', description = 'この動画では、白米の千枚田について紹介しています。千枚田は美しい棚田であり、その重要性や魅力を伝えています。' where id = 'a_8PdmTY2J2moEr4B8wzt';
update content_bodies set title = 'Senmaida Rice Terraces', description = 'This video introduces the Senmaida Rice Terraces, showcasing their beauty and significance.' where id = 'CAkZfQV4ffUJCbo8VESxQ';
update content_bodies set title = '長町武家屋敷跡', description = 'この動画では、長町武家屋敷跡について紹介しています。長町は、かつての武士の居住地であり、その歴史的な背景や文化を知ることができる場所です。武家屋敷の跡地は、当時の生活様式や建築様式を感じることができる貴重なスポットです。' where id = 'r-Wwbs3aQJMcfrOoZNa6d';
update content_bodies set title = 'Nagamachi Samurai Residences', description = 'This video introduces the Nagamachi Samurai Residences.' where id = 'OIhwHFC01KtSNVhOs9tUk';
update content_bodies set title = '主計町', description = 'この動画は主計町について紹介しています。主計町は、歴史的な背景や文化的な魅力を持つ地域であり、観光名所や地元の特産品などが紹介されることが期待されます。動画では、主計町の特徴や訪れる価値について詳しく説明されているでしょう。' where id = '0QE6YDxKCQ6mxUjCJhgX0';
