update content_bodies set title = 'ひがし茶屋街', description = 'この動画は、ひがし茶屋街について紹介しています。ひがし茶屋街は、伝統的な茶屋や文化が残る地域であり、観光名所としても知られています。' where id = 'VOwMaFr78AarQVTHeIME2';
update content_bodies set title = 'Higashi Chaya District', description = 'This video introduces the Higashi Chaya District.' where id = 'ydZzDe_aNCJUSwHEAobCQ';
update content_bodies set title = '千里浜なぎさドライブウェイ', description = 'この動画は千里浜なぎさドライブウェイについて紹介しています。千里浜なぎさドライブウェイは、石川県に位置する美しい海岸線を走ることができる特別な道路です。ドライブを楽しむだけでなく、周囲の自然や海の景色を堪能することができます。' where id = 'xtNaK2KEsHhHOW7L5F--O';
update content_bodies set title = 'Chirihama Nagisa Driveway', description = 'This video introduces the Chirihama Nagisa Driveway.' where id = 'ezO4gSwlc6xJxJQXeD5Nf';
update content_bodies set title = '金沢駅・もてなしドーム', description = 'この動画では、金沢駅とその特徴的なもてなしドームについて紹介しています。金沢駅は、北陸地方の重要な交通拠点であり、観光客にとっても魅力的な場所です。もてなしドームは、駅のシンボル的存在であり、訪れる人々を温かく迎え入れるデザインが特徴です。' where id = 'Qtj1bY2zR6QY2lwqCus_x';
update content_bodies set title = 'Kanazawa Station and the Motenashi Dome', description = 'This video introduces Kanazawa Station and the Motenashi Dome.' where id = 'cx25sTKP9w1_ECzWGdhb6';
update content_bodies set title = '機具岩', description = 'この動画は機具岩について紹介しています。' where id = 'ICvUPKqxCaOdJdi9eZ8iB';
update content_bodies set title = 'Kigui Rock', description = 'This video introduces Kigui Rock.' where id = 'F4ECxQ-80tSg66m-Cmicy';
update content_bodies set title = '山中節と温泉の館　山中座', description = 'この動画では、山中節と温泉の館である山中座について紹介しています。山中節は日本の伝統的な民謡であり、地域の文化や歴史を反映しています。また、山中座は温泉施設としても知られ、訪れる人々にリラックスできる空間を提供しています。動画では、これらの魅力を詳しく解説し、観光客や地元の人々にとっての重要性を伝えています。' where id = 'SgUzNcLb_Ad346qO0CCoW';
