update content_bodies set title = '石川県観光物産館', description = 'この動画は、石川県観光物産館について紹介しています。観光物産館は、石川県の魅力を伝えるための施設であり、地域の特産品や観光情報を提供しています。訪れる人々は、地元の文化や伝統を体験し、石川県の魅力を深く理解することができます。' where id = 'WZWp5ywKeifMDI7u5XgQw';
