update content_bodies set title = '巌門', description = 'この動画は巌門について紹介しています。巌門は自然の美しさや地形の特徴を持つ場所であり、観光地としても知られています。動画では、巌門の魅力や訪れる価値について詳しく解説されており、視聴者にその素晴らしさを伝えています。' where id = 'J76hPB2YTKMur2vr-Tp_P';
