update content_bodies set title = '山中温泉', description = 'この動画は山中温泉について紹介しています。山中温泉は、自然に囲まれた美しい温泉地で、訪れる人々にリラックスと癒しを提供します。温泉の効能や周辺の観光スポットについても触れられており、訪問者が楽しめるアクティビティや文化的な体験が紹介されています。' where id = 'J55pALJOCvdkRDlcNZmeN';
