update content_bodies set title = '【南丹市】#2 大送神社綱引き～地域無形文化遺産 森育ちの文化が待っている～', description = '「森の京都」として知られる南丹市は、山の恵みを受けて豊かな森と共に発展してきました。この動画では、森と人が育んできた伝統文化の魅力を、森の京都エリアの6つの町からお届けします。大送神社の綱引きは、南丹市八木町で行われる神事で、村を荒らす大蛇を討った武士の伝説に由来し、千年以上の歴史があります。参加者は、ヘビを象徴する網を鳥居の間で引き合い、南が勝てば米、北が勝てば麦が豊作になるとされています。毎年1月中旬の日曜日に開催される予定です。' where id = 'VATBJ-CIAT0Zh4Y4C6572';
update content_bodies set title = 'Oso Shrine Tug-of-War in Nantan City - A Cultural Heritage of the Region', description = 'Nantan City, known as ''Forest Kyoto,'' has developed alongside the rich blessings of the mountains and forests. This video showcases the traditional cultural charm nurtured by the relationship between the forest and the people in six towns of the Forest Kyoto area. The Oso Shrine Tug-of-War, held in Yagi, Nantan City, is a sacred event that has been passed down for over a thousand years, inspired by a legend of a warrior who defeated a giant serpent that troubled the village. Participants pull a net symbolizing the serpent across a torii gate, with the outcome predicting the harvest: if the south wins, rice will be abundant; if the north wins, wheat will thrive. The event is scheduled for a Sunday in mid-January each year.' where id = 'Wq75UcU8y1fMX__dOXlfT';
update content_bodies set title = '福知山音頭～地域無形文化遺産 森育ちの文化が待っている～', description = '「森の京都」として知られる福知山市は、山の恵みを受けて発展してきました。この動画では、森と人が育んできた伝統文化の魅力を、森の京都エリアの6つの町から紹介します。福知山音頭は「ドッコイセ、ドッコイセー」というかけ声が特徴で、福知山城の建設時に木材や石材を運ぶ人々が歌い踊ったことに由来します。今でも多くの人々に愛され、毎年8月14～16日と24～25日に福知山ドッコイセまつりで披露されます。この動画は地域無形文化遺産の継承を目的とした事業の一環として制作されました。' where id = 'dA678bbr7qMVvWPWSuzsH';
update content_bodies set title = 'Fukuchiyama Ondo: A Local Intangible Cultural Heritage of Fukuchiyama City', description = 'Fukuchiyama City, located in the ''Forest of Kyoto,'' has developed alongside the rich blessings of the mountains. This video showcases the traditional cultural charm nurtured by the forest and its people across six towns in the Forest of Kyoto area. The Fukuchiyama Ondo, characterized by the call ''Dokkoi se, Dokkoi se,'' originated from the songs and dances of people transporting timber and stones during the construction of Fukuchiyama Castle. This traditional dance is still beloved by many and is performed annually during the Fukuchiyama Dokkoi Se Festival held from August 14-16 and 24-25. The video was produced as part of a project to promote the utilization of local cultural assets.' where id = 'zzjVDHjxWslKFdQph1KsO';
update content_bodies set title = '【綾部市】#5 綾部太鼓～地域無形文化遺産 森育ちの文化が待っている～', description = '「森の京都」として知られる綾部市は、豊かな森の恵みを受けて発展してきました。この動画では、森と人が育んできた伝統文化の魅力を、森の京都エリアの6つの町から紹介します。綾部太鼓は、九鬼水軍が兵士を鼓舞するために打ち鳴らしたことに始まり、九鬼嘉隆の孫、九鬼隆季が綾部藩の初代藩主となった際に伝わりました。綾部太鼓は、あやべ初えびす大祭や大本節分大祭、あやべ丹の国まつりなどで披露されます。この動画は、文化庁の地域文化財総合活用推進事業の一環として制作されました。' where id = 'gs4A7r-l653L25mntdslP';
update content_bodies set title = 'Ayabe City #5 Ayabe Taiko - Intangible Cultural Heritage of the Region Awaits in the Forest', description = 'Ayabe City, located in the ''Forest of Kyoto,'' has developed alongside the rich forests that provide its blessings. This video showcases the charm of traditional cultures nurtured by the forest and its people across six towns in the Forest of Kyoto area. Ayabe Taiko originated from the Kuki Navy, which played drums to inspire soldiers. When Kuki Takaki, the grandson of Kuki Yoshitaka, became the first lord of the Ayabe domain, the powerful drumming tradition was passed down. Ayabe Taiko is performed at various festivals, including the Ayabe Hatsu Ebisu Festival, the Oomoto Setsubun Festival, and the Ayabe Tan no Kuni Festival. This video was produced as part of the Cultural Agency''s project to promote the comprehensive utilization of regional cultural assets.' where id = 'A0SSnZaZU4IkURZS2hc0w';
update content_bodies set title = '山国隊軍楽～地域無形文化遺産 森育ちの文化が待っている～', description = '「森の京都」として知られる京北は、豊かな森の恵みを受けて発展してきました。この動画では、森と人が育んできた伝統文化の魅力を、森の京都エリアの6つの町からお届けします。山国隊は幕末に京北の農民たちによって結成され、戊辰戦争で戦いました。彼らが行進の際に奏でていた太鼓のリズムや笛の音は、現在の山国隊軍楽として受け継がれています。毎年10月上旬には山國神社の還幸祭でその演奏を見ることができます。この動画は、文化庁の地域無形文化遺産継承のための新しい生活様式支援事業の一環として制作されました。' where id = 'IMBL6R0XarOpB16IrnIwe';
update content_bodies set title = 'Yamakunitai Military Music - Intangible Cultural Heritage of the Region in Kyoto''s Keihoku', description = 'Keihoku, known as ''Forest Kyoto,'' has developed alongside the rich forests that provide bountiful blessings. This video showcases the charm of traditional cultures nurtured by the forest and its people across six towns in the Forest Kyoto area. The Yamakunitai, formed by farmers in Keihoku during the late Edo period, fought in the Boshin War. The lively rhythms of drums and beautiful flute melodies they played during their marches have been passed down to the present day as Yamakunitai Military Music. You can witness this performance during the Kankōsai festival at Yamakuni Shrine in early October. This video was produced as part of a project by the Agency for Cultural Affairs to support new lifestyles for the inheritance of intangible cultural heritage.' where id = 'ntkbZ4KRCElF2C4-qlvNc';
update content_bodies set title = '輪島朝市', description = 'この動画は、輪島朝市について紹介しています。輪島朝市は、地元の新鮮な食材や特産品が並ぶ賑やかな市場で、観光客にも人気があります。地元の人々が日々の買い物をする場所としても利用されており、地域の文化や生活を感じることができる貴重なスポットです。' where id = 'ioxa4Bhkl7Zd_xeYsTBwa';
