update content_bodies set title = '揚げ浜塩田', description = 'この動画は揚げ浜塩田について紹介しています。揚げ浜塩田は、特有の製塩方法を用いて塩を生産する場所であり、その伝統的な技術や風景が魅力です。塩田の歴史や文化的背景も含め、揚げ浜塩田の重要性を伝える内容となっています。' where id = '4AHutvtOOjdVA2LeaDu6g';
