update content_bodies set title = '島ヶ原温泉やぶっちゃ', description = '三重県伊賀市の美しい自然に囲まれた木津川上流の山里に位置する「島ヶ原温泉やぶっちゃ」では、オートキャンプやディキャンプ、テニス、グラウンドゴルフなど多彩なレジャーを楽しむことができます。遊んだ後は、ミネラル豊富な天然温泉でリフレッシュできるのが魅力です。' where id = '3_1fcU7aQhW_i77Nz7aLk';
update content_bodies set title = 'Shimogahara Onsen Yabuccha', description = 'Located in a picturesque mountain village along the upper Kizu River in Iga City, Mie Prefecture, ''Shimogahara Onsen Yabuccha'' offers a variety of leisure activities such as auto camping, day camping, tennis, and ground golf. After enjoying these activities, visitors can refresh themselves in the mineral-rich natural hot springs.' where id = 'bdsf5Dyh_0E3Znn1GCrOE';
