update content_bodies set title = '京都亀岡の保津川でのカヤック', description = 'この動画では、京都の亀岡にある保津川でのカヤック体験を紹介しています。川の美しい景色や周囲の自然を強調し、このアウトドアアクティビティの魅力を視聴者に伝えています。' where id = 'VFf1Urk64-oGF2SAOGrBT';
update content_bodies set title = 'Kyoto Kameoka kayaking in Hozugawa river', description = 'This video showcases the experience of kayaking in the Hozugawa River located in Kameoka, Kyoto. It highlights the scenic beauty of the river and the surrounding nature, providing viewers with an insight into this outdoor activity.' where id = 'd5pdN2JE3kxTv5RMqcJrz';
