update content_bodies set title = '八木城跡', description = 'この動画は八木城跡について紹介しています。八木城は日本の歴史的な城の一つで、その遺跡は現在も多くの人々に訪れられています。城跡は、当時の建築様式や歴史的背景を知る貴重な場所であり、観光名所としても知られています。動画では、八木城跡の特徴や魅力、周辺の景観について詳しく解説されており、視聴者にとって興味深い内容となっています。' where id = '-f0JUnUgfkCYSuD_JDXjn';
update content_bodies set title = 'Yagi Castle Ruins', description = 'This video introduces the Yagi Castle Ruins.' where id = 'pUr5dYwzqaGJrK4bR-nJV';
update content_bodies set title = '京都で唯一の刀鍛冶体験！', description = '正弘は日本の京都で最も有名な刀鍛冶の一人です。彼はウッドランドエリアのスタジオで刀（カタナ）を製作しています。訪問者は彼の工房で自分自身の小さなカタナナイフを鍛えるユニークな体験ができます。詳細については、https://morinokyoto.jp/masahiro/ をご覧ください。' where id = '9kxdiGMeaUvclDdxVtesy';
update content_bodies set title = 'Only one sword smithing experience in Kyoto!', description = 'Masahiro is a renowned sword smith located in Kyoto, Japan, known for crafting Katana swords in his studio situated in the Woodland area. Visitors have the unique opportunity to forge their own small Katana knife at his workshop. For more details, please visit https://morinokyoto.jp/masahiro/' where id = '3jRuFlUaRV1ffSsTQW9nK';
