update content_bodies set title = '森の京都　伝統食・行事食の歳時記', description = 'この動画では、森の京都における伝統的な食文化や行事に関連する食事について紹介しています。地域の特性や季節ごとの食材を活かした料理がどのように受け継がれているのか、またそれらが地域の行事や祭りとどのように結びついているのかを探ります。森の京都の豊かな食文化を通じて、地域の歴史や人々の生活様式を知ることができる内容となっています。' where id = 'ZUc1ZUk70lEOfoR8mYZGQ';
update content_bodies set title = 'Forest Kyoto: A Chronicle of Traditional and Seasonal Foods', description = 'This video introduces the traditional and seasonal foods of Forest Kyoto.' where id = 'LjpsEez4QTe52JM4hTxfK';
