update content_bodies set title = 'ざるやぶり神事', description = 'ざるやぶり神事は、約450年の伝統を持つ祭りです。ふんどし姿の青年たちが、神前に供えられたお饌米が入った直径約90㎝のざるを奪い合います。体をぶつけ合いながらもみ合う姿は迫力があり、観客を魅了します。' where id = 'T4lOKqnbn2eqJT2bfUv6q';
update content_bodies set title = 'Zaruyaburi Festival', description = 'The Zaruyaburi Festival is a traditional event that has been passed down for approximately 450 years. Young men dressed in fundoshi (traditional Japanese loincloths) compete to snatch a large bamboo basket, about 90 cm in diameter, which contains offerings of rice placed before the deity. The scene of these young men colliding and grappling to break the basket is filled with excitement and intensity.' where id = 'NN72PDEHkrXoPMFZ5dCsL';
update content_bodies set title = '森を食べる', description = 'この動画は「森を食べる」というプロジェクトを紹介しています。このプロジェクトは、食と自然の関係を探求する内容です。' where id = 'IGulgKoUkSXCXX1ecSIuF';
update content_bodies set title = 'To Eat the Forest', description = 'This video introduces To Eat the Forest, a project that explores the relationship between food and nature.' where id = '8HcovfZ7DuzyTwC_ZVcBF';
