update content_bodies set title = 'To Be Born from the Forest', description = 'This video introduces To Be Born from the Forest.' where id = 'oqFHrNCuCRp5uWkKedcF8';
update content_bodies set title = '森と共に生きる', description = 'この動画は「森と共に生きる」を紹介しています。' where id = 'hw1-buOoJjglnV6YqaASl';
update content_bodies set title = 'To Live with the Forest', description = 'This video introduces To Live with the Forest.' where id = 'Y0lKVZrHeoOq2vzYHSAdf';
update content_bodies set title = '森を食べる（短縮版）', description = '京都エリアの森における狩猟の現場に密着し、森の恵みを食べることや命を頂くことがどのような意味を持つのかを追求する内容です。' where id = 'J-d4_SKXgbJ1fp_foxyU9';
update content_bodies set title = 'Eating the Forest (Short Version)', description = 'This piece closely follows the hunting scene in the Kyoto forest area. It explores what it means to eat the blessings of the forest and to take life.' where id = 'O8C7ep_cR89DnguR3er8T';
update content_bodies set title = '森と生きる（短縮版）', description = '大自然の神々と人とをつなぐ祭りであり、自然と人間を結ぶ最も古く、そして当たり前の神事です。' where id = 'Btr20UwqJf5J9DHniz1mE';
update content_bodies set title = 'Living with the Forest (Short Version)', description = 'A festival that connects the gods of nature with humanity. It is the oldest and most natural ritual that binds nature and humans together.' where id = 'EGM0Jd3rF8vARocSm_HH9';
update content_bodies set title = '田歌の祇園さん', description = '田歌の祇園さんは、毎年7月14日に南丹市美山町田歌集落で行われるお祭りです。この祭りは古くからの伝統を受け継ぎながら、若い人々や移住者ともつながりを持ち、地域の文化を守り続けています。' where id = 'PN0zOjmIMbWFVb4fVU4lX';
update content_bodies set title = 'Taka''s Gion Festival', description = 'The Taka''s Gion Festival is held annually on July 14 in the Taka community of Miyama Town, Nantan City. This festival preserves ancient traditions while connecting younger generations and newcomers to the area.' where id = 'RJ0AlxDTPM1vC_cKyNr7M';
update content_bodies set title = '森を食べる', description = 'このドキュメンタリーは、京都エリアの森における狩猟の現場に密着しています。野生動物の数が増えることで、駆除しなければならない動物も出てきますが、そのことを単に悩むのではなく、森の恵みとして食べることに焦点を当てています。命を頂くことが何を意味するのかを追求する映像作品です。' where id = 'fyueHTWZfjCT578SLDvMM';
update content_bodies set title = 'Eating the Forest', description = 'This documentary closely follows the hunting scene in the Kyoto area of the forest. As the population of wild animals increases, some must be culled. Instead of merely lamenting this necessity, the focus is on consuming these animals as a gift from the forest. The film explores what it means to take a life.' where id = 'ioHWzThDekTxQwRjXai3U';
update content_bodies set title = '森で産まれる', description = '森の京都エリアにおける伝統を受け継ぐ職人やクリエイターへのインタビューを中心に、森の京都でのモノづくりに密着した内容です。職人たちの技や創造性を通じて、地域の文化や伝統がどのように息づいているのかを探ります。' where id = 'vzM3z4kcjPZUlmrVjgy0Y';
update content_bodies set title = 'Born in the Forest', description = 'This project focuses on the craftsmanship and creativity in the Kyoto area of the forest, featuring interviews with traditional artisans and creators. It closely examines the process of making things in the forest of Kyoto.' where id = 'yx-HB6oiaSmPnmnW2MPq0';
update content_bodies set title = '森と生きる', description = '大自然の神々と人々をつなぐ祭りです。森の京都エリアで行われる祭りをダイジェストで紹介し、そこに住む人々と自然との関わりを詳しく紹介します。' where id = 'AKW2tAowksKN_R0GUiAgR';
update content_bodies set title = 'Living with the Forest', description = 'A festival that connects the gods of nature with people. This summary introduces the festivals in the Kyoto area of the forest, highlighting the relationship between the local residents and nature.' where id = 'V1TPbKcJdVkle6Pv90eWv';
update content_bodies set title = '【京都 滋賀 比叡山】ガーデンミュージアム比叡、星野リゾート ロテルド比叡、夢見が丘 Mt.Hiei', description = '比叡山の山頂には、花々が咲き誇る庭で名画を楽しむことができる「ガーデンミュージアム比叡」があり、ここからは京都方面やびわ湖方面の壮大な景色を望むことができます。また、山のオーベルジュである「星野リゾート ロテルド比叡」や「比叡山ドライブウェイ 夢見が丘」も美しい映像を通じて紹介されています。各スポットへのアクセスについては、公式ウェブサイトをご覧ください。' where id = 'pSZz3oea0bizgztowKdoR';
update content_bodies set title = 'Hieizan: Garden Museum Hiei, Hoshino Resort Hotel de Hiei, Yumemigaoka Mt. Hiei', description = 'At the summit of Hieizan, the Garden Museum Hiei offers a stunning display of flowers alongside famous artworks, providing breathtaking views of Kyoto and Lake Biwa. Additionally, the mountain auberge Hoshino Resort Hotel de Hiei and the Hieizan Driveway Yumemigaoka are introduced through beautiful visuals. For access to each spot, visit the official website.' where id = '9IqZ6TJxZARzi8Ym8Fzk5';
update content_bodies set title = '【比叡山】延暦寺　東塔、西塔、横川', description = '比叡山全体に広がる延暦寺の東塔、西塔、横川には、100のお堂が点在しています。世界文化遺産に登録されている比叡山延暦寺を、美しい映像と共に紹介します。各スポットへのアクセス情報は公式ウェブサイトで確認できます。' where id = 'YIdWqSO-prGWPncl3TTNL';
update content_bodies set title = 'Hieizan, Enryakuji Temple, Mt Hiei', description = 'This presentation showcases the entire Hieizan area, featuring the East Pagoda, West Pagoda, and Yokokawa, which collectively house 100 halls. Enryakuji Temple, a UNESCO World Heritage site, is highlighted through beautiful visuals. For access to each spot, visit the official website.' where id = 'oxThpAPe1TY5b4Ymj5Wgx';
update content_bodies set title = 'SKY HOP BUS ぐるっと森の京都〈亀岡編〉', description = 'この動画では、SKY HOP BUSの亀岡編を紹介しています。亀岡の自然や観光スポットを巡るツアーの魅力を伝えています。' where id = 'raYqN-vNlLS0EHNZUxSYl';
update content_bodies set title = 'SKY HOP BUS: Exploring the Forest of Kyoto (Kameoka Edition)', description = 'This video introduces the SKY HOP BUS tour focusing on the Kameoka area of the Forest of Kyoto.' where id = 'rxHeUIi-R_oScM_0fFuy6';
update content_bodies set title = 'ミキモト真珠島', description = 'ミキモト真珠島は、明治26年に御木本幸吉が世界で初めて真珠の養殖に成功した場所です。夏休み期間中には、真珠のティアラをつけて記念撮影ができる「真珠のティアラで華麗に変身」や、淡水真珠を使った「ストラップ工房」や「万華鏡工房」などのイベントが開催されます。詳細については、公式ウェブサイト「観光三重」をご覧ください。' where id = 'ZPubLahPG5rJld4FbP8b5';
update content_bodies set title = 'Mikimoto Pearl Island', description = 'Mikimoto Pearl Island is the site where Kokichi Mikimoto succeeded in cultivating pearls for the first time in the world in 1893. During the summer vacation, visitors can enjoy activities such as ''Transforming Elegantly with Pearl Tiara,'' where they can wear a pearl tiara and take commemorative photos with their own cameras. Additionally, there are workshops for creating items using freshwater pearls, including a ''Strap Workshop'' and a ''Kaleidoscope Workshop.'' For more details, please visit the official website ''Kankomie.''' where id = 'FJtkZjQpnsWit1JYMEOEf';
update content_bodies set title = '伊勢・安土桃山文化村', description = '安土城を丸ごと使ったお化け屋敷はここだけの特別な体験です。業火に苦しむ人々の叫び声が響く地獄絵図が広がります。来場者には指令が与えられ、怨霊がうごめく安土城から無事に脱出できるかが試されます。詳細については、公式ウェブサイト「観光三重」をご覧ください。' where id = 'KVdapl9YA6ctyR3bZAdKY';
update content_bodies set title = 'Ise Azuchi Momoyama Culture Village', description = 'The haunted house that fully utilizes Azuchi Castle is unique to this location! Visitors will experience a hellish scene of agony and chaos as they are tormented by flames. Each guest receives a mission, and the challenge is to escape safely from the haunted Azuchi Castle filled with vengeful spirits. For more details, please visit the official website ''Kankomie''.' where id = '1_5fzkf7G9qZWa8_zNhVb';
update content_bodies set title = '【滋賀 坂本 比叡山】 日吉大社、西教寺、旧竹林院、坂本ケーブル、おごと温泉', description = '滋賀県坂本（大津市）は比叡山延暦寺の門前町として栄え、地元の祭り「山王祭」や日帰り温泉、足湯が楽しめるおごと温泉が魅力です。この映像では、日吉大社や山王祭、坂本ケーブル、西教寺、旧竹林院などの観光スポットを美しい映像と共に紹介しています。各スポットへのアクセス情報も提供されています。' where id = 'XS5sL1MF8bxoAjRMFb5RP';
update content_bodies set title = 'Mt.Hiei Sakamoto: Hiyoshi Taisha, Saikyo-ji, Former Bamboo Grove, Sakamoto Cable, Ogoto Onsen', description = 'This video showcases the scenic beauty of Sakamoto in Shiga Prefecture, a town that flourished as the gateway to Mount Hiei and is known for the Sanno Festival, one of the three major festivals in Otsu. It also features Ogoto Onsen, which offers day-use hot springs and foot baths. The video includes highlights of various attractions such as Hiyoshi Taisha, the Sanno Festival, Sakamoto Cable, Saikyo-ji, and the Former Bamboo Grove, all presented with beautiful visuals.' where id = 'TCw-cOOT2Se-mhQrS-7J8';
update content_bodies set title = '【絶景動画ループ】【4K高画質】北海道の絶景&ドローン映像｜総集編 計21スポット｜観賞・リラックス用', description = 'この動画は、北海道の魅力的な観光スポットや観光資源を紹介する総集編です。2023年に紹介された絶景動画を集め、肉眼ではなかなか見られないドローンによる空撮映像を含む、北海道の絶景を4K画質でお届けします。全21スポットを収録しており、ボリューム満点で、ながら視聴にも最適です。紹介されるスポットには、滝野スノーワールドや北海道開拓の村、ウトナイ湖などが含まれています。' where id = 'wxtgstwDf_GpHjyU02uiT';
update content_bodies set title = 'Superb view of Hokkaido【compilation vol.2】', description = 'This video compilation showcases the stunning tourist spots and attractions of Hokkaido, featuring breathtaking views captured from various angles. The 2023 highlights include aerial drone footage that offers perspectives rarely seen by the naked eye. With a total of 21 locations, this 4K video is perfect for relaxation and casual viewing. The featured spots include Takino Snow World, Hokkaido Pioneer Village, Lake Utonai, and many more, providing a comprehensive look at the beauty of Hokkaido.' where id = 'iarzA1DXawXK5E5R9uIxE';
update content_bodies set title = '三笠市桂沢湖 4K／北海道の絶景景色', description = '北海道の観光スポット「桂沢湖」を紹介する動画です。桂沢湖は桂沢ダムの完成によりできた人工湖で、周囲62kmの美しい自然景観に囲まれ、道立自然公園に指定されています。また、桂沢湖周辺は化石の宝庫としても知られ、アンモナイトなどの化石が多数発見されており、一部は三笠市立博物館に展示されています。湖では四季折々の風景を楽しむことができ、訪れる人々に素晴らしい体験を提供します。' where id = 'u3G0mgOI30R8YcU9ywyg0';
update content_bodies set title = 'Katsurazawa Lake in Mikasa City 4K / Superb View of Hokkaido', description = 'This video introduces Lake Katsurazawa in Mikasa City, Hokkaido, showcasing the region''s stunning natural scenery from various angles. Lake Katsurazawa is an artificial lake formed by the completion of the Katsurazawa Dam, with a circumference of 62 km and surrounded by beautiful forests, designated as a prefectural natural park. The area is also renowned for its rich fossil deposits, including ammonites, with some specimens displayed at the Mikasa City Museum. Visitors can enjoy the picturesque views of the lake throughout the four seasons.' where id = 'W43j7y-9fS25jCp35JD79';
update content_bodies set title = '熊野大花火大会', description = '熊野大花火大会では、約10000発の迫力ある花火が打ち上げられます。フィナーレでは、鬼ヶ城の岩場や洞窟から仕掛け花火が打ち上がり、爆発音が岩場で共鳴し、観客を魅了する大迫力の演出が行われます。' where id = 'gePgbzL-stBmt_FzspZ1x';
update content_bodies set title = 'Kumano Grand Fireworks Festival', description = 'The Kumano Grand Fireworks Festival features an impressive display of approximately 10,000 fireworks. The grand finale showcases the Oni no K城''s spectacular fireworks, which are launched from the rocky cliffs and caves of Oni no K城. The explosive sounds resonate off the rocks, creating a powerful and captivating performance.' where id = '7V9CKluMnMBp8Nz3FatZe';
update content_bodies set title = 'クッチャロ湖 4K／北海道の絶景景色', description = '北海道の観光スポット「クッチャロ湖」を紹介します。クッチャロ湖は、浜頓別町に位置し、国内最北のラムサール条約指定地です。日本とロシアを結ぶ水鳥の重要な中継地であり、多くの渡り鳥が訪れます。特に春と秋には、数千羽のコハクチョウや数万羽のカモ類が観察でき、冬には天然記念物のオジロワシやオオワシも見ることができます。詳しくはリンクをご覧ください。' where id = 'do3YiSuwk371wk7IGAu1e';
update content_bodies set title = 'Lake Kutcharo 4K / Superb view of Hokkaido', description = 'This video introduces Lake Kutcharo, located in Hamatonbetsu Town, Hokkaido, showcasing the stunning scenery of the region from various angles. Lake Kutcharo is the northernmost Ramsar site in Japan, serving as a crucial stopover for migratory waterfowl between Japan and Russia. During spring and autumn, thousands of swans and tens of thousands of ducks can be observed, while in winter, the lake is home to natural monuments such as white-tailed eagles and Steller''s sea eagles. For more details, visit the provided link.' where id = 'ByMjOXrweW_VYxkC5UAtw';
update content_bodies set title = '東京ディズニーランドの待ち時間の意味', description = '東京ディズニーランドのプーさんのハニーハントにおける待ち時間は、単なるランダムなものではなく、特定の意味を持っています。これらの待ち時間を理解することで、訪問者はアトラクションの人気や運営の効率についての洞察を得ることができ、体験を向上させることができます。この情報は、ゲストが訪問をより効果的に計画し、パークでの時間を最大限に活用するのに役立ちます。' where id = 'rIiMAOvBe66Kw_pP33RTU';
update content_bodies set title = 'What these random wait times mean at Tokyo Disneyland', description = 'The wait times at Pooh''s Hunny Hunt in Tokyo Disneyland are not just random; they carry specific meanings. Understanding these wait times can enhance the experience for visitors, providing insights into the attraction''s popularity and operational efficiency. This information can help guests plan their visit more effectively, ensuring they make the most of their time at the park.' where id = '_RuJmzg63ZWDtIqevmGCH';
update content_bodies set title = '宮島沼 4K／北海道の絶景景色', description = '「BEST HOKKAIDO」では、北海道の魅力的な観光スポットや観光資源を紹介しています。今回は、美唄市に位置する「宮島沼」を取り上げます。この沼は、毎年春と秋に多くのマガンが飛来することで知られています。面積25ヘクタール、平均水深55センチメートルの小さく浅いこの沼は、マガンの重要な中継地としてラムサール条約に登録されています。また、ハクチョウなど多くの野鳥が観察できる場所でもあり、バードウォッチング愛好者にとっては貴重なスポットです。' where id = 'tctV-LtaOdCmL4ZKa6vBx';
update content_bodies set title = 'Miyajima Swamp 4K / Superb view of Hokkaido', description = 'BEST HOKKAIDO introduces the attractive tourist spots and resources of Hokkaido. This time, we focus on Miyajima Swamp in Bibai City, known for the large numbers of white-fronted geese that migrate there every spring and fall. Covering an area of 25 hectares with an average depth of 55 cm, this small and shallow marsh is recognized under the Ramsar Convention as an important staging area for these geese. It is also a haven for birdwatchers, offering sightings of various other birds, including swans.' where id = 'TOPHnCFrwPYX3B9kZMNuT';
update content_bodies set title = '札幌市豊平川さけ科学館 4K／北海道の絶景景色', description = '北海道の魅力的な観光スポットや観光資源を紹介するBEST HOKKAIDO。今回は、札幌市南区に位置する「札幌市豊平川さけ科学館」をご紹介します。この科学館は、1984年にカムバックサーモン運動の一環として、豊平川に帰ってきたサケを見た市民の声を受けて開館しました。サケのふ化放流事業に加え、サケの仲間や豊平川の淡水魚を飼育・展示し、サケや豊平川に関する多様な情報を発信しています。' where id = 'h9NyYzjTWFWGL2cObN6Gf';
update content_bodies set title = 'Sapporo Salmon Museum 4K / Superb view of Hokkaido', description = 'BEST HOKKAIDO introduces attractive tourist spots and resources in Hokkaido. This time, we present the Sapporo Salmon Museum located in Minami Ward, Sapporo City. Opened in 1984, the museum was established in response to citizens witnessing salmon returning to the Toyohira River during the comeback salmon campaign. Besides the salmon hatching and release project, the museum raises and displays various salmon species and freshwater fish from the Toyohira River, providing a wealth of information about salmon and the river.' where id = 'W85YcglkYfWPttuaAmP39';
update content_bodies set title = '2023 さっぽろオータムフェスト', description = '2023年9月8日から9月30日まで、北海道札幌市で開催される「2023さっぽろオータムフェスト」は、200万人以上が来場する食の祭典です。このイベントは、札幌市の中心にある大通公園で秋の実りを祝うもので、2つの主要会場があります。7丁目会場「大通公園7丁目BAR」では、北海道産のワインや日本酒、クラフトビールと、それに合う海鮮や肉料理が楽しめます。8丁目会場「さっぽろ大通ほっかいどう市場」では、約80のブースが出店し、北海道各地の特産品や地元の味を楽しむことができます。' where id = 'WyFm012eCcgLXqV8U7uL7';
update content_bodies set title = '2023 Sapporo Autumn Fest', description = 'The 2023 Sapporo Autumn Fest is a gourmet event taking place in Sapporo City, Hokkaido, from September 8 to September 30, 2023. This food festival attracts over 2 million visitors and celebrates the autumn harvest at Odori Park, a central relaxation spot for citizens. The event features two main venues: the 7-chome venue, named ''Odori Park 7-chome BAR,'' which offers Hokkaido wines, sake, craft beers, and unique gourmet foods that pair well with these beverages; and the 8-chome venue, ''Sapporo Odori Hokkaido Market,'' showcasing around 80 booths from various municipalities and organizations in Hokkaido, allowing visitors to enjoy local flavors and specialty products from across the region.' where id = 'BumeZHZSLXEoRKY1e35RW';
update content_bodies set title = '道の駅石狩「あいろーど厚田」4K／北海道の絶景景色', description = 'この記事では、石狩市の国道231号線（オロロンライン）沿いにある道の駅石狩「あいろーど厚田」を紹介します。1階には石狩の地場産品を扱うショップと飲食テナントがあり、2階は町の文学や芸術、自然、歴史に触れられる展示コーナーとテイクアウトグルメを楽しめる店舗が並ぶ歴史と食のフロアです。3階には厚田の街並みを一望できる展望バルコニーがあり、晴れた日には石狩湾や手稲山、遠くの積丹半島まで見渡せます。特にこの展望バルコニーは、夕暮れ時に日本海に沈む夕日を楽しむことができる絶景スポットとして有名です。また、9月1日から10月31日までデジタルスタンプラリーとSNSキャンペーンも実施中です。' where id = 'yJwn1zlu7i9n6p_elHN7-';
update content_bodies set title = 'Roadside Station Ishikari ''Airoad Atsuta'' 4K / Superb view of Hokkaido', description = 'This article introduces Roadside Station Ishikari ''Airoad Atsuta,'' located along National Route 231, known as the Ororon Line, in Ishikari City. The first floor features a shop selling local Ishikari products and a restaurant. The second floor offers a history and food area with exhibitions on the town''s literature, art, nature, and history, along with take-out gourmet options. The third floor boasts a balcony with stunning views of the Atsuta cityscape, Ishikari Bay, Mt. Teine, and the distant Shakotan Peninsula on clear days. The observation balcony is particularly famous for its breathtaking sunset views over the Sea of Japan, creating a memorable experience. Additionally, a digital stamp rally and an SNS campaign for local products are ongoing until October 31.' where id = 'gvfq_6sdQU3UhagUU_L9f';
update content_bodies set title = '厚田キャンプ場 4K／北海道の絶景景色', description = '今回は石狩市にある「厚田キャンプ場」を紹介します。厚田キャンプ場は、野鳥や昆虫、小動物が遊ぶ森の中に位置しています。秋の9月中旬から10月中旬には、場内を流れる牧佐内川で鮭が遡上する様子を間近で観察できます。キャンプ場には車の乗り入れが可能で、炊事場や水洗トイレのほか、子ども向けの遊具やジップラインも完備されています。また、石狩の特産品が当たるSNSキャンペーンやスタンプラリーも実施中で、石狩の魅力を探しに行く良い機会です。' where id = 'lZOjju0QWkNbOwF_Qz34G';
update content_bodies set title = 'Atsuta Campgrounds 4K / Superb view of Hokkaido', description = 'This introduction highlights the Atsuta Campgrounds located in Ishikari City, Hokkaido. The campgrounds are set in a forest where wild birds, insects, and small animals thrive. During autumn, from mid-September to mid-October, visitors can observe salmon swimming upstream in the Bokusanai River, which flows through the site. The campgrounds are accessible by car and offer various facilities, including a kitchen, flush toilets, and play areas for children, featuring a zip line and playground equipment. The campaign also encourages visitors to explore Ishikari''s attractions and participate in a social media contest for a chance to win local specialties.' where id = 'mnZHMk_ZaIpcf6gsdoHxe';
update content_bodies set title = '2023年最新の三重のサウナ3選♨✨', description = '三重県には、サウナー必見のスポットが多数あります。滝の目の前で楽しめるテントサウナ、サービスが充実したおふろcafé、絶景を眺めながら入れるサウナなど、さまざまな体験が可能です。特に、飛雪の滝キャンプ場ではテントサウナが楽しめ、湯守座では多彩なサービスが提供され、カブクリゾートでは山の中でのサウナ体験が待っています。自然の中でリラックスしたい方に最適な場所です。' where id = 'PSCAudKEdvc30vG7-4ysA';
update content_bodies set title = 'Top 3 Saunas in Mie Prefecture for 2023', description = 'Mie Prefecture offers a variety of must-visit sauna spots for enthusiasts. You can enjoy a tent sauna right in front of a waterfall, experience a service-rich bath café, or relax in a sauna with breathtaking views. Notable locations include Hisetuf Falls Campsite, known for its tent sauna, Yumoriza, a bath café with numerous amenities, and Kabukuri Resort, which features a mountain sauna. These spots are perfect for anyone looking to unwind and enjoy nature.' where id = '6g-J18wo8icHgWQYwOINA';
update content_bodies set title = '川下海水浴場（はまますピリカ・ビーチ）4K／北海道の絶景景色', description = '今回は、札幌市の隣に位置する石狩市の「川下海水浴場（はまますピリカ・ビーチ）」を紹介します。札幌市から車で約90分の距離にあり、道央で人気の海水浴場で、毎年約2万人の海水浴客で賑わいます。ビーチには美しい芝生が整備された川下海浜公園が隣接しており、炊事場や水洗トイレも完備されているため、キャンプも楽しめます。また、車で5分ほどの距離には浜益温泉もあり、訪れる人々にとって魅力的なポイントです。' where id = 'rZQrSVz2wDgpnj3pD_Hef';
update content_bodies set title = 'Kawashimo Swim Area (Hamamasu Pirika Beach) 4K / Superb view of Hokkaido', description = 'This video introduces the Kawashimo Swim Area, also known as Hamamasu Pirika Beach, located in Ishikari City, near Sapporo. It takes about 90 minutes by car from Sapporo. The beach is popular in central Hokkaido, attracting around 20,000 visitors each year. Adjacent to the beach is Kawashimo Seaside Park, featuring well-maintained lawns, cooking facilities, and flush toilets, making it suitable for camping. Additionally, Hamamasu Onsen is just a 5-minute drive away, adding to the appeal of the location.' where id = 'nfXguFSkuzIh24PkWc6Y_';
update content_bodies set title = '紋別市の観光スポット 4K／北海道の絶景景色', description = 'この動画では、北海道の魅力的な観光スポットや観光資源を紹介し、様々な角度から絶景をお届けします。北海道北部に位置する紋別市には、いくつかの注目すべき観光地があります。まずは、世界初の氷海展望塔「オホーツクタワー」。ここでは、オホーツク海を一望できるパノラマ展望台や、地元の海洋生物を展示したミニ水族館があります。次に、唯一の海岸沿いの道立公園「オホーツク流氷公園」では、屋内外の遊具やラベンダー畑、パークゴルフ場など多様な楽しみ方ができます。最後に、紋別の名産ズワイガニの爪を表現した高さ12mの「カニの爪オブジェ」があり、1983年の流氷アートフェスティバルのために作られ、紋別観光のシンボルとなっています。' where id = 'e6pSTVKMWUtlZeo6yH635';
update content_bodies set title = 'Tourist Spots in Mombetsu City 4K / Superb View of Hokkaido', description = 'This video introduces various attractive tourist spots and resources in Hokkaido, showcasing the stunning scenery from different angles. Mombetsu City, located in northern Hokkaido, features several notable attractions. The first is the ''Okhotsk Tower,'' the world''s first ice sea observation tower, offering panoramic views of the Sea of Okhotsk and a mini aquarium showcasing local marine life. Next is the ''Okhotsk Sea Ice Park,'' the only coastal prefectural park, which includes playgrounds, a lavender field, and a park golf course for diverse recreational activities. Lastly, the 12-meter tall ''Crab Claw Object,'' representing Mombetsu''s specialty snow crab, serves as a symbol of the city and was created for the Drift Ice Art Festival in 1983.' where id = 'TPheeq4oSUlzQICWKGAbO';
update content_bodies set title = '松阪祇園まつり', description = '宵宮の午後、松阪・御厨・八雲の3つの神社から「三社みこし」が繰り出されます。揃いの法被姿で1000人もの老若男女が「チョーサヤ」の掛け声と共に町を勇壮に練り歩きます。本日には「松阪しょんがい音頭と踊り」などの伝統的な踊りやステージイベントが披露される予定です。' where id = '-Vrqlb0lzTGxAHsle_kyx';
update content_bodies set title = 'Matsusaka Gion Festival', description = 'In the afternoon of the evening festival, the ''Three Shrine Mikoshi'' emerges from the Matsusaka, Mikuriya, and Yakumo shrines. Around 1,000 people of all ages, dressed in matching happi coats, march through the town with the spirited chant of ''Chosaya.'' Today''s events include traditional dances such as the ''Matsusaka Shongai Ondo'' and various stage performances.' where id = 'hgcgUo_qothqILlw-U8Tx';
update content_bodies set title = '芝ざくら滝上公園 4K／北海道の絶景景色', description = '「BEST HOKKAIDO」では、北海道の魅力的な観光スポットを紹介しています。今回は、滝上町にある「芝ざくら滝上公園」をご紹介します。この公園は、5月上旬から6月上旬にかけて咲く美しいピンクの芝ざくらで知られています。みかん箱一杯の苗から始まり、約50年の間に町民の努力により成長し、今では日本最大の10万平方メートルの群落を誇ります。訪れる人々は、街を包み込む甘い香りと丘陵地を流れる渓谷に魅了され、夢のような世界に誘われます。ぜひ、絵画のような美しい風景を体感してください。' where id = 'IBsT8NjNdXwkHWh27FfF8';
update content_bodies set title = 'Shibazakura Takinoue Park 4K / Superb view of Hokkaido', description = 'BEST HOKKAIDO introduces the captivating tourist spots and resources of Hokkaido. This time, we present Shibazakura Takinoue Park, renowned for its stunning pink moss phlox that blooms from early May to early June. Originating from a box of mandarin orange seedlings, the park has flourished over the past 50 years due to the dedication of the local community, now boasting Japan''s largest moss phlox colony, covering 100,000 square meters. Visitors are enchanted by the sweet fragrance of the flowers and the picturesque valley that flows through the hills. Experience the breathtaking scenery that resembles a beautiful landscape painting.' where id = 'HxZ-omwxiXZtZIeUy8lx3';
update content_bodies set title = '前田森林公園 4K／北海道の絶景景色', description = '今回は、札幌市手稲区にある前田森林公園をご紹介します。この公園は、札幌市全体を緑地で囲むという構想に基づき、何もないところから森林を作り上げるのに10年をかけて完成しました。公園の半分は森林で、春には桜、秋には紅葉と、四季折々の樹木を楽しむことができます。また、展望ラウンジからは手稲山に向かって伸びるカナールと、約200本のポプラの木が異国情緒を醸し出しています。清々しい空気の中で散歩やジョギングを楽しむことができる素晴らしい場所です。' where id = 'vA_2QUFqDRqUqcHHRJ_Zf';
update content_bodies set title = 'Maeda Forest Park 4K / Superb view of Hokkaido', description = 'This video introduces Maeda Forest Park located in Teine Ward, Sapporo City, as part of the BEST HOKKAIDO series showcasing the attractions of Hokkaido. The park was developed over a decade, transforming a barren area into a lush forest, with half of its area dedicated to trees. Visitors can enjoy the beauty of cherry blossoms in spring and autumn foliage throughout the year. The park features a canal leading to Mt. Teine, surrounded by around 200 poplar trees, creating an exotic ambiance. It is an ideal spot for walking or jogging while enjoying the fresh air.' where id = '_obdeyGo9qa9oh9enmk__';
update content_bodies set title = '戸田記念墓地公園 4K／北海道の絶景景色', description = '今回紹介するのは、春に美しい桜を楽しめる「戸田記念墓地公園」です。石狩市に位置するこの公園には、約8000本の桜があり、特に人気のスポットとして、200メートルにわたる桜のトンネルを形成するＡ区の「桜冠の道」や、400メートルの桜並木が魅力的なＣ区の「桜花の道」があります。また、園内の奥にあるＨ・Ｉ区では、幹線道路沿いに咲く桜とその背後に広がる日本海や雪化粧した山々が素晴らしい景観を作り出しています。公園内には、ソメイヨシノやエゾヤマザクラなど、様々な種類の桜が植えられており、ほとんどが樹齢30～50年で、開園時に植えられました。' where id = 'bmX9Ia9kNqDtoYXiTEqp_';
update content_bodies set title = 'Toda Memorial Park 4K / Superb view of Hokkaido', description = 'This video introduces Toda Memorial Park in Ishikari City, Hokkaido, showcasing its stunning cherry blossoms in spring. The park features around 8,000 cherry trees, with notable spots like the 200-meter-long ''Okan no Michi'' cherry blossom tunnel in Section A and the impressive 400-meter-long cherry tree row in Section C. Additionally, the H and I districts offer breathtaking views of cherry blossoms alongside the main road, with the Sea of Japan and snow-capped mountains in the background. Various cherry blossom species, including Somei Yoshino and Ezoyamazakura, are present, most of which are 30 to 50 years old, planted at the park''s opening.' where id = 'zkHT8Sr_8qGW7wTq1ceNS';
update content_bodies set title = 'マクンベツ湿原 4K／北海道の絶景景色', description = '「BEST HOKKAIDO」では、北海道の魅力的な観光スポットを紹介しています。今回は、春を告げる花「ミズバショウ」を間近で鑑賞できる「マクンベツ湿原」を取り上げます。石狩市に位置するこの湿原は、約130ヘクタールの広さを持ち、石狩川の蛇行部に広がっています。4月中旬からミズバショウが開花し、北海道内でも有数の大群落を形成します。石狩河口橋の堤防沿いには1.5キロメートルの遊歩道が整備されており、400メートルの木道も河岸まで伸びています。野鳥のさえずりと共に、白く可憐なミズバショウを間近で楽しむことができます。' where id = '1TywivE9E6NMy8M8uddWz';
update content_bodies set title = 'Makumbetsu Marshland 4K / Superb view of Hokkaido', description = 'This video introduces the Makumbetsu Marshland, a stunning wetland in Ishikari City, Hokkaido, where visitors can enjoy the beauty of the Asian skunk cabbage, a flower that heralds spring. The marshland spans approximately 130 hectares along the meandering part of the Ishikari River. From mid-April, the skunk cabbage blooms under the alder forest, creating one of the largest colonies in Hokkaido. A 1.5-kilometer promenade and a 400-meter boardwalk provide access to the area, allowing visitors to appreciate the delicate white flowers while listening to the sounds of wild birds.' where id = '2xGcLQqWRZmTJThhfgjEo';
update content_bodies set title = 'キロロリゾート「謎解きレストラン」', description = '北海道の余市郡赤井川村にあるキロロリゾートで楽しめるスノーアクティビティ「謎解きレストラン」を紹介します。参加者は、スノードームで説明を受けた後、秘密基地の鍵を探しに出発します。制限時間は70分で、鍵を手に入れたら仲間と協力して数々の謎を解き、越冬野菜を集めます。謎を解き明かすことができれば、「至福の料理」が待っています。このアクティビティはゲーム要素があり、家族や友人と楽しい思い出を作ることができる素晴らしい体験です。' where id = 'zuN-OzdIQy-SYKWSkiaeH';
update content_bodies set title = 'Kiroro Resort ''Riddle Solving Restaurant''', description = 'This introduction highlights a unique snow activity at Kiroro Resort in Akaigawa Village, Yoichi-gun, called the ''Riddle Solving Restaurant.'' Participants embark on a quest to find the key to a secret base after receiving instructions at a snow dome, with a time limit of 70 minutes. Once the key is obtained, teams work together to solve various riddles to gather overwintering vegetables. Successfully solving the riddles leads to the reward of a ''Blissful Cuisine.'' This activity combines game elements with excitement, making it a perfect opportunity for families and friends to create memorable experiences together.' where id = 'OO1mjQu85oDmQY3GxdGTy';
update content_bodies set title = 'キロロリゾート「絶景プレミアムツアー」', description = 'この動画では、北海道余市郡赤井川村にあるキロロリゾートで楽しめるスノーアクティビティ「絶景プレミアムツアー」を紹介します。ツアーはリゾートから冷水峠まで車で移動し、スノーシューを装着して深い雪の中を数百メートル先のカルデラ展望所を目指して歩きます。展望所からは「日本で最も美しい村」と称される赤井川村の美しい景色が広がり、天候が良ければ遠くにニセコ連峰や羊蹄山も望むことができます。展望所に到着後は、雪で作ったテーブルと椅子でコーヒーブレイクを楽しみ、冬の寒さの中で水飴を使って絵を描き、固める貴重な体験もできます。' where id = 'aWTebCILCnIhfrUVSBAKT';
update content_bodies set title = 'Kiroro Resort ''Superb View Premium Tour''', description = 'This video introduces the ''Superb View Premium Tour,'' a snow activity at Kiroro Resort in Akaigawa Village, Yoichi-gun, Hokkaido. The tour begins with a drive from the resort to Hiyamizu Pass, where participants don snowshoes and trek through deep snow to reach the Caldera Observatory, located several hundred meters away. From this vantage point, visitors can enjoy breathtaking views of Akaigawa Village, often referred to as ''the most beautiful village in Japan.'' Weather permitting, the Niseko mountain range and Mt. Yotei can also be seen in the distance. After reaching the observatory, participants can take a coffee break at a table and chairs made of snow and engage in a unique experience of drawing with starch syrup, which can be hardened in the cold winter air.' where id = 'XR43ibDeKPjgjNMP2KFdm';
update content_bodies set title = '冬のウトナイ湖 4K／北海道の絶景景色', description = 'この映像では、北海道苫小牧市の東部に位置する淡水湖「ウトナイ湖」の冬の様子を紹介します。湖の周辺には原野や湿原が広がり、美々川、トキサタマップ川、勇払川から清流が流れ込んでいます。ウトナイ湖は、マガンや白鳥などの渡り鳥の飛来地として知られ、270種以上の鳥類が確認されています。1981年には日本初のバードサンクチュアリに指定され、翌年には国指定鳥獣保護区特別地区となりました。また、1991年には日本で4番目のラムサール条約湿地に登録されています。道の駅ウトナイ湖が隣接しており、食事も楽しめます。' where id = 'cz5LlVXiFw9WTWGfI0sT2';
update content_bodies set title = 'Winter Lake Utonai 4K / Superb view of Hokkaido', description = 'This video showcases Lake Utonai, a freshwater lake located in the eastern part of Tomakomai City, Hokkaido, during winter. The lake is surrounded by rich nature, including wetlands and grasslands, with clear streams flowing in from the Bibi River, Tokisatamappu River, and Yufutsu River. It is renowned as a habitat for migratory birds, hosting over 270 species, including white-fronted geese and swans. Designated as Japan''s first bird sanctuary in 1981 and a special national wildlife sanctuary the following year, it was also registered as the fourth Ramsar wetland in Japan in 1991. Visitors can enjoy meals at the adjacent roadside station, Lake Utonai.' where id = 'LzyTgyKpuNxSe46QZXfde';
update content_bodies set title = '北海道開拓の村 4K／北海道の絶景景色', description = '「北海道開拓の村」は、北海道の開基百年を記念して1983年に設立された野外博物館です。明治から昭和初期にかけて建築された建物を移築・復元し、重要な文化資産を保存することを目的としています。村内には52棟の建物があり、市街地、漁村、農村、山村の4つのエリアに分かれています。訪れる人々は、開拓当時の生活を体験できる伝統的な遊具作りやわら細工のワークショップに参加することができます。詳細は公式ウェブサイトをご覧ください。' where id = 'EYYZN8-AgJX5ejKgrIpcG';
update content_bodies set title = 'Historical Village of Hokkaido 4K / Superb view of Hokkaido', description = 'The ''Historical Village of Hokkaido'' is an open-air museum that showcases relocated and restored buildings from the Meiji to early Showa eras, established in 1983 to commemorate Hokkaido''s 100th anniversary. The museum aims to preserve important cultural assets and provide visitors with an immersive experience of life during the pioneering days. It features 52 buildings divided into four areas: Town, Fishing Village, Farm Village, and Mountain Village. Visitors can engage in traditional activities such as making playground equipment and participating in straw craft workshops. For more details, visit the official website.' where id = 'O-CyT4iR5JbvJLzJL6DSh';
update content_bodies set title = '楯ヶ崎【ドローン撮影】(熊野市)｜観光三重｜三重県の観光・旅行情報', description = '三重県熊野市の観光スポット「楯ヶ崎」をドローンで撮影した映像です。高さ100ｍ、周囲600ｍの岩壁は、無数の柱が連なったような美しい「柱状節理」を形成しており、その姿は圧巻です。陸路だけでなく、観光遊覧船に乗って海からも近くで見ることができ、訪れる人々に素晴らしい体験を提供します。' where id = 'b0j-ntqB7RuRlK1MFhWRP';
update content_bodies set title = 'Tategasaki [Drone Photography] (Kumano City) | Tourism Mie | Mie Prefecture Travel Information', description = 'This video showcases Tategasaki, a tourist spot in Kumano City, Mie Prefecture, captured through drone photography. The site features impressive columnar jointing rock formations that rise 100 meters high and stretch 600 meters around, creating a breathtaking sight. Visitors can admire this magnificent rock face not only by land but also by taking a sightseeing boat to view it from the sea.' where id = '19YSiDJIGZdW5KuZSI6fW';
update content_bodies set title = '大阪の夜の散歩 - 北新地周辺 | 4K HDR', description = 'この動画では、大阪の北新地周辺を夜に散歩する様子が紹介されています。活気ある雰囲気やこの人気エリアの夜の生活が映し出されています。' where id = 'wRk8J1CSjB3Qgw29RR5Sk';
update content_bodies set title = 'Osaka Night Walk - North Osaka around Kitashinchi | 4K HDR', description = 'This video features a night walk in North Osaka, specifically around the Kitashinchi area. The footage showcases the vibrant atmosphere and nightlife of this popular district.' where id = 'b5hQemFj9OKqeznfQEpPX';
update content_bodies set title = '滝野スノーワールド 4K／北海道の絶景景色', description = '「滝野スノーワールド」は、札幌市内の冬のあそびコンテンツを提供するイベント「さっぽろASOBIプロジェクト～Winter Season～」の一環として、1月28日からスタートします。このスノーアクティビティのスポットは、夏にキャンプが楽しめる「滝野すずらん丘陵公園」が冬に変身したもので、スキーやスノーボード初心者、子供連れでも安心して遊べるなだらかなゲレンデがあります。さらに、全長約200メートルのチューブそりやスノーシュー、歩くスキーも楽しめます。また、渓流ゾーンでは「鱒見の滝」や「アシリベツの滝」のしぶきが凍る「氷瀑」現象も見ることができるかもしれません。詳しくは滝野公園のウェブサイトをご覧ください。' where id = 'lJ2to2bVh3g9A-8kGFZfx';
update content_bodies set title = 'Takino Snow World 4K / Superb view of Hokkaido', description = 'Takino Snow World, a premier snow play destination in Sapporo, is featured in the Sapporo ASOBI Project''s Winter Season event starting January 28. This event showcases five venues in Sapporo with winter activities. Takino Snow World transforms from the Takino Suzuran Hillside Park, which offers camping in summer, into a winter wonderland for snow activities. It features gentle slopes suitable for beginners in skiing and snowboarding, as well as tube sledding, snowshoeing, and walking skiing. Visitors can also witness the stunning icefall phenomenon at Masumi Falls and Ashiribetsu Falls in the Keiryu Zone. For more details, visit the Takino Park website.' where id = 'typZ7YChoPjBmf5vqcr8J';
update content_bodies set title = 'いつきのみや歴史体験館プロモーション動画（明和町）', description = '三重県明和町にある「いつきのみや歴史体験館」のプロモーション動画です。この施設は、日本遺産に認定された「祈る皇女斎王のみやこ 斎宮」の舞台に位置しており、地域の歴史的な重要性を伝える役割を果たしています。この動画は、三重県観光キャンペーン中南勢地域部会によって制作されました。' where id = 'qTV_O2XvGT3Cdfv2CIKzS';
update content_bodies set title = 'Itsuki no Miya Historical Experience Center Promotional Video (Meiwa Town)', description = 'This is a promotional video for the ''Itsuki no Miya Historical Experience Center'' located in Meiwa Town, Mie Prefecture, which is recognized as a Japanese heritage site. The center is situated in the area that was once the stage for the ''Praying Princess Saio no Miya,'' highlighting the historical significance of the location.' where id = 'v8z1SG5VQk7mexGpDSZNK';
update content_bodies set title = '浦幌町 昆布刈石海岸 - 北海道の絶景', description = '今回紹介するのは、北海道十勝総合振興局管内の最東端に位置する浦幌町の「昆布刈石海岸」です。かつてアイヌの人々はこの海岸で収穫した昆布を和人と交換し、江戸に供給していたと伝えられています。標高約80メートルの「昆布刈石展望台」からは、昆布刈石海岸と広大な太平洋を一望できます。天気が良ければ、襟裳岬や釧路も見渡せる絶景スポットです。また、初日の出や流星群の観測スポットとしても人気があります。' where id = 'LAWa_CQJ5MnbeIOD2Twco';
update content_bodies set title = 'Kobukariishi Coast in Urahoro Town - Superb View of Hokkaido', description = 'This video introduces the stunning Kobukariishi Coast located in Urahoro Town, the easternmost part of the Tokachi region in Hokkaido. Historically, the Ainu people harvested kombu from this coast and exchanged it with the Japanese, supplying it to Edo. From the Kobukariishi Observatory, situated at an altitude of about 80 meters, visitors can enjoy breathtaking views of the coast and the vast Pacific Ocean. On clear days, the observatory also offers views of Cape Erimo and Kushiro. It is a popular spot for witnessing the first sunrise of the year and for observing meteor showers.' where id = 'UQ3tdy3B1jRo0o5_qWJt_';
update content_bodies set title = '恋人の聖地／厚田展望台 4K／北海道の絶景景色', description = '今回は、北海道の石狩市にある「恋人の聖地／厚田展望台」を紹介します。この展望台は日本海に面し、約80kmの海岸線を持っています。中世のお城のような石造りの展望台は、プロポーズにふさわしい観光スポットとして「恋人の聖地」プロジェクトで北海道初の選出を受けました。「誓いの鐘」や、恋人たちが南京錠を取り付けるためのフェンスが設置されています。展望台からは雄大な海岸線や美しい夕日を眺めることができ、石狩を代表する絶景スポットとして知られています。また、夜には美しい星空も楽しめるスポットです。' where id = '_6FuziqNelpViWQUKxKm4';
update content_bodies set title = 'Lover''s Sanctuary / Atsuta Observatory 4K / Superb view of Hokkaido', description = 'This video introduces the Atsuta Observatory in Ishikari City, Hokkaido, which faces the Sea of Japan and boasts an 80km coastline. The stone observatory resembles a medieval castle and was the first site in Hokkaido selected for the ''Lover''s Sanctuary'' project, which identifies 100 ideal spots for proposals. It features ''vows bells'' and fences for lovers to attach padlocks, symbolizing their commitment. Visitors can enjoy stunning views of the coastline and beautiful sunsets over the Sea of Japan, making it a renowned scenic spot in Ishikari. Additionally, it offers a breathtaking night view of the starry sky.' where id = '-nyZ9Fara1zaAZqxqgrXg';
update content_bodies set title = 'はまなすの丘公園 4K／北海道の絶景景色', description = '「はまなすの丘公園」は、日本海と石狩川の交わりに形成された細長い砂丘に広がる公園で、札幌中心部から車で約1時間の距離にあります。約46ヘクタールの敷地には、はまなすの花を含む180種類の植物が自生しており、美しい夕陽が眺められるスポットとしても有名です。公園の入口には、赤と白のストライプが特徴の「石狩灯台」があり、北海道最古の現存する灯台として100年以上の歴史を誇ります。また、「はまなすの丘公園ヴィジターセンター」では、石狩の特産品やハマナス関連商品が販売されており、2階のテラスからは日本海と石狩川の絶景を楽しむことができます。' where id = 'L366uz3W0PllxbZQeU-6I';
update content_bodies set title = 'Hamanasu Hill Park 4K / Superb view of Hokkaido', description = 'Hamanasu Hill Park is located about an hour''s drive from Sapporo, covering approximately 46 hectares and featuring around 180 types of plants, including Hamanasu flowers. The park is renowned for its stunning sunsets, thanks to its unobstructed views. At the entrance stands the Ishikari Lighthouse, a historic red and white striped lighthouse, recognized as the oldest existing lighthouse in Hokkaido, with over 100 years of history. The Hamanasu Hill Park Visitor Center offers souvenirs, including local specialties and Hamanasu-related products, and visitors can enjoy panoramic views of the Sea of Japan and the Ishikari River from the second-floor terrace.' where id = 'gQXWJ74Zcy1pp7_kZz7fa';
update content_bodies set title = 'うらほろ森林公園展望台 4K／北海道の絶景景色', description = 'この動画では、北海道の絶景を様々な角度から紹介し、特に十勝地方の東端に位置する浦幌町の「うらほろ森林公園展望台」からの眺望に焦点を当てています。浦幌町は、ゆるやかな丘陵地と河岸段丘から成り、東には丘陵山脈、南には太平洋が広がっています。展望台は、総面積120ヘクタールの広大な「うらほろ森林公園」内にあり、広い芝生の広場やオートキャンプ場、パークゴルフ場、散策路などの充実した設備が整っており、子どもから大人まで一日中楽しむことができる理想的な観光地です。' where id = 'JXSMnBoOqmbKj2OIUhABT';
update content_bodies set title = 'Urahoro Forest Park Observatory 4K / Superb view of Hokkaido', description = 'This video showcases the stunning views of Hokkaido from various angles, focusing on the Urahoro Forest Park Observatory located in Urahoro Town, at the eastern end of the Tokachi region. Urahoro Town features gentle hills and river terraces, stretching from the hills in the east to the Pacific Ocean in the south. The observatory is situated within the expansive 120-hectare Urahoro Forest Park, which offers a range of facilities including a large grassy area, an auto campground, a park golf course, and walking paths, making it an ideal destination for visitors of all ages.' where id = 'U8Zklyz3Ci2rU9B7NiyvP';
update content_bodies set title = '白い恋人パーク4K／北海道の絶景景色', description = '今回は、北海道の銘菓「白い恋人」で知られる石屋製菓のテーマパーク「白い恋人パーク」を紹介します。地下鉄東西線の宮の沢駅から徒歩約7分、札幌中心部から車で約25分の場所に位置し、西洋のお城を思わせる外観が特徴です。館内では、「白い恋人」の工場見学や、チョコレートの四大革命をプロジェクションマッピングで紹介する「チョコトピアハウス」、ここでしか味わえないスイーツが楽しめる「チョコレートラウンジ」、お菓子作り体験ができる「お菓子作り体験工房」など、見て、知って、味わって、体験できるテーマパークです。また、夏にはバラが咲き誇り、冬にはイルミネーションが煌く英国風の庭園もあり、撮影スポットとしてもおすすめです。' where id = 'iQbqox5zh430GmLST0rE5';
update content_bodies set title = 'Shiroi Koibito Park 4K / Superb view of Hokkaido', description = 'This introduction highlights ''Shiroi Koibito Park'', a theme park by ISHIYA, famous for Hokkaido''s confectionery ''Shiroi Koibito''. Located about 7 minutes on foot from Miyanosawa Station and 25 minutes by car from central Sapporo, the park features a castle-like exterior. Inside, visitors can explore the ''Chocotopia House'' showcasing the production of ''Shiroi Koibito'' and chocolate innovations through projection mapping. The ''Chocolate Lounge'' offers unique sweets, while the ''Sweets Workshop'' allows guests to create their own treats. The park also boasts an English-style garden, perfect for photography, with blooming roses in summer and dazzling illuminations in winter.' where id = 'AHpuSdX5VH4_HO37ktdj6';
update content_bodies set title = '滝野すずらん丘陵公園4K／北海道の絶景景色', description = '今回は、札幌市南部に位置する北海道唯一の国営公園「滝野すずらん丘陵公園」を紹介します。この公園は、中心部から約20km、車で約40分の距離にあり、400ヘクタールの広大な敷地を誇ります。公園は渓流ゾーン、中心ゾーン、滝野の森ゾーン（東・西）の4つのエリアに分かれています。渓流ゾーンでは、日本の滝100選の一つであるアシリベツの滝を含む4つの滝を巡り、川遊びやバーベキューが楽しめます。中心ゾーンには四季折々の花や大型遊具があり、子供から大人まで楽しめます。滝野の森ゾーンは豊かな自然に囲まれ、小さなお子様も遊べる遊具があります。冬季には「滝野スノーワールド」が開園し、スキーやスノーボード、チューブそりなどの冬のアクティビティが楽しめます。' where id = 'TPyR1qy2aikWUfs3QwePg';
update content_bodies set title = 'Takino Suzuran Hillside Park 4K / Superb view of Hokkaido', description = 'This video introduces Takino Suzuran Hillside Park, the only national park in Hokkaido, located about 20 km south of Sapporo city. The park spans 400 hectares and is divided into four zones: Keiryu Zone, Chushin Zone, and Takino no Mori Zone (east and west). In the Keiryu Zone, visitors can explore four waterfalls, including Ashiribetsu Falls, and enjoy river activities and barbecues. The Chushin Zone features seasonal flowers and large playground equipment suitable for all ages. The Takino no Mori Zone offers a nature-filled environment with playgrounds for small children. In winter, the park transforms into ''Takino Snow World,'' offering activities like skiing, snowboarding, and tube sledding, including one of Japan''s largest tube slides.' where id = 'gOYY9eyBtvMJDskFu-lnZ';
update content_bodies set title = 'さっぽろ羊ヶ丘展望台4K／北海道の絶景景色', description = '「さっぽろ羊ヶ丘展望台」は、石狩平野の雄大な景色を一望できる観光スポットです。北海道らしい牧歌的な風景が広がり、天候や時期によっては放牧された羊たちが草を食べる様子も見ることができます。札幌駅から車で約30分、新千歳空港から約50分の距離にあり、シンボルは「少年よ、大志を抱け」で有名なクラーク博士の銅像です。台座はポストになっており、夢や希望を書いた「大志の誓い」を投函することができます。施設内の「羊ヶ丘レストハウス」では、北海道のソウルフードであるジンギスカンを楽しめ、隣接する「オーストリア館」では「白い恋人ソフトクリーム」や「ラベンダーソフトクリーム」などのスイーツも味わえます。冬にはスノーパークとして、チューブソリ滑りや歩くスキーなどの雪のアクティビティも楽しめます。' where id = 'mQAcZyE5n8dxS19_7q4dv';
update content_bodies set title = 'Sapporo Hitsujigaoka Observation Hill 4K / Superb view of Hokkaido', description = 'This video introduces the Sapporo Hitsujigaoka Observation Hill, showcasing the magnificent scenery of the Ishikari plain. The site features a pastoral landscape typical of Hokkaido, where visitors can sometimes see sheep grazing, depending on the weather and season. Located about 30 minutes from Sapporo Station and 50 minutes from New Chitose Airport, the hill is marked by the bronze statue of Dr. Clark, known for the phrase ''Boys Be Ambitious.'' Visitors can post their dreams in a mailbox at the statue. The Hitsujigaoka Rest House offers Hokkaido''s soul food, Genghis Khan, while the adjacent Austrian Pavilion serves local sweets like Shiroi Koibito and lavender soft serve ice cream. In winter, the area transforms into a snow park for activities like tube sledding and walking skiing.' where id = 'YPsi5c3jC6iiWzN2E-aV-';
update content_bodies set title = '厚田海浜プール4K／北海道の絶景景色', description = '「厚田海浜プール」は、石狩市の国道231号線（オロロンライン）沿いに位置し、2009年にオープンした海水浴場です。札幌中心部から車で約1時間の距離にあり、防波ブロックに囲まれた遠浅の砂浜と穏やかな波が特徴で、小さなお子様でも安心して楽しめます。監視時間内にはライフセーバーが常駐し、180台収容の駐車スペースやトイレ、シャワー、更衣室も完備されています。海水浴だけでなく、デイキャンプやバーベキューも楽しめるため、開設期間中は地元の人々や近郊からの訪問者に人気のスポットです。今年の開設期間は8月21日までで、天候が良ければ夕暮れ時に日本海に沈む美しい夕日を楽しむことができます。' where id = 'qB7dzeZ5crRT9rAqtXf0A';
update content_bodies set title = 'Atsuta Beach Pool 4K / Superb view of Hokkaido', description = 'This video introduces the ''Atsuta Beach Pool'' located along National Route 231 (Ororon Line) in Ishikari City, Hokkaido. Opened in 2009, the beach is about an hour''s drive from central Sapporo and features a shallow sandy beach surrounded by breakwater blocks, making it safe for small children. Lifeguards are present during surveillance hours, and the facility includes parking for 180 cars, as well as toilets, showers, and changing rooms for a comfortable visit. The beach is popular for swimming, day camping, and barbecues, attracting both locals and visitors from nearby areas. The opening period lasts until August 21. At dusk, visitors can enjoy stunning views of the sunset over the Sea of Japan.' where id = 'qww6ygC4W-DwO4GD_lf9s';
update content_bodies set title = '函館山4K／北海道の絶景景色', description = '北海道函館市の西端に位置する「函館山」は、観光地として名高い山です。標高334m、周囲約9kmで、牛が寝そべるような外観から臥牛山とも呼ばれています。山頂まではロープウェイで3分という近さが特徴で、市街地や港を一望できる絶景が楽しめます。夜景だけでなく、昼の眺望も四季ごとに見どころがあります。秋は晴れた日が多く、冬は雪とイルミネーションの競演が楽しめます。春には雲海が広がり、夏には霧の中から幻想的な景色が現れることもあります。現在は函館を代表する観光名所ですが、明治時代から昭和20年までは要塞として利用されていたため、戦争の痕跡も残っています。' where id = '9qb99L67wzF6rf4Mr-Ts6';
update content_bodies set title = 'Mount Hakodate 4K / Superb view of Hokkaido', description = 'Mount Hakodate, located at the western end of Hakodate city in Hokkaido, is a renowned tourist destination. Standing at an altitude of 334m with a circumference of about 9km, it is also known as Gagyuzan due to its cow-like appearance. The mountaintop is easily accessible via a 3-minute ropeway, offering stunning views of the city and harbor. Visitors can enjoy both night and daytime vistas, with each season presenting unique highlights. Autumn offers clear skies for distant views, while winter features beautiful snow and illuminations. Spring brings a sea of clouds, and summer may reveal mystical views through fog. Historically, the site served as a fortress from the Meiji era until 1945, leaving remnants of its military past.' where id = 'ZXKhIddjxBHgF5b9DJXof';
update content_bodies set title = '定山渓ネイチャールミナリエ4K／北海道の絶景景色', description = '定山渓ネイチャールミナリエは、札幌の奥座敷に位置する定山渓温泉の150周年を祝うために2016年から毎年開催されている幻想的なナイトウォークイベントです。今年のテーマは「ウォーターライトバレー」で、水の波紋を踏むと逃げるかっぱの足跡など、子供から大人まで楽しめる仕掛けが用意されています。メインの二見吊橋は自然の中で美しくライトアップされ、別世界にいるような感覚を味わえます。夜の温泉街を浴衣で散策することで、日常の喧騒を忘れることができます。このイベントは定山渓温泉に宿泊した方限定で、6月上旬から10月中旬まで開催され、入場は無料です。' where id = 'XMwmHuj4wQyIIgILacDXZ';
update content_bodies set title = 'Jozankei Nature Luminarie 4K / Superb view of Hokkaido', description = 'The Jozankei Nature Luminarie is a captivating night walk event held annually since 2016, celebrating the 150th anniversary of Jozankei Onsen, located near Sapporo. This year''s theme, ''Water Light Valley,'' features interactive elements like kappa footprints that escape when stepping on water ripples, making it enjoyable for all ages. The main attraction, the Futamitsuri Bridge, is beautifully illuminated, creating a surreal atmosphere. Guests can stroll through the hot spring town in yukata, providing a unique experience away from daily life. The event is exclusive to Jozankei Onsen guests and runs from early June to mid-October, with free admission and accessible facilities.' where id = 'm_Q9W0TDxeA61NQ9b799E';
update content_bodies set title = 'さっぽろ湖・定山渓ダム4K／北海道の絶景景色', description = 'この動画では、北海道の観光スポットである「定山渓ダム」と、そのダムによって作られた「さっぽろ湖」を紹介します。さっぽろ湖は1989年に小樽内川をせき止めてできた湖で、ダム上流には札幌国際スキー場や朝里川温泉を経由して小樽市内へ向かう絶景のドライブコースがあります。季節ごとに変化する風景は特に秋の紅葉時期に美しく、木々のコントラストが魅力的です。また、ダムの直下には「定山渓ダム下流園地」が整備されており、巨大なダムを間近で見ることができます。園内には「定山渓ダム資料館」もあり、開館時間中は堤体内の見学も可能です。' where id = 'a_1-txAq_En4Mr9zCjbEh';
update content_bodies set title = 'Superb view of Hokkaido/ Lake Sapporo / Jozankei Dam', description = 'This video introduces two scenic spots in Hokkaido: Jozankei Dam and Lake Sapporo, which was created in 1989 by damming the Otarunai River. The area offers a stunning drive to Otaru city, passing through Sapporo Kokusai Ski Resort and Asarigawa Onsen. The landscape changes with the seasons, particularly captivating during autumn when the colorful foliage contrasts beautifully. Visitors can enjoy the Jozankei Dam Downstream Garden located directly beneath the dam, providing a close-up view of the massive structure. Additionally, the Jozankei Dam Museum is available for tours during its opening hours, allowing guests to explore the inside of the embankment.' where id = 'ds9WqtShT2dqCxMWzLHKG';
update content_bodies set title = '斜里 オシンコシンの滝4K／北海道の絶景景色', description = 'BEST HOKKAIDOでは、北海道の魅力的な観光スポットや観光資源を紹介しています。今回は、日本の滝100選にも選ばれている斜里町の「オシンコシンの滝」を取り上げます。オシンコシンの滝は、アイヌ語で「エゾマツが群生するところ」を意味し、流れが2つに分かれることから「双美の滝」とも呼ばれています。高さ約30m、落差約80mの滝は、春には雪解け水で水量が増し、冬には凍り付いた美しい姿を見せます。展望台からは「オホーツク海」と「知床連山」を遠望でき、流氷の季節には真っ白な海が広がります。JR釧路本線知床斜里駅からバスで約40分、駐車場や売店、トイレも完備されており、知床を代表する絶景スポットです。' where id = 'VPL4vmIEL4afM838RGSzp';
update content_bodies set title = 'Oshinkoshin Waterfall 4K / Superb View of Hokkaido', description = 'BEST HOKKAIDO showcases attractive sightseeing spots and tourism resources in Hokkaido, presenting the stunning views from various angles. This edition features Oshinkoshin Falls in Shari Town, recognized as one of Japan''s 100 best waterfalls. Located in Shari-cho, Hokkaido, the name Oshinkoshin translates to ''where spruce grows'' in the Ainu language. The waterfall, also known as ''Futami no Taki'' due to its bifurcated flow, has a height of about 30m and a drop of approximately 80m. In spring, the waterfall swells with melting snow, while in winter, it freezes beautifully. An observatory offers views of the Sea of Okhotsk and the Shiretoko Mountain Range, especially stunning during the drift ice season. Accessible by bus from Shiretoko Shari Station and equipped with parking, shops, and restrooms, it is a must-visit scenic spot in Shiretoko.' where id = 'Dc7c3vfPsvR_OomzLqNkQ';
update content_bodies set title = '恵庭渓谷4K／北海道の絶景景色', description = '北海道の恵庭渓谷は、恵庭市街から道道恵庭岳公園線を通り、支笏湖方面に約18㎞進んだ場所に位置する自然の絶景スポットです。ここには「白扇の滝」「三段の滝」「ラルマナイの滝」の3つの滝があり、これらは総称して「恵庭渓谷」と呼ばれています。特に「白扇の滝」は高さ15メートル、幅18メートルで、真っ白な扇のように見えることから名付けられました。「三段の滝」はその名の通り、白い帯が三段に流れ落ちる様子が特徴です。「ラルマナイの滝」はアイヌ語で「急流で滝になっているところ」を意味し、滝見広場の橋からの眺めは圧巻です。これらの滝はどれも迫力があり、特に10月中旬には美しい紅葉も楽しめます。「白扇の滝」と「ラルマナイの滝」には駐車場とトイレも完備されており、ドライブにも最適です。' where id = 'GPXvnf2s-fkSLv-5Njea1';
update content_bodies set title = 'Eniwa Valley 4K / Superb view of Hokkaido', description = 'This video introduces Eniwa Valley, a stunning natural waterfall located about 18 km from Eniwa city on the Eniwadake Koen Line towards Lake Shikotsu. The valley features three waterfalls: Hakusen fall, Sandan fall, and Rarumanai fall. Hakusen fall, the most famous, is 15 meters high and resembles a white fan. Sandan fall flows in three distinct tiers, while Rarumanai fall, meaning ''a waterfall with a rapid stream'' in Ainu, offers breathtaking views from Takimi Square. All three waterfalls provide a magnificent sight, especially with colorful autumn leaves around mid-October. Facilities like parking and restrooms are available at Hakusen and Rarumanai falls, making them ideal for visitors.' where id = 'kcepSaCeC3RN8mHVGe8rm';
update content_bodies set title = '白石こころーど 4K／北海道の絶景景色', description = '「白石こころーど」は、北海道の桜の穴場スポットとして知られるサイクリングロードです。この道は、札幌コンベンションセンターからJR北広島駅まで続いており、1974年8月に旧国鉄千歳線の跡地が自転車と歩行者専用道路として生まれ変わりました。2014年には新しい愛称が募集され、1,750件の応募の中から「白石こころーど」が選ばれました。桜は4月下旬から5月上旬にかけて満開を迎え、散歩やサイクリングを楽しむには最適なスポットです。' where id = 'ihxraNwEfi2P2q1IoymH6';
update content_bodies set title = 'Shiraishi Kokoro-do 4K / Superb view of Hokkaido', description = 'This video introduces ''Shiraishi Kokoro-do'', a cycling road in Hokkaido that is a hidden gem for cherry blossoms. The road stretches from the Sapporo Convention Center to JR Kitahiroshima Station and was transformed from the former JNR Chitose Line into a path for cyclists and pedestrians in August 1974. In 2014, it was renamed ''Shiraishi Kokoro-do'' after a public contest that received 1,750 entries. The cherry blossoms bloom beautifully from late April to early May, making it an ideal location for walking and cycling while enjoying the stunning views.' where id = 's5nhmgYU3bwXreE5hD-co';
update content_bodies set title = '奥尻島鍋釣岩 4K／北海道の絶景景色', description = '今回紹介するのは、奥尻島のシンボル「鍋釣岩」です。この岩は自然に形成され、ドーナツ型で鍋の弦に似ていることから名付けられました。高さは19.5mで、夜間はライトアップされます。頂上には「ヒロハノヘビノボラズ」という木が生えており、トゲのある枝や葉が特徴で、蛇が登れないことからこの名が付けられています。この木は小さな花と赤い実をつけます。島を訪れた際には、ぜひ写真を撮りたいスポットです。また、夜にはイカ釣り漁船の漁火が幻想的な光景を生み出します。駐車場は普通車10台、大型バス3台分があります。' where id = 'fkZ13OawBJ4V1omeah4l8';
update content_bodies set title = 'Okushiri Nabetsuru Rock 4K / Superb view of Hokkaido', description = 'This video introduces ''Nabetsuru Rock,'' a symbol of Okushiri Island, showcasing the stunning scenery of Hokkaido from various angles. The rock, naturally formed and donut-shaped, stands 19.5 meters tall and is illuminated at night. Atop the rock grows a tree known as ''Hirohano Snake Noborazu,'' named for its thorny branches and leaves that prevent snakes from climbing. This tree produces small flowers and red fruits. The site is a must-visit for photography enthusiasts. Additionally, the night view of squid fishing boats creates a magical atmosphere. There is parking available for 10 regular cars and 3 large buses.' where id = 'JHabsr9k7x1rhXJmLedlI';
update content_bodies set title = '大倉山展望台 4K／北海道の絶景景色', description = 'BEST HOKKAIDOでは、北海道の魅力的な観光スポットや観光資源を紹介しています。今回の映像では、北海道の絶景を様々な角度からお届けします。札幌の夜景は「日本新三大夜景」に認定されており、大倉山展望台からの夜景を特集しています。大倉山ジャンプ競技場は1932年に開場し、当初は大倉喜七郎男爵にちなんで「大倉シャンツェ」と名付けられましたが、1972年の冬季オリンピックに向けて改修された際に「大倉山ジャンプ競技場」と改名されました。標高307mのスタート地点からは、札幌市街や石狩平野のパノラマが楽しめ、右手には宮の森ジャンプ競技場も見渡せます。遠くの大通公園の光は飛行機の滑走路のように見え、さっぽろテレビ塔が素敵な夜景を演出しています。また、SNSフォトキャンペーンも開催中で、札幌の夜景写真を投稿すると抽選で素敵な景品が当たるチャンスがあります。' where id = '7NWHMT9ZQ1MJMtlu3FpIz';
update content_bodies set title = 'Okurayama Observatory 4K / Superb view of Hokkaido', description = 'BEST HOKKAIDO introduces the attractive tourist spots and resources of Hokkaido. This video showcases the stunning views of Hokkaido from various angles. Sapporo''s night view has been recognized as one of the ''New Three Major Night Views of Japan.'' This feature highlights the night view from the Okurayama Observatory. The Okurayama Jump Stadium, opened in 1932 and originally named ''Okura Schanze'' after Baron Kishiro Okura, underwent a name change during renovations for the 1972 Winter Olympics. At an altitude of 307m, visitors can enjoy panoramic views of Sapporo city and the Ishikari Plain, including the Miyanomori Jump Stadium. The lights of Odori Park resemble an airplane runway, with the Sapporo TV Tower adding to the beautiful night scenery. Additionally, an SNS Photo Campaign invites participants to post night view photos of Sapporo on social media for a chance to win prizes.' where id = 'SEEme656f2sgFoP1xh-c0';
update content_bodies set title = '札幌もいわ山夜景 4K／北海道の絶景景色', description = 'BEST HOKKAIDOでは、北海道の魅力的な観光スポットや観光資源を紹介しています。今回は、札幌の藻岩山からの夜景を再構成した映像をお届けします。札幌の夜景は「日本新三大夜景」に認定されており、標高531mの藻岩山からは、人口200万の大都市の広がりを一望できる「光の絨毯」を楽しむことができます。多くの観光客がその美しさに感動しています。詳しくは、リンクをご覧ください。' where id = '3s5roBgCHply15keVfe3t';
update content_bodies set title = 'Superb view of Hokkaido/Mt. Moiwa Observatory', description = 'BEST HOKKAIDO introduces the attractive tourist spots and resources of Hokkaido. This video showcases the breathtaking night view from Mt. Moiwa in Sapporo, reconstructed using previously unshown footage. Sapporo''s night view has been recognized as one of the ''New Three Major Night Views of Japan,'' offering a stunning panorama from an altitude of 531 meters. Visitors can enjoy a ''carpet of light'' that reveals the sprawling cityscape of a metropolis with a population of 2 million, leaving many tourists in awe. For more information, visit the provided link.' where id = '2wMxpKvR_r7DXXeVtH62m';
update content_bodies set title = '浦幌町 昆布刈石海岸 - 北海道の絶景', description = 'この動画では、北海道浦幌町にある美しい昆布刈石海岸を紹介します。昆布刈石展望台からは、約90mの崖の上から太平洋の絶景を楽しむことができます。帯広市の南東に位置し、近くには黄金の滝やジュエリーアイスで有名な大津海岸があります。この動画では、北海道の風景の美しさを様々な角度から映し出し、観光地としての魅力を強調しています。' where id = 'NBCfhmMpK-6X9vXy9ejak';
update content_bodies set title = 'Kobukariishi Coast in Urahoro Town - Superb View of Hokkaido', description = 'This video introduces the stunning Kobukariishi Beach located in Urahoro Town, Hokkaido. The Kobukariishi Observatory offers breathtaking views of the Pacific Ocean from a cliff approximately 90 meters high. Situated southeast of Obihiro City, this scenic spot is close to the Otsu coast, known for its golden waterfall and jewelry ice. The video showcases the beauty of Hokkaido''s landscapes from various angles, highlighting its appeal as a tourist destination.' where id = 'UKH2oMAGJLxjJoaHTQMQn';
update content_bodies set title = '小樽ゆき物語 4K／北海道の絶景景色', description = '北海道の観光スポットや資源を紹介するBEST HOKKAIDOでは、今回は小樽で開催されている「小樽ゆき物語」を取り上げます。このイベントは「小樽・余市ゆき物語」とも呼ばれ、さまざまな街並みが工夫を凝らしたイルミネーションで美しくライトアップされます。イルミネーションの青と空の蒼が相まって、幻想的な小樽運河の景色を楽しむことができます。詳細はリンクをご覧ください。' where id = 'Rkjt3M3WHPVyWvtCvT98B';
update content_bodies set title = 'Otaru Yuki Monogatari 4K / Superb view of Hokkaido/Otaru Canal', description = 'BEST HOKKAIDO introduces the attractive tourist spots and resources of Hokkaido. This time, we present the ''Otaru Yuki Monogatari'' event held in Otaru, also known as ''Otaru/Yoichi Yuki Monogatari.'' This event features beautifully illuminated cityscapes, creating a magical atmosphere. The blue lights of the illuminations blend with the blue sky, offering a fantastic view of the Otaru Canal. For more information, visit the provided link.' where id = 'P0LkrFTRdt21ULq0CU4Ij';
update content_bodies set title = '円山公園のエゾリス 4K／北海道の絶景景色 【BESTHOKKAIDO_VOL.81】', description = '北海道の観光スポットや資源を紹介する「BEST HOKKAIDO」では、札幌にある「円山公園」を取り上げます。円山原始林の北側に位置するこの公園は、北海道神宮境内とともに古くから桜の名所として知られ、市民に親しまれています。円山公園には多くのエゾリスが生息しており、冬の寒さをしのぐために園内を活発に動き回っています。' where id = 'PphYBHfgjfSZj4r9f1P_j';
update content_bodies set title = 'Superb view of Hokkaido/Maruyama Park', description = 'BEST HOKKAIDO introduces the attractive tourist spots and resources of Hokkaido. This time, we will showcase Maruyama Park in Sapporo. Located on the north side of the Maruyama Primeval Forest, Maruyama Park is a historic cherry blossom viewing spot, cherished by locals, and adjacent to the Hokkaido Jingu Shrine. The park is home to many squirrels, known as Ezo squirrels, which can be seen moving around to survive the cold winter.' where id = 'HYfSK4dRE4Ib3lpYLXgDp';
update content_bodies set title = '上ノ国町 神の道 4K／北海道の絶景景色', description = '「BEST HOKKAIDO」では、北海道の魅力的な観光スポットや観光資源を紹介し、絶景を様々な角度から映像でお届けします。今回は、上ノ国町にある「神の道」を取り上げます。この町は中世からの歴史を持ち、多くの伝説が伝わっています。特に神の道では、夜になると不思議な灯が上がり、夷王山を経て八幡野を越え、大平山へと消えていくとされています。村人たちは、海の神竜神が大平山の山祇神のところへ竜灯として通ったと信じていました。' where id = 'CbVtNx_thOIEgubKmVXHQ';
update content_bodies set title = 'Kaminokuni Town Kan no Michi 4K / Superb view of Hokkaido', description = 'BEST HOKKAIDO introduces the attractive tourist spots and resources of Hokkaido, showcasing the stunning scenery from various angles. This episode features ''Kan no Michi'' in Kaminokuni Town, a place rich in legends dating back to the Middle Ages. It is said that a mysterious light rises from this path at night, traveling through Mt. Iozan, crossing Yawatano, and disappearing into Mt. Ohira. Villagers believed that the sea dragon god traveled to the mountain god of Mt. Taihei as a dragon lantern.' where id = '0ZeLvWDxpQlk3Ta3WlVkI';
update content_bodies set title = 'もいわ山 山頂展望台クリスマスツリー', description = '今回は、札幌にある「もいわ山ロープウェイの山頂展望台クリスマスツリー」を紹介します。2021年12月23日にロープウェイがリニューアルされて10周年を記念し、1週間限定でクリスマスツリーと山頂展望台が公開されます。特に、15時から16時の間に見られる「マジックアワー」は、柔らかく温かい金色の光が特徴で、撮影に最適です。山頂展望台にある「幸せの鐘」がクリスマスツリーに変身し、16時以降は様々な色にライトアップされます。この機会にぜひ訪れてみてはいかがでしょうか。' where id = 'FlIB84GxcjXI_zSpwblH7';
update content_bodies set title = 'Mt. Moiwa Ropeway Mountaintop Observatory Christmas Tree', description = 'This video introduces the ''Mt. Moiwa Ropeway Mountaintop Observatory Christmas Tree'' in Sapporo, celebrating the 10th anniversary of the ropeway''s renewal on December 23, 2021. The Christmas tree and observatory are open for a limited time of one week, showcasing the beautiful ''magic hour'' between 15:00 and 16:00. This period, known for its soft and warm golden light, is ideal for photography. The ''bell of happiness'' at the observatory is transformed into a Christmas tree, and after 16:00, it is illuminated with various colors. Visitors are encouraged to take this opportunity to experience the festive atmosphere.' where id = 'rlhypOJA634KmdBqU5fCw';
update content_bodies set title = '函館 大船遺跡（縄文）4K／北海道の絶景景色', description = 'この動画では、函館市にある大船遺跡を紹介します。この遺跡は、縄文時代前期後半から中期後半にかけての大規模な集落遺跡であり、2021年には「北海道・北東北の縄文遺跡群」として世界文化遺産に登録されました。遺跡の周辺には、当時の環境を再現した「縄文の森」、竪穴住居や盛土遺構を復元した「縄文のにわ」、南茅部地域の縄文遺跡に関するパネルを展示した「管理棟」が整備されています。詳細については、提供されたリンクをご覧ください。' where id = 'TC20pR5UZSsqB6od06lWe';
update content_bodies set title = 'Ofune Site in Hakodate (Jomon) 4K / Superb View of Hokkaido', description = 'This video introduces the Ofune Site, a significant Jomon period archaeological site located in Hakodate City, Hokkaido. The site represents a large settlement from the latter half of the early to the middle Jomon period and was registered as a World Cultural Heritage site in 2021 as part of the ''Hokkaido/Northeastern Jomon Sites.'' Surrounding the ruins are several reconstructed areas, including ''Jomon no Mori,'' which recreates the environment of that era, ''Jomon no Niwa,'' featuring restored pit houses and embankment remains, and an administrative building displaying panels related to Jomon archaeological sites in the Minamikayabe area. For more details, visit the provided links.' where id = 'sEjIusAxLafBXVbaWIeVT';
update content_bodies set title = '奥尻島 宮津弁天宮4K／北海道の絶景景色', description = '今回は、奥尻島の「宮津弁天宮」を紹介します。この神社は中津島神社とも呼ばれ、島のように見える岩の上に位置しています。昔は、北海道本土との連絡拠点として利用されていました。神社には広島の厳島神社から移された宗像三女神が祀られ、1841年に現在の澳津神社となりました。この岩山には、9世紀のオホーツク文化の遺跡や、16～17世紀のアイヌの砦が存在したと考えられています。本殿は1918年、1970年、1999年に改築され、島内最古の神社祭祀の場所として町指定有形文化財に認定されています。' where id = 'eQQYqIiLS24w4FoQCjaXy';
update content_bodies set title = 'Okushiri Island Miyatsubentengu 4K / Superb view of Hokkaido', description = 'This video introduces ''Miyatsubentengu'' on Okushiri Island, also known as Nakatsushima Shrine, which is situated high on a rock mass resembling an island. Historically, it served as a lookout and contact point with the Hokkaido mainland. The shrine enshrines the Three Goddesses of Munakata, moved from Itsukushima Shrine in Hiroshima in 1841. The area has historical significance, with ruins from the Okhotsk culture and Ainu fortifications dating back to the 9th and 16th-17th centuries, respectively. The main shrine has undergone several reconstructions, with the latest in 1999, and is recognized as a tangible cultural property due to its historical and scenic importance.' where id = '4_qwCPLJEcU_ioaO7_MDO';
update content_bodies set title = '大沼国定公園4K／北海道の絶景景色', description = '今回は、七飯町にある「大沼国定公園」を紹介します。大沼公園駅から徒歩5分の場所に位置し、森に囲まれた大沼、小沼、蓴菜沼には100以上の小島が浮かんでいます。手漕ぎボートでのんびりと水上散歩を楽しんだり、レンタサイクルで湖畔を巡ることができます。湖上テラスで自然を満喫することもでき、四季折々の花や鳥を楽しむことが特徴です。特に秋には、大沼公園駅前の街路樹が美しい黄色に染まり、駒ケ岳を望む「湖月橋」は絶好の紅葉スポットです。沼に浮かぶ小島を結ぶ散策路も整備されています。' where id = 'HXWP12yvcxM4wA4UUIH2g';
update content_bodies set title = 'Onuma Quasi-National Park 4K / Superb view of Hokkaido', description = 'This video introduces Onuma Quasi-National Park located in Nanae Town, Hokkaido. Just a 5-minute walk from Onuma Koen Station, the park features over 100 small islands surrounded by forests in Onuma, Onuma, and Watershield. Visitors can enjoy leisurely water walks by rowing boat or rent bicycles to explore the lakeside roads. The park offers various activities, including relaxing on the lake terrace and enjoying nature throughout the four seasons. Autumn is particularly beautiful, with the trees in front of Onuma Koen Station turning vibrant yellow. Kogetsu Bridge, overlooking Mt. Komagatake, is an ideal spot for viewing autumn leaves, and there are walking paths connecting the islets in the swamp.' where id = '_PJIFx00iFDGGOC63BVMe';
update content_bodies set title = '北斗のパノラマ展望 きじひき高原4K／北海道の絶景景色', description = '「BEST HOKKAIDO」では、北海道の魅力的な観光スポットを紹介しています。今回は北斗市の「きじひき高原」を取り上げます。新函館北斗駅から車で約15分の場所に位置し、標高560mの展望台からは津軽海峡や函館山、大沼、駒ヶ岳などの絶景を一望できます。また、大野平野に半径3,000mの巨大な弧を描く北海道新幹線の高架橋も見ることができます。屋内で景観を楽しむことができる展望施設もあり、タイミングが合えば雲海を眺望することも可能です。' where id = 'VP0og1tgyIebX3RAcvwR2';
update content_bodies set title = 'Superb view of Hokkaido/Kijihiki Plateau', description = 'This article introduces ''Kijihiki Kogen'' in Hokuto City, a stunning tourist spot in Hokkaido. Located about a 15-minute drive from Shin-Hakodate Hokuto Station, the panoramic observatory at an altitude of 560 meters offers breathtaking views of the Tsugaru Strait, Mt. Hakodate, Onuma, and Mt. Komagatake. Visitors can also see the impressive viaduct of the Hokkaido Shinkansen, which forms a massive arc with a radius of 3,000 meters in the Ono Plain. The observatory facility allows guests to enjoy the scenery indoors, and if conditions are right, they may witness a beautiful sea of clouds.' where id = 'mid2t978exdC8byD5xiIL';
update content_bodies set title = '知内町青い洞窟ボートクルーズ（道南の秘境）4K／北海道の絶景景色', description = '北海道の観光スポット「青い洞窟ボートクルーズ」を紹介します。函館市から車で約80分の場所に位置するこの青い洞窟は、ダイナミックな断崖絶壁と透明度の高い青い海が広がる「道南の秘境」として知られています。矢越海岸の自然や神秘的な青い世界を体験してみませんか？このクルーズは知内町の854CRUISE（矢越クルーズ）によって運営されています。' where id = '0-twAMPi3C139bPtwwW4z';
update content_bodies set title = 'Blue Cave Boat Cruise in Shiriuchi Town (Hidden Gem of Southern Hokkaido) 4K / Superb View of Hokkaido', description = 'This video introduces the ''Blue Cave Boat Cruise'' in Shiriuchi Town, a stunning tourist spot in Hokkaido. Located about 80 minutes by car from Hakodate city, the blue cave is known as an ''unexplored region of southern Hokkaido,'' featuring dynamic cliffs and a highly transparent blue sea. Experience the natural beauty of the Yagoshi coast and the mysterious blue world. The cruise is operated by 854 CRUISE (Yakoshi Cruise) in Shiriuchi Town.' where id = 'CdqMzRo5NuPxgX0c3M32u';
update content_bodies set title = '芽室町 新嵐山スカイパーク展望台4K／北海道の絶景景色', description = '北海道の観光スポットや資源を紹介するBEST HOKKAIDOでは、今回は芽室町の「新嵐山スカイパーク展望台」を取り上げます。この展望台からは、十勝平野の雄大な景色を360度パノラマで楽しむことができ、パッチワークのような田園風景や耕地防風林など、のどかな農村の風景が広がります。また、奥には大雪山、十勝連山、日高山脈が見え、夜には満天の星空を楽しむことができます。' where id = 'cHUV6aXZAgOOTJo6xXgyI';
update content_bodies set title = 'New Arashiyama Sky Park Observatory 4K / Superb view of Hokkaido', description = 'BEST HOKKAIDO introduces attractive tourist spots and resources in Hokkaido. This time, we present the ''New Arashiyama Sky Park Observatory'' in Memuro Town. Visitors can enjoy a 360-degree panoramic view of the magnificent Tokachi Plain, featuring idyllic rural landscapes that resemble a patchwork quilt and cultivated windbreaks. In the background, the Daisetsu, Tokachi, and Hidaka mountain ranges can be seen, and at night, the observatory offers a stunning view of the starry sky.' where id = 'gmwbcIw6-ga-0Ix4SmToB';
update content_bodies set title = '新篠津村 しのつ公園キャンプ場4K／北海道の絶景景色', description = '今回紹介するのは、新篠津村の「しのつ公園」です。この公園は、キャンプ場や夏に楽しめるしのつ湖、展望台、ちびっこ広場、水遊び、貸し自転車、産直市場、道の駅、温泉などがあり、新篠津村を代表するスポットです。しのつ公園キャンプ場では、200張のテントサイト、炊事場、バーベキューコーナーがあり、5月上旬から10月下旬まで利用可能です。天気の良い週末でも広い敷地のため、テントが多くても狭さを感じません。また、テントや寝袋などのキャンプ用品のレンタルもあり、手ぶらでのキャンプも楽しめます。しのつ湖では、無料の貸し自転車やボート、ウォーターダッシュ、四輪バギー体験、釣りが楽しめます。新型コロナウイルスの影響で営業内容が異なる場合があるため、事前に確認が必要です。' where id = 'IT8mItfinl5dY7PXpSO7e';
update content_bodies set title = 'Shinotsu Park Campground 4K / Superb View of Hokkaido', description = 'This video introduces Shinotsu Park in Shinshinotsu Village, a representative site of the area. The park features a campground, Shinotsu Lake for summer activities like boat rentals and fishing, an observatory, a children''s play area, water play, rental bicycles, a direct market, a roadside station, and a hot spring. The campground offers 200 tent sites, kitchen facilities, and barbecue areas available from early May to late October. Despite many tents on busy weekends, the spacious area ensures comfort. Various camping gear rentals are available, allowing for easy camping without prior preparation. Shinotsu Lake, an oxbow lake along the Ishikari River, offers free bicycle rentals, boat rentals, water dash, four-wheel buggy experiences, amphibious vehicle experiences, and fishing. Note that business operations may vary due to COVID-19, so please check in advance.' where id = 'ioK2L2JtkdG2vV4Xg4hUI';
update content_bodies set title = '食べて、つくって、触れ合える！まるで“食”のテーマパーク🍖✨', description = '牛の乳しぼりやウインナー作りなど、食に関する体験ができるテーマパークです。毎日開催されるイベントや体験教室は大人から子どもまで楽しめる内容で、大人気です。園内にはカフェやレストランもあり、素材にこだわった美味しいメニューを楽しむことができます。この夏のおすすめスポットは「モクモクファーム」で、一日中楽しむことができます。三重県伊賀市に位置し、営業時間は10:00から16:30まで。入園料は600円で、駐車場も完備されています。詳細は「観光三重」をご覧ください。' where id = 'dPjvuQ9oRAGS8c38ID1mY';
update content_bodies set title = 'A Theme Park of Food: Eat, Make, and Interact! 🍖✨', description = 'Experience a food-themed park where you can enjoy activities like milking cows and making sausages. Daily events and workshops cater to both adults and children, making it a popular destination. The park also features cafes and restaurants offering delicious menus focused on quality ingredients. This summer, Mokumoku Farm is the perfect place for a full day of fun. Located in Iga, Mie Prefecture, the farm operates from 10:00 AM to 4:30 PM, with various facilities available. Admission is 600 yen, and parking is provided. For more details, visit ''Kankou Mie''.' where id = '3fDR44y2wguLRQtdPahUb';
update content_bodies set title = '津ぎょうざプロモーション動画（三重県津市）', description = '三重県津市のB級グルメ「津ぎょうざ」を紹介するプロモーション動画です。この動画は、三重県観光キャンペーンの中南勢地域部会によって制作されました。津ぎょうざは地域の特産品として知られ、観光客にその魅力を伝えることを目的としています。' where id = 'xljXO1W5GRCWbXONbX612';
update content_bodies set title = 'Tsu Gyoza Promotion Video (Tsu City, Mie Prefecture)', description = 'This is a promotional video for ''Tsu Gyoza,'' a B-class gourmet dish from Tsu City in Mie Prefecture. The video was created by the Nansei Regional Committee as part of the Mie Prefecture tourism campaign.' where id = 'UaCG2sysqDXeh2OkMXW3g';
update content_bodies set title = '三陸ジオパークVRムービー（六観堂洞窟）', description = '岩手県住田町に位置する六観堂洞窟は、美しい石灰岩の造形で知られています。この洞窟は、その自然の美しさから訪れる人々を魅了しており、三陸ジオパークの一部としてVRムービーで紹介されています。' where id = 'aYNSiufRTgVVbWKrWPWjd';
update content_bodies set title = 'Sanriku Geopark VR Movie (Rokando Cave)', description = 'The Sanriku Geopark VR Movie showcases the Rokando Cave located in Sumita Town, Iwate Prefecture. This cave is renowned for its stunning limestone formations, which are beautifully modeled and attract visitors for their natural beauty.' where id = 'Iqnp86ZNP2wbhR1Ixzjgb';
update content_bodies set title = '豊頃町 はるにれの木4K／北海道の絶景景色', description = '北海道の観光スポットや資源を紹介するBEST HOKKAIDOでは、今回は豊頃町にある大樹「はるにれの木」を取り上げます。この樹齢150年の大樹は、季節や時間によってその表情を変えます。実は、2本の木が一体化して現在の形になった珍しい木で、風の日も雨の日も決して離れず寄り添ってきた様子は、まるで永遠の愛を誓い合った恋人のようです。春夏秋冬それぞれの表情を見せるこの場所は、撮影スポットとしても人気があります。' where id = 'JIEP_TOD7RDQE5m7rgfwH';
update content_bodies set title = 'Toyokoro Harunire Tree 4K / Superb view of Hokkaido', description = 'BEST HOKKAIDO introduces the attractive tourist spots and resources of Hokkaido. This time, we focus on the magnificent ''Harunire no Ki'' in Toyokoro Town. This large tree, estimated to be 150 years old, changes its appearance with the seasons and time. Uniquely, it consists of two trees that have merged into one, symbolizing eternal love as they have never separated through wind and weather. It is a popular photography spot, showcasing different expressions throughout spring, summer, autumn, and winter.' where id = 'Bw6mWoBL0G4gxxrOrBgxt';
update content_bodies set title = '札幌 幌見峠ラベンダー園 4K／北海道の絶景景色', description = '「BEST HOKKAIDO」では、北海道の魅力的な観光スポットや観光資源を紹介しています。今回は、札幌にある「幌見峠ラベンダー園」を取り上げ、5000株のラベンダーが咲く様子をお届けします。この園は、さっぽろテレビ塔やJRタワーなどの高層建築物が近くにあり、藻岩山よりも標高が低く市街地に近いため、ダイナミックな景観を楽しむことができます。ラベンダー園は7月中旬から8月上旬まで営業しており、一面に咲くラベンダーの花を楽しむことができるため、日中のドライブに訪れるのもおすすめです。' where id = 'yjhl24WDRs1QrTqxeU1Bn';
update content_bodies set title = 'Sapporo Horomi Pass Lavender Garden 4K / Superb view of Hokkaido', description = 'BEST HOKKAIDO introduces attractive tourist spots and resources in Hokkaido. This time, we present the ''Horomi Pass Lavender Garden'' in Sapporo, where 5,000 lavender plants bloom. The garden offers close views of Sapporo''s high-rise buildings, including the Sapporo TV Tower and JR Tower. Its lower altitude compared to Mt. Moiwa and proximity to the city allow for a dynamic landscape experience. The garden is open from mid-July to early August, showcasing a stunning display of blooming lavender flowers, making it a recommended destination for daytime drives.' where id = 'R_ZoJGC637T9LRX-1LwIy';
update content_bodies set title = '札幌百合が原公園 4K／北海道の絶景景色', description = 'BEST HOKKAIDOでは、北海道の魅力的な観光スポットや観光資源を紹介しています。今回の映像では、札幌市北区に位置する百合が原公園の絶景を様々な角度からお届けします。この公園は約100種類のユリやライラックが咲き誇る自然公園で、札幌市民にも人気のスポットです。敷地面積は25.3ヘクタールで、東京ドーム約5.4個分、札幌ドーム約4.6個分に相当します。園内には「世界の百合広場」や、札幌の姉妹都市である中国の瀋陽、ドイツのミュンヘン、アメリカのポートランドの庭園、そしてアジサイや耐陰性宿根草を中心としたボーダーガーデンなど、約13のエリアで花々を楽しむことができます。' where id = '9yABpF_IcJympsMcpcoc9';
update content_bodies set title = 'Sapporo Yurigahara Park 4K / Superb view of Hokkaido', description = 'BEST HOKKAIDO introduces the attractive tourist spots and resources of Hokkaido. This video showcases the superb views of Hokkaido from various angles. Yurigahara Park, located in the Kita Ward of Sapporo, is a natural park where about 100 kinds of lilies and lilacs bloom beautifully, making it a popular spot for local residents. The park covers an area of 25.3 hectares, equivalent to about 5.4 Tokyo Domes or 4.6 Sapporo Domes. Visitors can enjoy flowers in approximately 13 areas, including ''Yuri Square in the World,'' which cultivates around 100 types of lilies, and the ''Garden of the World,'' featuring traditional Japanese gardens alongside those from Sapporo''s sister cities: Shenyang, Munich, and Portland.' where id = 'hbxBHMnuyL_LXvB4TeM8C';
update content_bodies set title = '白旗山 いろはすの水源地 4K／北海道の絶景景色', description = 'この動画では、北海道の絶景を紹介し、札幌市清田区に位置する白旗山に焦点を当てています。ミネラルウォーターのいろはすは、白旗山の地下水を水源としており、山の中でも湧き水を見ることができます。登山ルートは複数あり、傾斜が緩やかなので初心者でも気軽に登ることができます。登山口の横には芝生の広場とトイレがあり、広場の奥にはバーベキュー場もあります。週末は賑わうようです。新型コロナウイルス感染症の影響で変更がある場合があるため、事前に確認することをお勧めします。' where id = 'x_Ug3fAnsbGvxqf8Jx2LO';
update content_bodies set title = 'Shirahata-yama: Source of I Lohas Water - 4K / Superb View of Hokkaido', description = 'This video showcases the stunning landscapes of Hokkaido, focusing on Mt. Shirahata located in Kiyota Ward, Sapporo City. The mineral water brand I Lohas sources its water from the groundwater of Mt. Shirahata, where visitors can also find natural spring water. The mountain offers several climbing routes with gentle slopes, making it accessible for beginners. Facilities at the trailhead include a lawn area and restrooms, along with a barbecue spot that is popular on weekends. Note that changes may occur due to the impact of the COVID-19 pandemic, so it''s advisable to check in advance.' where id = 'L835PVeziXMfNeVH-sZlR';
update content_bodies set title = '当別町 菜の花畑 4K／北海道の絶景景色', description = '北海道の魅力的な観光スポットや観光資源を紹介するBEST HOKKAIDO。今回は、当別町の菜の花畑を取り上げます。町の東裏地区では、菜種油用の菜の花が満開に咲き誇り、道道沿いには黄色い花がじゅうたんのように広がっています。菜の花は5月中旬から咲き始め、6月上旬までが見ごろです。この季節には、北海道内のさまざまな場所で美しい花畑が楽しめます。' where id = 'kGYfA3pBEkHyYa1stFgFf';
update content_bodies set title = 'Tobetsu Town Canola Flower Field 4K / Superb View of Hokkaido', description = 'BEST HOKKAIDO introduces the attractive tourist spots and resources of Hokkaido. This video showcases the stunning scenery of Hokkaido from various angles. In this episode, we focus on the canola flower field in Tobetsu Town, where rapeseed flowers bloom beautifully in the Higashiura district. The yellow flowers spread like a carpet along the roadside. The blooming season starts in mid-May and lasts until early June, offering beautiful flower fields across various locations in Hokkaido during this time.' where id = 'WpILgUQvUbYPZZav0bXDc';
update content_bodies set title = '札幌 川下公園ライラックの森4K', description = 'BEST HOKKAIDOでは、北海道の魅力的な観光スポットや観光資源を紹介し、様々な角度から絶景をお届けします。今回は札幌の川下公園にあるライラックの森を紹介します。5月中旬から7月上旬までの約1ヶ月半の間に、約200種類のライラックの花が見られ、日本最後のライラックも保存されています。公園では原種を含む様々なライラックが分かりやすく紹介されていますが、新型コロナウイルスの影響で一部の利用が休止されています。毎年開催されるライラック祭りは2021年にオンラインで行われ、ライラックの森のガイドツアー動画も公開されています。' where id = 'oS8il_KwBHooKouGXE3bO';
update content_bodies set title = 'Superb view of Hokkaido/Sapporo Kawashimo Park Lilac', description = 'BEST HOKKAIDO showcases attractive sightseeing spots and tourism resources in Hokkaido, presenting stunning views from various angles. This edition features the lilac forest in Kawashimo Park, Sapporo, where around 200 types of lilac flowers bloom from mid-May to early July. Notably, the last lilac in Japan is preserved here. The park offers an easy-to-understand introduction to various lilac species, although some areas are closed due to the impact of COVID-19. The annual Lilac Festival, typically held by Sapporo City, was conducted online in 2021, and a guided tour video of the lilac forest is available for viewing.' where id = 'MNX4MzXiRnmmrlLzpGpuJ';
update content_bodies set title = '札幌 春の豊平川4K／北海道の絶景景色 【BESTHOKKAIDO_VOL.65】', description = '北海道の観光スポットや資源を紹介するBEST HOKKAIDOでは、北海道の絶景を様々な角度から映像でお届けします。今回は札幌の母なる川、豊平川を紹介します。この川は石狩川の支流であり、札幌市の市街地はこの川が形成した扇状地の上に存在しています。豊平川は現在の札幌を形成する上で重要な役割を果たしました。市内の河川敷は市民の憩いの場となっており、ジンギスカンやバーベキューを楽しむことができ、パークゴルフ場も整備されています。ただし、2021年5月現在、コロナウイルスの影響で火器の使用はできません。' where id = 'uOQjw8JGeD-Yd5qf7f3Rf';
update content_bodies set title = 'Superb view of Hokkaido/Sapporo Toyohira River in spring', description = 'BEST HOKKAIDO introduces the attractive tourist spots and resources of Hokkaido. This video showcases the stunning scenery of Hokkaido from various angles. This time, we focus on the Toyohira River, known as the mother river of Sapporo. It is a first-class river that is a tributary of the Ishikari River, flowing through Sapporo City. The city is situated on the alluvial fan formed by this river, which has played a significant role in shaping modern Sapporo. The riverbed serves as a relaxation area for citizens, where they can enjoy Genghis Khan and barbecues, as well as park golf courses. (As of May 2021, the use of firearms is prohibited due to the coronavirus.)' where id = '7b6r9LbwjSmDaIBypIdq8';
update content_bodies set title = '札幌手稲 軽川緑地の桜4K／北海道の絶景景色 【BESTHOKKAIDO_VOL.64】', description = 'BEST HOKKAIDOでは、北海道の魅力的な観光スポットや観光資源を紹介しています。今回は札幌市手稲区にある軽川緑地に焦点を当て、2021年の桜の様子をお届けします。軽川は新川水系の支流で、春には川沿いに満開の桜が咲き誇り、道内有数の桜の名所として知られています。約300本のエゾヤマザクラとチシマザクラが植えられ、こどもの日には軽川に鯉のぼりが掛けられます。' where id = 'bAK8DEN_dmiQ-GecKMqQ1';
update content_bodies set title = 'Superb view of Hokkaido/Sapporo Garugawa Ryokuchi Sakura', description = 'BEST HOKKAIDO introduces attractive tourist spots and resources in Hokkaido. This time, we focus on Garugawa Ryokuchi in Teine Ward, Sapporo, showcasing the cherry blossoms of 2021. The Kei River, a second-class tributary of the Shinkawa River, flows through Teine Ward. In spring, the cherry blossoms bloom magnificently along the river, making it one of Hokkaido''s most scenic locations, known as Garugawa Sakura Zutsumi. Approximately 300 Ezoyama and Chishima cherry trees are planted here, and on Children''s Day, carp streamers are hung along the river.' where id = 'C6vhccbUYo7l3K7k49dan';
update content_bodies set title = '旭川買物公園4K／北海道の絶景景色', description = '「BEST HOKKAIDO」では、北海道の魅力的な観光スポットや観光資源を紹介し、絶景を様々な角度から映像でお届けします。今回は旭川市中心部にある「買物公園」を紹介します。この公園は旭川駅前から8条通までの1kmにわたる歩行者天国で、1972年に日本初の恒久的歩行者天国として開設されました。商業の中心地として多くの客を集め、毎年2月には旭川冬まつりの一環として「国際氷彫刻コンテスト」が開催されます。また、9月には食べマルシェの主会場としても利用されています。旧旭川偕行社や旭橋とともに、旭川八景の一つとしても知られています。' where id = 'sPRZ3dskJvkdNXBO-juW6';
update content_bodies set title = 'Asahikawa Shopping Park 4K / Superb View of Hokkaido', description = 'BEST HOKKAIDO introduces the attractive tourist spots and resources of Hokkaido, showcasing its stunning scenery from various angles. This edition features the ''Shopping Park'' located in the center of Asahikawa city. Stretching 1 km from Asahikawa Station to 8 Jodori, it was established in 1972 as Japan''s first permanent pedestrian paradise. The area serves as a commercial hub, attracting many visitors, and hosts events such as the ''International Ice Sculpture Contest'' during the Asahikawa Winter Festival in February. Additionally, it is the main venue for the Eating Marche in September. The park is recognized as one of the eight scenic views of Asahikawa, alongside the former Asahikawa Museum of Commerce and Asahibashi.' where id = 'T1IBmxBdktYbb8iJUS4LF';
update content_bodies set title = '石狩湾・オロロンライン 春編4K／北海道の絶景景色', description = '今回の動画では、石狩市に位置する日本海に面した「石狩湾」を紹介します。この湾は北海道中西部にあり、小樽市や石狩市と接しています。札幌圏と各地を結ぶ海上物流の拠点として機能しており、湾の内側には広い砂浜が広がり、多くの海水浴場があります。また、増毛に向かう道であるオロロンラインは、美しい夕日が見えるスポットとして人気です。冬にはオオワシやキタキツネなどの野生動物も観察できます。' where id = 'l1bZf86eQ54cV0dRbZxeP';
update content_bodies set title = 'Ishikari Bay and Oloron Line Spring Edition 4K / Superb View of Hokkaido', description = 'This video introduces Ishikari Bay, located in Ishikari City, facing the Sea of Japan. The bay is part of Hokkaido''s Midwestern region, connecting Otaru City and Ishikari City. It serves as a marine logistics hub linking the Sapporo area with other locations. The inner coast features expansive sandy beaches, making it a popular destination for beachgoers. The Oloron Line, leading towards Mashike, is renowned for its stunning sunset views. In winter, visitors can spot wildlife such as Steller''s sea eagles and red foxes.' where id = 'ZvbeClDLoFn9o-bcPNNFU';
update content_bodies set title = '当別ふくろう湖 冬編4K／北海道の絶景景色', description = '今回紹介するのは、北海道当別町にある「当別ふくろう湖」です。このダム湖は2012年に完成し、町民の公募により、町のシンボルであるふくろうにちなんで名付けられました。豊かな自然に囲まれ、バードウォッチングや紅葉を楽しむ穴場スポットです。冬には湖が凍り、一面の雪景色が広がります。また、山から吹き降ろされる風によって雪埃が舞う現象も見ることができます。春夏秋冬、それぞれの季節に異なる顔を持ち、訪れる人々を楽しませてくれます。' where id = '7kWp3qjT0_6YyoOFBlsZe';
update content_bodies set title = 'Tobetsu Owl Lake Winter Edition 4K / Superb View of Hokkaido', description = 'This video introduces ''Tobetsu Owl Lake'' located in Tobetsu Town, Hokkaido. Completed in 2012, the dam lake was named after the owl, the town''s symbol, through a public naming contest. Surrounded by rich nature, it is a hidden gem for bird watching and enjoying autumn leaves. In winter, the lake freezes, offering a vast snowy landscape, while the phenomenon of snow dust dancing in the wind can also be observed. Each season brings its own unique beauty, making it a delightful destination year-round.' where id = '8y0z0fgXMDJ5I81W8Z0EF';
update content_bodies set title = '虎杖浜 冬編4K／北海道の絶景景色', description = '北海道の観光スポットや資源を紹介する「BEST HOKKAIDO」では、絶景を様々な角度から映像でお届けします。今回は白老町の「虎杖浜」を取り上げ、虎杖浜温泉やタラコの加工業者が集まる地域として知られています。10月から翌年2月にかけて漁獲されるスケトウダラの卵巣を塩蔵加工した国産タラコを出荷しており、虎杖浜産の「虎杖浜たらこ」は高品質で地域ブランド化された水産加工品として流通しています。' where id = 'kMJfp8KLRH23btPtjrldp';
update content_bodies set title = 'Kojohama Winter Edition 4K / Superb View of Hokkaido', description = 'This video introduces the attractions and resources of Hokkaido, showcasing its stunning scenery from various angles. This episode features ''Kojohama'' in Shiraoi Town, known for Kojohama Onsen and its cod roe processing industry. The area is recognized as a cod roe producing region, shipping domestically produced salted ovaries of Alaska pollack caught from October to February. The ''Kojohama cod roe'' is of high quality and is marketed as a locally branded marine product.' where id = 'M97383dMPHhplga0dRCf4';
update content_bodies set title = '地獄谷 冬編4K／北海道の絶景景色', description = '「BEST HOKKAIDO」では、北海道の魅力的な観光スポットや観光資源を紹介しています。今回は、登別温泉にある「地獄谷」を取り上げ、北海道の絶景を様々な角度から映像でお届けします。地獄谷は日和山の噴火活動によって形成された爆裂火口跡で、直径約450m、面積約11haの広さを持ちます。谷には多くの湧出口や噴気孔があり、泡立ち煮えたぎる風景が「鬼の棲む地獄」という名前の由来となっています。また、ここからは1日あたり約1万トンの多種類の温泉が湧出し、温泉街のホテルや旅館に供給されています。' where id = '9l9H1kC9LkToWJaoeabg_';
update content_bodies set title = 'Jigokudani Winter Edition 4K / Superb View of Hokkaido', description = 'BEST HOKKAIDO introduces the attractive tourist spots and resources of Hokkaido. This video showcases the superb views of Hokkaido from various angles. This time, we focus on ''Jigokudani'' in Noboribetsu Onsen, which is an explosion crater formed by the eruptive activity of Mt. Hiyori. The crater has a diameter of about 450 meters and covers an area of approximately 11 hectares. Numerous outlets and fumaroles line the valley, creating a bubbling and boiling landscape that inspired the name ''Hell where demons live.'' Additionally, around 10,000 tons of various types of hot springs flow from this site daily, supplying the hot spring town''s hotels and inns.' where id = 'arsxebgqImf6mJ8Kqj0kM';
update content_bodies set title = '登別温泉街 冬編4K／北海道の絶景景色', description = 'この動画では、北海道の登別市にある登別温泉街を紹介します。江戸時代から知られる温泉地で、明治時代に温泉宿が設けられ、観光地として発展しました。毎年「にっぽんの温泉100選」で上位にランクインする日本有数の温泉地で、地名はアイヌ語の「ヌプル・ペツ」（水色の濃い川）に由来しています。温泉街には10体の鬼像があり、観光スポット「地獄谷」から立ち上る白い煙が「鬼の棲む地獄」のように見えることから、鬼がシンボルとして用いられています。また、泉源公園の間欠泉は約3時間ごとに迫力ある音とともに噴き出し、訪れる人々に感動を与えています。' where id = '4KbhvNLiB8i9jWBZFokMq';
update content_bodies set title = 'Noboribetsu Onsen Town Winter Edition 4K / Superb View of Hokkaido', description = 'This video introduces Noboribetsu Onsen Town in Hokkaido, a renowned hot spring destination known since the Edo period. Established as a tourist spot in the Meiji period, it consistently ranks high in Japan''s top hot springs. The name ''Noboribetsu'' comes from the Ainu word ''Nupuru Petu,'' meaning ''dark blue river.'' The town features ten demon statues, symbolizing the area''s connection to the ''Jigokudani'' or ''Hell Valley,'' where the hot springs emit steam and resemble a hellish landscape. Visitors can also experience the impressive geyser at Sengen Park, which erupts every three hours, providing a thrilling display of sound and steam.' where id = 'e_vuE673-75DZaFlQOVP_';
update content_bodies set title = 'Verdeプロモーション動画（三重県大台町）', description = '三重県大台町のアウトドアプログラム「Verde」のプロモーション動画です。この動画は、三重県観光キャンペーン中南勢地域部会によって作成されました。' where id = 'kJe4M6F58BtGFv0Kt_8Dd';
update content_bodies set title = 'Verde Promotional Video (Odaigun, Mie Prefecture)', description = 'This is a promotional video for the outdoor program ''Verde'' in Odaigun, Mie Prefecture. The video was created by the Nansai Regional Committee of the Mie Prefecture Tourism Campaign.' where id = 'x5OSf6AvaTi-A8UXI0l6f';
update content_bodies set title = '支笏湖 冬編4K／北海道の絶景景色', description = '「BEST HOKKAIDO」では、北海道の観光スポットや資源を紹介しています。今回は千歳市にある「支笏湖」を取り上げます。支笏湖は「日本最北の不凍湖」として知られ、環境省の水質調査で何度も日本一に認定されるほどの透明度を誇ります。札幌市内から車で約60分、新千歳空港からは約40分でアクセスできるため、手軽に大自然を楽しむことができる絶景スポットです。湖の東側には支笏湖温泉地区があり、北側と南側に向かう道路が整備されているため、レイクサイドドライブも楽しめます。' where id = 'JbTTWCipF-Pw5gGK4jtIg';
update content_bodies set title = 'Lake Shikotsu Winter Edition 4K / Superb View of Hokkaido', description = 'This video introduces Lake Shikotsu, located in Chitose City, Hokkaido, known as Japan''s northernmost non-freezing lake. The lake has been recognized multiple times as having the best water quality in Japan by the Ministry of the Environment. Easily accessible, Lake Shikotsu is about a 60-minute drive from Sapporo and 40 minutes from New Chitose Airport, making it a perfect spot for enjoying nature. Visitors can start from the hot spring area on the east side of the lake and enjoy scenic lakeside drives to the north and south.' where id = 'qZDlJztY4XBGdJq_vkQxa';
update content_bodies set title = '祝津パノラマ展望台 冬編4K／北海道の絶景景色', description = '「BEST HOKKAIDO」シリーズの一環として、北海道の港町小樽にある祝津パノラマ展望台を紹介します。この展望台は、ニセコ積丹小樽海岸国定公園内に位置し、標高70.9mから日本海の絶景を楽しむことができます。海岸線や灯台、小樽市鰊御殿などが一望でき、朝日や夕日の名所としても知られています。祝津はかつて鰊の千石場所として栄えた歴史があり、「江差追分節名歌碑」や「北海浜節民謡碑」も設置されています。' where id = 'I-oPI0KWqyAmzamlaT0R7';
update content_bodies set title = 'Shukutsu Panorama Observatory Winter Edition 4K / Superb View of Hokkaido', description = 'This video introduces the Shukutsu Panorama Observatory located in the port town of Otaru, Hokkaido, as part of the BEST HOKKAIDO series showcasing the region''s attractions. The observatory, situated at an altitude of 70.9 meters within the Niseko-Shakotan Otaru Kaigan National Monument, offers stunning views of the Sea of Japan, the coastline, lighthouses, and the Otaru Nishin Goten. It is renowned for its picturesque sunrises and sunsets. The area is historically significant as Shukutsu once thrived as a herring fishing site, marked by the presence of the Esashi Oiwake Festival Famous Song Monument and the North Seaside Festival Folk Song Monument.' where id = '8y6penjh4RuJCgB1TDElF';
update content_bodies set title = '小樽運河 冬編4K／北海道の絶景景色', description = 'この動画では、北海道の港町小樽にある小樽運河を紹介します。1923年に日本唯一の海岸沖合埋立て方式で完成し、全長1,140メートルの運河は、臨港線沿いが20メートル、北運河が当時のままの40メートルの幅を持っています。1986年には運河の一部が埋立てられ、道路と散策路が整備され、小樽市の観光資源へと変貌しました。散策路には63基のガス灯が設置されており、運河沿いの木骨石造倉庫群は当時の姿を残し、夕暮れ時からライトアップされています。また、運河周辺では『小樽雪あかりの路』や『おたる☆浅草橋オールディーズナイト』などのイベントも開催されています。' where id = 't6TDOe-7h1fsKrSubNA0W';
update content_bodies set title = 'Otaru Canal Winter Edition 4K / Superb view of Hokkaido', description = 'This video introduces the Otaru Canal, located in the port city of Otaru, Hokkaido. Completed in 1923 using Japan''s only offshore landfill method, the canal stretches 1,140 meters in length. The width varies, being 20 meters along the harbor line and 40 meters in the northern section, known as the North Canal. In 1986, part of the canal was reclaimed, creating a road and a walking path that transformed the area into a tourist destination. The walking path features 63 gas lights, and the timber-framed stone warehouses along the canal maintain their historical appearance, illuminated from dusk. Events such as the ''Otaru Snow Light Path'' and ''Otaru ☆ Asakusa Bridge Oldies Night'' are also held in the vicinity.' where id = 'OPH4jN8tsr265n1i5_bFn';
update content_bodies set title = '札幌定山渓温泉 冬編', description = '今回のBEST HOKKAIDOでは、札幌にある温泉街「定山渓温泉」を紹介します。定山渓温泉は北海道有数の温泉街で、「札幌の奥座敷」として知られています。札幌市中心部から約30km、1時間ほどでアクセス可能です。歴史は古く、1866年に修行僧の美泉常山（後に定山と改名）がこの地で温泉を発見し、1870年に温泉開発が始まりました。泉質はナトリウム-塩化物泉で、定山渓温泉には56ヵ所の泉源があります。' where id = 'rOvREXU6RYr3O1KBN4B0h';
update content_bodies set title = 'Superb view of Hokkaido/Sapporo Jozankei Onsen Winter', description = 'This edition of BEST HOKKAIDO introduces Jozankei Onsen, a renowned hot spring town located about 30 km from Sapporo city center, easily accessible in about an hour. Known as ''Okuzashiki in Sapporo'', Jozankei has a rich history dating back to 1866 when a monk named Miizumi Tsuneyama discovered the hot springs. Development of the hot springs began in 1870. The springs are classified as sodium chloride springs, with a total of 56 sources available in the area.' where id = 'OQ85nqqmZ7fq-JbRpfSn3';
update content_bodies set title = '札幌ホワイトイルミネーション編/北海道の絶景景色', description = 'BEST HOKKAIDOでは、北海道の魅力的な観光スポットや観光資源を紹介しています。今回は、札幌市で開催される第40回さっぽろホワイトイルミネーションを特集します。このイベントは1981年に日本初のイルミネーションとして始まり、冬の札幌を400,000個の電飾で彩ります。大通公園の点灯時間はクリスマス時期に24時まで延長され、恋人たちのデートスポットとしても人気です。今年はコロナ禍の影響で開催が危ぶまれましたが、無事に実施されることとなりました。' where id = 'JTB4ySuNl7N2umEgZibfW';
update content_bodies set title = 'Sapporo White Illumination Edition / Superb View of Hokkaido', description = 'BEST HOKKAIDO introduces the attractive tourist spots and resources of Hokkaido. This edition features the 40th Sapporo White Illumination, which began in 1981 as Japan''s first illumination event. The event showcases 400,000 lights that illuminate Sapporo during winter, creating a festive atmosphere. The lighting at Odori Park is extended until midnight during the Christmas season, making it a popular date spot for couples. Despite concerns about the event being canceled due to the COVID-19 pandemic, it will take place this year.' where id = 'a4XOGUU1jH8q88UNKc35-';
update content_bodies set title = 'ニセコ イワオヌプリ編／北海道の絶景景色', description = '「BEST HOKKAIDO」では、北海道の魅力的な観光スポットや観光資源を紹介しています。今回は、標高1,116メートルの活火山「イワオヌプリ」の山頂に焦点を当てています。この山は、北海道虻田郡倶知安町と磯谷郡蘭越町にまたがり、ニセコ連峰の東山系に位置しています。登山道では、6月から多くの高山植物の花々を楽しむことができ、頂上からはニセコの全山、羊蹄山、昆布岳などの絶景を見渡すことができます。' where id = 'WEFSbk3yOUOLEdFFquYNX';
update content_bodies set title = 'NISEKO IWAONUPURI: Superb View of Hokkaido', description = 'This edition of BEST HOKKAIDO introduces the stunning tourist attractions and resources of Hokkaido. It features breathtaking views of Hokkaido from various angles. The focus is on the summit of the active volcano Iwaonupuri, which stands at an altitude of 1,116 meters, located between Kutchan-cho in Abuta-gun and Rankoshi-cho in Isoya-gun. Situated in the Higashiyama system of the Niseko mountain range, the mountain trail offers a chance to enjoy a variety of alpine flowers starting in June. From the summit, visitors can enjoy panoramic views of the entire Niseko range, including Mt. Yotei and Mt. Konbu.' where id = 'Gzs0q4HfxsWRc5ibyKcp9';
update content_bodies set title = '阿曽温泉プロモーション動画（三重県大紀町）', description = '三重県大紀町に位置する阿曽温泉のプロモーション動画です。この動画は、三重県観光キャンペーン中南勢地域部会によって制作されました。' where id = 'TOzaQVUm_YLSf8hPpOmzQ';
update content_bodies set title = 'Aso Onsen Promotional Video (Daiki Town, Mie Prefecture)', description = 'This is a promotional video for Aso Onsen located in Daiki Town, Mie Prefecture. The video was created by the Nansei Regional Committee of the Mie Prefecture Tourism Campaign.' where id = 'uzKbSGB8P669PH5phkQ8M';
update content_bodies set title = '洞爺湖編／北海道の絶景景色', description = '「BEST HOKKAIDO」は、北海道の魅力的な観光スポットや観光資源を紹介する番組です。50回目の今回はリニューアルされ、北海道の絶景を様々な角度から映像でお届けします。紹介されるのは、北海道虻田郡洞爺湖町と有珠郡壮瞥町にまたがる「洞爺湖」です。この湖は「日本百景」「新日本旅行地100選」「美しい日本の歩きたくなるみち500選」に選ばれています。毎年7月から10月末までロングラン花火大会が開催され、中島には遊覧船が行き来し、観光スポットとしても人気があります。' where id = 'cuX4zZdIPT8lou8U6WJPX';
update content_bodies set title = 'Lake Toya Edition / Superb View of Hokkaido', description = 'BEST HOKKAIDO introduces the attractive tourist spots and resources of Hokkaido. The 50th edition marks a renewal of the program, showcasing the stunning views of Hokkaido from various angles through a YouTube series. The featured location is Lake Toya, which spans Toyako-cho in Abuta-gun and Sobetsu-cho in Usu-gun. It has been selected as one of the ''100 Landscapes of Japan'', ''100 New Japan Travel Destinations'', and ''500 Beautiful Japanese Walking Paths''. A long fireworks display is held annually from July to the end of October, and pleasure boats frequently visit Nakajima, making it a popular tourist destination.' where id = 'aT0efm19854hpOjkDQAI2';
update content_bodies set title = '舞鶴 神崎', description = '神崎は舞鶴市の北西部、由良川河口近くに位置し、白砂青松の美しい景観で知られています。夏の海水浴を楽しむことができるほか、さまざまな魅力があります。最近では、京丹後鉄道（通称：丹鉄）の由良川鉄橋でも知られるようになりました。京丹後鉄道の丹後神崎駅から徒歩で訪れることができ、アクセスも便利です。' where id = 'PUfQXoXhPhDaYebfif-i4';
update content_bodies set title = 'Maizuru Kanzaki', description = 'Kanzaki is situated in the northwestern part of Maizuru City, close to the mouth of the Yura River, and is renowned for its beautiful scenery featuring white sand and green pines. The area offers various attractions, particularly popular for summer swimming. Recently, it has gained recognition for the Yura River Railroad Bridge of the Kyotango Railway, commonly referred to as ''Tantetsu.'' Visitors can easily access Kanzaki on foot from Tango Kanzaki Station on the Kyotango Railway.' where id = 'Sj9IVXoNH9wXuoh885Ycf';
update content_bodies set title = '海軍ゆかりの港めぐり遊覧船　船内アナウンス編英語版', description = 'これは、舞鶴遊覧船の英語版船内アナウンスの様子です。' where id = 'RzprPpJi8C3K7dF0kbvgN';
update content_bodies set title = 'Naval Heritage Port Sightseeing Boat - English Onboard Announcement', description = 'This is the English version of the onboard announcements for the Maizuru Sightseeing Boat.' where id = 'MH6opWjT8B1ebI1lLMQfL';
update content_bodies set title = '松阪牛プロモーション動画（松阪市）', description = '世界に誇る松阪牛を紹介するプロモーション動画です。この動画は、三重県観光キャンペーン中南勢地域部会によって制作されました。さらに、三重県の中南勢エリアに関する観光情報が提供されており、津市、松阪市、明和町、多気町、大台町、大紀町の魅力を伝えるWeb観光・旅行マガジン「Storyを紡ぐたび 〜もののはれ中南勢ものがたり〜」や、松阪市の観光スポットを特集した「城下町で歴史散策とグルメ旅：松阪を歩く」などのリンクも紹介されています。三重県の観光、旅行、イベント、宿泊予約に関する情報は、三重県観光連盟の公式サイト「観光三重」で確認できます。' where id = 'dpK6NMyn9NyWPTe2U9Pfo';
update content_bodies set title = 'Matsusaka Beef Promotion Video (Matsusaka City)', description = 'This is a promotional video showcasing the world-renowned Matsusaka beef. The video was created by the Mie Prefecture Tourism Campaign for the Chunansei region.' where id = 'MTDjWlVZ_TJrJf1awRNmw';
update content_bodies set title = '舞鶴の四季', description = 'この動画では、京都の舞鶴の四季折々の風景やグルメイベントを紹介しています。舞鶴の美しさを一年を通じて強調し、各季節がもたらすユニークな体験や料理の魅力を伝えています。' where id = 'k6vvzKpR0DZMAxbEgiCJb';
update content_bodies set title = 'Four Seasons of Maizuru', description = 'This video showcases the seasonal scenery and gourmet events in Maizuru, Kyoto. It highlights the beauty of Maizuru throughout the year, emphasizing the unique experiences and culinary delights that each season brings.' where id = 'ZZenelEPzcu10-XitPRjc';
update content_bodies set title = '京都駅から舞鶴へのアクセス', description = 'この動画では、京都駅から舞鶴へのアクセス方法として、特急列車と高速バスを紹介しています。京都を訪れた際には、海辺の舞鶴を楽しんでみてはいかがでしょうか。' where id = 'oN5zCZTwhevrFgHefdgd9';
update content_bodies set title = 'Access to Maizuru from Kyoto Station', description = 'This video provides information on how to reach Maizuru from Kyoto Station using limited express trains and high-speed buses. It encourages visitors to explore the beautiful coastal area of Kyoto.' where id = 'YNPJbz5dMbB3yYKtvb8dZ';
update content_bodies set title = '日本寿司の発祥地、舞鶴京都', description = '古代、舞鶴市の一部は「若狭の国」に含まれ、天皇の食卓に並ぶ料理の食材を供給していました。奈良の都、平城京の遺跡から発掘された記録によれば、現在の舞鶴市を含む地域から約1300年前に寿司が献上されたことが示されており、これは日本における寿司に関する最古の資料とされています。このように、舞鶴は「日本寿司の発祥地」と呼ばれ、豊富な魚介類で知られています。' where id = 'Y7dVzn6y8S6sfz7-Up3_m';
update content_bodies set title = 'Birthplace of Japanese Sushi, Maizuru Kyoto', description = 'Maizuru City, part of the ancient ''Region of Wakasa'', historically provided ingredients for the emperor''s meals. Archaeological findings from Heijokyo, the capital of Nara, indicate that sushi from the area, including present-day Maizuru, was served around 1300 years ago, marking it as the oldest known reference to sushi in Japan. Consequently, Maizuru is recognized as the ''birthplace of Japanese sushi'' and is celebrated for its abundant fish and shellfish.' where id = '8jg5E1Z2faTAhztZ-Z-8_';
update content_bodies set title = '海軍ゆかりの港めぐり遊覧船　見どころ紹介　～海上自衛隊基地編～', description = '「海軍ゆかりの港めぐり遊覧船」は、赤れんが博物館の海側にある桟橋から出発し、舞鶴湾周辺の見どころを約30分かけて巡ります。特に、北吸桟橋に停泊する海上自衛隊の大規模な護衛艦を間近で見ることができるのが最大の魅力です。舞鶴に訪れた際には、ぜひこの遊覧船に乗船してみてください！' where id = 'VbIqpIKALR481Onb4T-qd';
update content_bodies set title = 'Naval Heritage Port Cruise - Highlights of the Maritime Self-Defense Force Base', description = 'The ''Naval Heritage Port Cruise'' departs from the pier located on the seaside of the Red Brick Museum and takes approximately 30 minutes to tour around the scenic spots of Maizuru Bay. One of the main attractions is the opportunity to see the large-scale escort ships of the Japan Maritime Self-Defense Force up close at the Kitaku Pier. If you visit Maizuru, be sure to take this cruise!' where id = 'iL1HalSICtYeIAxaPepDT';
update content_bodies set title = '東京ディズニーランドでできないこと', description = 'この記事では、東京ディズニーランドで禁止されているいくつかの活動について説明しています。訪問者が公園内の制限やルールを理解するためのガイドとして機能しています。これらの制限についてより詳しく知りたい方は、提供されたウェブサイトを訪れることをお勧めします。この記事は、アジアでのテーマパーク体験を最大限に活用するためのリソースの一部であり、特に東京ディズニーランドやユニバーサル・スタジオ・ジャパンに焦点を当てています。' where id = 'Q37HqJPGGvhXzE0wzbMkb';
update content_bodies set title = 'Things you CAN''T do at Tokyo Disneyland', description = 'This article outlines several activities that are prohibited at Tokyo Disneyland. It serves as a guide for visitors to understand the limitations and rules within the park. For a more detailed exploration of these restrictions, readers are encouraged to visit the website provided. The article is part of a broader resource aimed at helping theme park enthusiasts maximize their experiences in Asia, particularly at Tokyo Disneyland and Universal Studios Japan.' where id = 'K77xK5rRyqCZu4JfPNs76';
update content_bodies set title = '史跡斎宮跡', description = '斎宮は天皇に代わり伊勢神宮の天照大神に仕えた斎王が暮らした場所です。この史跡周辺には、平安時代の斎宮寮庁の建物を復元した「さいくう平安の杜」など、斎宮の世界に関連するスポットが点在しています。詳細については、観光三重のHPをご覧ください。' where id = 'iRPOTDUrRN2S2EKpCFgyy';
update content_bodies set title = 'Historical Site of Saiku', description = 'Saiku was the residence of the Saio, a priestess who served the deity Amaterasu at Ise Shrine on behalf of the Emperor. The area surrounding this historical site features several spots related to the Saiku world, including ''Saiku Heian no Mori,'' which has reconstructed buildings from the Heian period that were part of the Saiku administrative office. For more details, please visit the Mie Prefecture tourism website.' where id = 'nr8s1XOx6Z1xlb3cUinD9';
update content_bodies set title = 'レトロ自動販売機の聖地：舞鶴ドライブインダルマ', description = '「ドライブイン」という懐かしい呼び名がぴったりのサービスエリアで、特にラーメンやうどんの自動販売機が今なお現役で稼働しているのが特徴です。ここ「ドライブインダルマ」はレトロ自動販売機の聖地とも呼ばれ、遠方から訪れる人も多く、ツーリングスポットとしても注目されています。また、店内には昭和時代の懐かしいゲームが数多くあり、訪れる人々に懐かしさとわくわく感を提供しています。' where id = 'DJ9SZSFOpqQxw2XjQxge_';
update content_bodies set title = 'The Holy Land of Retro Vending Machines: Maizuru Drive-In Daruma', description = 'The ''Drive-In'' is a nostalgic service area that perfectly embodies the charm of the past. The main attraction is the active vending machines that serve ramen and udon, making ''Drive-In Daruma'' a pilgrimage site for fans of retro vending machines, drawing visitors from afar. It is also a popular touring spot. Inside, there are numerous nostalgic games from the Showa era, providing a delightful mix of nostalgia and excitement.' where id = '_tx3OG-EuNnR5qNqP9qT1';
update content_bodies set title = '舞鶴赤れんがパークの駐車場を世界チャンピオンLA CLASSICが紹介', description = '舞鶴在住のフリースタイルフットボール世界チャンピオン、ラクラシックのお二人が舞鶴赤れんがパークの「駐車場」を紹介します。彼らは、訪れる人々にとって便利な駐車施設についての情報を提供し、舞鶴赤れんがパークの魅力を伝えています。この公園は地元の人々や観光客にとって重要なスポットであり、チャンピオンたちの視点が加わることで、より特別な体験が提供されています。' where id = 'RSjgd43RWkp3ncYXFaWKl';
update content_bodies set title = 'Introducing the Parking Area at Maizuru Red Brick Park by World Champion LA CLASSIC', description = 'This text introduces the parking area at Maizuru Red Brick Park, presented by LA CLASSIC, a duo of freestyle football world champions residing in Maizuru. The champions share insights about the parking facilities available at the park, highlighting its convenience for visitors. The Maizuru Red Brick Park is a notable location for both locals and tourists, and the champions'' involvement adds a unique perspective to the park''s offerings.' where id = 'foOi5cmOzFM621Ze6qt1P';
update content_bodies set title = '舞鶴赤れんがパークの芝生広場を世界チャンピオンLA CLASSICが紹介', description = '舞鶴に住むフリースタイルフットボールの世界チャンピオン、ラクラシックのお二人が舞鶴赤れんがパークの「芝生広場」の魅力を紹介します。彼らはこの公園のユニークな特徴や魅力を強調し、地元の人々や訪問者にとっての魅力を伝えています。' where id = 'CaOBg3IdaixXai0Qppni_';
update content_bodies set title = 'Introducing the Grass Square at Maizuru Red Brick Park by World Champion LA CLASSIC', description = 'World Champion freestyle footballers, LA CLASSIC, who reside in Maizuru, introduce the charm of the ''Grass Square'' at Maizuru Red Brick Park. This presentation highlights the unique features and attractions of the park, showcasing its appeal to both locals and visitors.' where id = '0xLNA4Sy-4nSi7Qe3yWJ8';
update content_bodies set title = '舞鶴赤れんがパークで紹介される世界チャンピオンLA CLASSIC～5号棟赤れんがイベントホール～', description = '舞鶴に住むフリースタイルフットボールの世界チャンピオン、ラクラシックのお二人が舞鶴赤れんがパークの「5号棟赤れんがイベントホール」の魅力を紹介します。このイベントでは、会場のユニークな特徴やチャンピオンたちの才能が強調されます。' where id = 'lIWOxUkJUwZ-_h3SBQA5k';
update content_bodies set title = 'Introducing the World Champion LA CLASSIC at Maizuru Red Brick Park - Event Hall No. 5', description = 'World freestyle football champions, LA CLASSIC, who reside in Maizuru, will showcase the charm of the ''Event Hall No. 5'' at Maizuru Red Brick Park. This event highlights the unique features of the venue and the talents of the champions.' where id = '2TNXT0kXLJXyPjzy3SO2f';
update content_bodies set title = '京都府舞鶴市【観光PR動画】', description = '舞鶴は京都府北部に位置する海に面した港町で、京都駅から特急電車で約90分でアクセス可能です。豊かな自然や貴重な文化財が多く、観光スポットが充実しています。また、日本海の新鮮な海の幸も楽しめる魅力的な場所です。この動画では、舞鶴の魅力を詰め込んだ内容をお楽しみいただけます。' where id = 'IfGuWs7aMkU7CHdAPfan7';
update content_bodies set title = 'Maizuru City, Kyoto Prefecture - Tourism PR Video', description = 'Maizuru is a port town located in the northern part of Kyoto Prefecture, facing the sea. It is accessible from Kyoto Station in about 90 minutes by express train. The area boasts rich nature and valuable cultural assets, making it a great destination for visitors. Additionally, the fresh seafood from the Sea of Japan is one of the highlights. Enjoy this collection of videos showcasing the charm of Maizuru.' where id = 'QK_Y1cg_lzxPEfHB5rxlY';
update content_bodies set title = '舞鶴観光　西舞鶴編', description = '西舞鶴は約430年前に築かれた田辺城の城下町として栄え、今もその風情を町の中で見ることができます。田辺城跡をはじめ多くの歴史ある神社やお寺が今も残り、訪れる人々に歴史を感じさせます。徒歩や自転車でゆっくり街中を周ることが推奨されており、町の美しさを存分に楽しむことができます。また、日本海の新鮮な旬の魚介類を味わえることも大きな魅力で、訪問者にとって重要な観光ポイントとなっています。' where id = 't_ycFpi9GPj_iszHglXc3';
update content_bodies set title = 'Maizuru Tourism: Exploring Nishi-Maizuru', description = 'Nishi-Maizuru, a castle town established around 430 years ago with the construction of Tanabe Castle, retains its historical charm. Visitors can still see the ruins of Tanabe Castle along with many ancient shrines and temples. It is recommended to explore the town on foot or by bicycle to fully appreciate its beauty. Additionally, Nishi-Maizuru offers the delightful experience of tasting fresh seasonal seafood from the Sea of Japan, making it a significant attraction for visitors.' where id = 'jbignh9F7uJR7NRYbQ7uM';
update content_bodies set title = '京都舞鶴　「育成岩がき」', description = '京都府舞鶴で生産される育成岩がきについての情報です。舞鶴は、海に面した地域で、豊かな海の恵みを受けて育った岩がきが特徴です。育成岩がきは、特にその味わいと食感が評価されており、地元の特産品として親しまれています。' where id = 'WakuHorCzT--WOlsfotaa';
update content_bodies set title = 'Kyoto Maizuru ''Cultivated Rock Oysters''', description = 'Cultivated rock oysters from Maizuru, Kyoto Prefecture.' where id = '0Z4jSCwgaLOs89_sd55-e';
update content_bodies set title = '京都舞鶴　「丹後とり貝」', description = '京都府舞鶴産の丹後とり貝について紹介します。出荷前の水揚げの様子を詳しく説明しており、丹後とり貝の特徴やその魅力を伝えています。舞鶴の豊かな海で育まれたこの貝は、新鮮さが際立ち、地元の特産品として親しまれています。' where id = '9Vc0AZ3CjO29ftfM381Ar';
update content_bodies set title = 'Tango Tori Clam from Maizuru, Kyoto', description = 'This text introduces the Tango tori clam, which is produced in Maizuru, Kyoto Prefecture. It highlights the process of catching the clams before they are shipped.' where id = 'K9KaIri6Sx20cAdsMO1Aj';
update content_bodies set title = '世界遺産 巡礼路「熊野古道伊勢路」 ～映像シリーズ１', description = '古より日本人は万物に神が宿ると信じ、自然を神と崇めてきました。伊勢神宮には太陽の神、天照大御神が祀られており、ここで旅の無事を祈り、熊野への旅が始まります。伊勢路は伊勢から熊野まで約170キロの道のりで、様々な顔を持つ峠をいくつも越えていきます。熊野古道は、日本各地から和歌山県の熊野三山（熊野速玉大社、熊野那智大社、熊野本宮大社）を目指した巡礼者が歩いた古道です。伊勢神宮と熊野三山を結ぶこの世界遺産の巡礼路「熊野古道伊勢路」の歴史と魅力を紹介します。' where id = '5q24VC5cE8tRoLVJ94Ct-';
update content_bodies set title = 'World Heritage Pilgrimage Route ''Kumano Kodo Iseji'' - Video Series 1', description = 'Since ancient times, the Japanese have believed that gods reside in all things and have revered nature. The Ise Jingu Shrine, dedicated to the sun goddess Amaterasu, is where travelers pray for a safe journey before starting their pilgrimage to Kumano. The Iseji route stretches approximately 170 kilometers from Ise to Kumano, crossing numerous mountain passes with diverse landscapes. The Kumano Kodo is an ancient path that pilgrims walked to reach the three Kumano shrines in Wakayama Prefecture: Kumano Hayatama Taisha, Kumano Nachi Taisha, and Kumano Hongu Taisha. This world heritage pilgrimage route, connecting the two major sacred sites of Ise Jingu and the Kumano Sanzan, showcases the history and allure of the Kumano Kodo Iseji.' where id = 'LHaWiJNXfyilZkRbjwnsF';
update content_bodies set title = '海軍ゆかりの港めぐり遊覧船', description = 'この動画では、海軍に関連する港を巡る遊覧船について紹介しています。海軍の歴史や文化に触れながら、訪れる港の魅力を楽しむことができる内容となっています。' where id = '2RpQhha0zim7RHvJ3IboD';
update content_bodies set title = 'Naval Heritage Port Tour Boat', description = 'This video introduces a tour boat that explores ports associated with naval history.' where id = 'Mzg92y5qxrOeWu8s3br6_';
update content_bodies set title = '【舞鶴かに®2018】かにPR動画～カニコレ～', description = '舞鶴かに®を多くの人に知ってもらうために、PR動画を制作しました。軽快なセリの様子をスタイリッシュに表現しています。ぜひ舞鶴に遊びに来てください！' where id = 'rBwnqT83XMgWx7O9s9p99';
update content_bodies set title = 'Mizusaki Crab® 2018 - Crab PR Video', description = 'To promote Mizusaki Crab®, we created a PR video showcasing the lively atmosphere of crab auctions in a stylish manner. We invite everyone to come and visit Mizusaki!' where id = 'pwEKcAu7xMiR3OH16toUA';
update content_bodies set title = '丹後の海にさそわれて②（与謝野，舞鶴編）', description = 'この文章では、京都府北部エリアに位置する宮津、京丹後、伊根、与謝野、舞鶴の見どころやおすすめスポットを紹介しています。各地域の魅力を知ることで、訪れる際の参考になる情報が得られます。' where id = 'YUj1B4W_cZyKk4JsykZeX';
update content_bodies set title = 'Invited by the Sea of Tango② (Yosano, Maizuru Edition)', description = 'This text introduces the attractions and recommended spots in the northern area of Kyoto Prefecture, including Miyazu, Kyotango, Ine, Yosano, and Maizuru.' where id = '4Q4fUuB_A2RML_CcdJWJe';
update content_bodies set title = '海軍ゆかりの港めぐり遊覧船', description = '護衛艦が目の前に迫り、海軍に関連する造船所を訪れることができます。心地よい潮風を感じながら、海からの美しい眺望を楽しむことができます。また、船内では海上自衛隊のOBによる人気のガイドも充実しています。' where id = 'DkY15ATQAVfCoPHrCs_cY';
update content_bodies set title = 'Naval Heritage Port Cruise', description = 'Experience the thrill of seeing a destroyer up close and visit shipyards with naval connections. Enjoy the refreshing sea breeze while taking in the views from the water. The cruise features an engaging onboard guide, who is a popular former member of the Japan Maritime Self-Defense Force.' where id = 'fPjDEipoSY0tNTH_MYoMM';
update content_bodies set title = '松尾寺　仏舞', description = '松尾寺で行われる仏舞は、伝統的な宗教行事の一環として重要な役割を果たしています。この舞は、仏教の教えを表現し、信者や観客に深い感動を与えることを目的としています。松尾寺はその歴史的背景と美しい環境から、多くの人々に親しまれており、仏舞はその魅力の一部となっています。' where id = 'G8y9alTdKoiI5X7p_d842';
update content_bodies set title = 'Matsuo-ji Temple: Buddhist Dance', description = 'The Buddhist dance is performed at Matsuo-ji Temple.' where id = 'Jx2Q_okwy5goRFnY5_63o';
update content_bodies set title = '丹後の海にさそわれて①（宮津，京丹後，伊根編）', description = 'この記事では、京都府北部エリアである宮津、京丹後、伊根、与謝野、舞鶴の見どころやおすすめスポットを紹介しています。' where id = 'HX7zKY1GTmudbNSNqn5rc';
update content_bodies set title = 'Invited by the Sea of Tango ① (Miyazu, Kyotango, Ine Edition)', description = 'This article introduces attractions and recommended spots in the northern area of Kyoto Prefecture, including Miyazu, Kyotango, Ine, Yosano, and Maizuru.' where id = 'Ws5Qan2dGNpqciBwbDHTh';
update content_bodies set title = '長崎鼻＆龍宮神社', description = '長崎鼻は鹿児島県指宿市に位置する絶景スポットで、龍宮神社があることで知られています。この地域には長崎鼻灯台があり、海や自然の美しさを楽しむことができます。観光地として人気があり、特にドローンを使った4K映像でその景色が多く撮影されています。指宿観光を楽しむ際には、ぜひ訪れたい場所です。' where id = 'yqWn6dD5yHYSdFGAddw9X';
update content_bodies set title = 'Nagasaki Nose & Ryugu Shrine', description = 'Nagasaki Nose is a scenic spot located in Ibusuki, Kagoshima, known for its stunning views and the Ryugu Shrine. The area features the Nagasaki Nose Lighthouse and offers breathtaking landscapes, making it a popular tourist destination. Visitors can enjoy the beauty of the sea and the surrounding nature, often captured in 4K drone footage. The site is a must-visit for those exploring Ibusuki tourism.' where id = 'TBsWngATKLvvwE2LlNbi5';
update content_bodies set title = 'みなと舞鶴ちゃったまつり「花火鑑賞船」', description = 'ちゃったまつりを締めくくる花火は圧巻で、2019年も花火鑑賞船が運航します。花火を楽しむための特別な体験が提供されます。問い合わせはまいづる広域観光公社まで、電話番号は0773-77-5400（平日9：00～17：00）です。' where id = 'tGYfpL630WGw4I_uizkrN';
update content_bodies set title = 'Minato Maizuru Chattamatsuri Fireworks Viewing Boat', description = 'The fireworks that conclude the Chattamatsuri festival are spectacular. In 2019, the fireworks viewing boat will be in operation again. For inquiries, please contact the Maizuru Wide Area Tourism Association at 0773-77-5400 (weekdays from 9:00 AM to 5:00 PM).' where id = 'heb-fFf20N0v87Y-2v_JV';
update content_bodies set title = '鹿児島県指宿市/枚聞神社（ドローン/iPhone ４K撮影）', description = '枚聞神社は鹿児島県指宿市開聞十町に位置し、主に大日孁貴命を祀っています。天照大御神の先祖神々や八柱の皇祖神も一緒に祀られ、南薩地方の守り神として古くから敬われてきました。特に交通安全や航海安全、漁業の守り神として地元の漁師たちに大切にされています。境内には神馬の像があり、神馬に関する伝承も存在します。本殿の奥からは指宿のシンボルである開聞岳が見え、朱色の社殿と緑豊かな境内をモチーフにした多様な絵馬も置かれています。交通安全や航海安全、厄除け、開運のご利益があるとされ、ぜひ訪れてみてください。' where id = 'qt0UhaqNCsUZ0Fdzv97u_';
update content_bodies set title = 'Ibusuki City, Kagoshima Prefecture / Hirakiki Shrine (Drone/iPhone 4K Shooting)', description = 'Hirakiki Shrine is located in Kaimon, Ibusuki City, Kagoshima Prefecture. It primarily enshrines the deity Oohirume-muchi-no-mikoto, along with other ancestral gods of Amaterasu. The shrine is also dedicated to eight imperial ancestors and has been revered as a guardian deity of the southern Satsuma region, respected as the ancestor of the area. It is particularly important to local fishermen for traffic and maritime safety. The shrine features a statue of a divine horse, with associated legends. From the main hall, visitors can see the iconic Kaimondake mountain. Various types of ema (votive tablets) inspired by Kaimondake and the shrine''s red buildings are available. The shrine is believed to offer blessings for traffic safety, maritime safety, and fortune. A visit to Hirakiki Shrine is highly recommended.' where id = 'sjuJDM1AkWkU3vu6FcE8H';
update content_bodies set title = '鹿児島県指宿市/池田湖（ドローン４K撮影）', description = '池田湖は九州最大のカルデラ湖で、周囲約15km、水深最大233mを誇ります。神秘的な自然景観と湖を取り巻くのどかな風景が魅力で、約5700年前からの火山活動によって形成されました。体長1.5メートル以上の「大うなぎ」が生息し、天然記念物にも指定されています。また、謎の生物「イッシー」の伝説もあります。湖畔には四季折々の花々が植えられ、訪れる人々を楽しませています。2022年10月7日には、カフェや水上デッキを備えた「IKEDAKO PAX」がオープンしました。観光の際は、干潮時に現れる砂の道を通って知林ヶ島にも足を運んでみてください。撮影には特別な許可を取得しています。' where id = 'iWzbrYkEVRfOG5ttBIdyL';
update content_bodies set title = 'Ikeda Lake in Ibusuki City, Kagoshima Prefecture (Drone 4K Footage)', description = 'Ikeda Lake is the largest caldera lake in Kyushu, with a circumference of about 15 km and a maximum depth of 233 m. The lake''s enchanting natural scenery and the tranquil landscapes surrounding it are captivating. Formed over thousands of years due to volcanic eruptions, it is home to the ''giant eel,'' which can grow over 1.5 meters and is designated as a natural monument. There is also a legend of a mysterious creature called ''Issy.'' The lakeside is adorned with seasonal flowers, enhancing its beauty throughout the year. On October 7, 2022, a facility called ''IKEDAKO PAX'' opened, featuring a café and a waterside deck. Visitors are encouraged to explore the area leisurely, especially the sand path that appears only at low tide leading to Chirin Island. Note that filming was done with special permission.' where id = '5Dnx-sw1ciweEJ7Ul6jVn';
update content_bodies set title = '【鹿児島県指宿市】鰹節工場見学', description = 'この動画では、鹿児島県指宿市にある鰹節工場の見学について紹介しています。鰹節は日本の伝統的な食材であり、その製造過程や工場の様子を知ることができます。' where id = 'iA86qtA1jv5JQagyMFVhr';
update content_bodies set title = 'Katsuobushi Factory Tour in Ibusuki City, Kagoshima Prefecture', description = 'This video introduces a tour of a katsuobushi factory located in Ibusuki City, Kagoshima Prefecture.' where id = 'W4QVf1Zufq6MihZ6UNA29';
update content_bodies set title = '【鹿児島県指宿市】長太郎焼・白薩摩（陶芸体験）', description = 'この動画では、鹿児島県指宿市における長太郎焼と白薩摩の陶芸体験について紹介しています。' where id = 'xrDHuphyxIstLtyl5zgy3';
update content_bodies set title = 'Chotaro-yaki and Shirasatsuma (Pottery Experience) in Ibusuki City, Kagoshima Prefecture', description = 'This video introduces the pottery experience of Chotaro-yaki and Shirasatsuma in Ibusuki City, Kagoshima Prefecture.' where id = 'ArapaDfeljXhBpW6TxXaO';
update content_bodies set title = '【鹿児島県指宿市】青隆寺　文化体験', description = 'この動画では、鹿児島県指宿市にある青隆寺での文化体験について紹介しています。' where id = '37fridtW9hcv4_3Jaaops';
update content_bodies set title = 'Cultural Experience at Seiryuji Temple in Ibusuki City, Kagoshima Prefecture', description = 'This video introduces the cultural experience at Seiryuji Temple located in Ibusuki City, Kagoshima Prefecture.' where id = '4P4O2JNUi0hqaRQyGRMCt';
update content_bodies set title = '【鹿儿岛県指宿市】鰹節工場見学', description = '鰹節の製造過程を見学するツアーです。-50℃の冷凍庫に入ることができ、鰹節や鰹のスープを試食することができます。興味のある方は、指宿観光と体験の会にお問い合わせください。' where id = 'FF9GMqGGqXm3_HuLkQLKh';
update content_bodies set title = 'Kagoshima Prefecture Ibusuki City: Bonito Factory Tour', description = 'Experience the process of making bonito flakes by visiting a factory. The tour includes a visit to a -50°C cold storage facility, where you can taste bonito flakes and bonito soup.' where id = 'TTUjsEw13Gf8geh7Xyyfe';
update content_bodies set title = '【鹿児島県指宿市】長太郎焼陶芸体験・白薩摩絵付け体験', description = '長太郎焼陶芸体験では、参加者がカップや皿などの手作り陶器を制作します。完成品は1ヶ月後にお届けされます。白薩摩絵付け体験では、カップや皿に絵を描くことができ、こちらも完成品は1ヶ月後にお届けされます。お問い合わせは指宿観光と体験の会まで。' where id = '6n_nLcKBcy88uk_DNEylA';
update content_bodies set title = 'Kagoshima Prefecture Ibusuki City: Chōtarō Pottery Experience and Shirasama Painting Experience', description = 'The Chōtarō pottery experience allows participants to create handmade pottery items such as cups or plates, with the finished products delivered one month later. The Shirasama painting experience involves painting on cups or plates, also with delivery of the completed works in one month. For inquiries, please contact the Ibusuki Tourism and Experience Association.' where id = 'hY2eOKglf6OFvT2xJY33y';
update content_bodies set title = '鹿児島県指宿市の青龍寺文化体験', description = '青龍寺では、庭園を散歩し、経典を写経する体験や瞑想体験を提供しています。文化的な体験を通じて、心を落ち着ける時間を過ごすことができます。お問い合わせは指宿観光と体験の会まで。' where id = '0YAigVjmxkBpEemR04rpb';
update content_bodies set title = 'Cultural Experience at Seiryuji Temple in Ibusuki City, Kagoshima Prefecture', description = 'The Seiryuji Temple offers a cultural experience that includes a stroll through its beautiful garden, a sutra copying experience, and meditation sessions. For inquiries, please contact the Ibusuki Tourism and Experience Association.' where id = 'psEG5x6WQ1c12zzgrUPpF';
update content_bodies set title = '世界遺産 巡礼路「熊野古道伊勢路」 ～映像シリーズ２', description = '巡礼の道には、祖先を敬い、自然を大切に守る人々の暮らしがあります。旅の無事を願う年配の里の人々や、木の精霊と話しながら舟を作る人、棚田を耕す人々が登場し、自然と神々と共存する様子が描かれています。熊野古道は、日本各地から和歌山県の熊野三山を目指して歩かれた古道であり、伊勢神宮と熊野三山を結ぶ世界遺産「熊野古道伊勢路」の歴史と魅力が紹介されています。' where id = '4pdxM24xH6uni2MXv3nGy';
update content_bodies set title = 'World Heritage Pilgrimage Route ''Kumano Kodo Iseji'' - Video Series 2', description = 'The pilgrimage route is home to people who respect their ancestors and cherish nature. It features elderly villagers who pray for safe travels, artisans who converse with tree spirits while crafting boats, and farmers who cultivate terraced rice fields, known as ''plowing to the heavens.'' These individuals coexist with nature and deities. The Kumano Kodo is an ancient path that pilgrims walked from various parts of Japan to the Kumano Sanzan (Kumano Hayatama Taisha, Kumano Nachi Taisha, and Kumano Hongu Taisha) in Wakayama Prefecture. This World Heritage pilgrimage route, ''Kumano Kodo Iseji,'' connects two of Japan''s major sacred sites: Ise Jingu and the Kumano Sanzan, showcasing its history and allure.' where id = '9q55NOGM-q7FCRUSF7mmA';
update content_bodies set title = '【鹿児島県指宿市】シズる！指宿～うなぎ～', description = '鹿児島県指宿市は、人気の返礼品としてうなぎを提供しています。鹿児島県は日本一の養鰻生産量を誇るうなぎの大国で、南九州の温暖な気候とシラス台地の土壌でろ過された水で育てられた国産うなぎは、身がふっくらとしており、臭みもなく、安全で高品質な逸品です。また、他にも「黒毛和牛」「黒豚」「完熟マンゴー」などのおすすめ返礼品も紹介されています。' where id = 'ufWvbbVyzl5Fsj81K7R4g';
update content_bodies set title = 'Ibusuki City, Kagoshima Prefecture: Sizzle! Ibusuki - Eel', description = 'Kagoshima Prefecture is renowned for its eel production, being the top producer in Japan. The locally farmed eels are raised in filtered water from the Shirasu plateau, benefiting from the warm climate of southern Kyushu. This results in eels that are plump, free from odor, and of high quality, ensuring safety and reliability. In addition to eel, other recommended return gifts include ''Kuroge Wagyu'', ''Kurobuta'', and ''Ripe Mangoes''.' where id = 'Bg_w3r4PVSmkRRD47HrOs';
update content_bodies set title = '【鹿児島県指宿市】お待ちしています、指宿', description = '指宿は南国の豊かな自然と天然の恵み温泉が魅力です。心と体を癒す雄大な風景が広がっています。いつかまた、皆様のお越しをお待ちしております。' where id = 'VtzsbPq39lJEP5dAqoK2x';
update content_bodies set title = 'Welcome to Ibusuki, Kagoshima Prefecture', description = 'Ibusuki offers a rich natural environment and natural hot springs that provide healing for both the mind and body. The majestic landscapes of Ibusuki are truly breathtaking. We look forward to welcoming you back someday.' where id = 'BrmuUIulTawIpknNDL2MJ';
update content_bodies set title = '【鹿児島県指宿市】あなたがすきです、指宿30', description = '指宿を旅したくなるようなあたたかな時間を提供します。皆さんが再びお越しいただける日を心待ちにしています。' where id = 'ICDdQCj5RHR77VSNnzFKU';
update content_bodies set title = 'Ibusuki City, Kagoshima Prefecture: We Love You, Ibusuki 30', description = 'Experience the warm moments that make you want to travel to Ibusuki. We look forward to the day when you can visit us again.' where id = '1ZZ1AIF1GinUgUe5asmgo';
update content_bodies set title = '伊賀のかたやき　鎌田製菓さん', description = '伊賀名物の豆腐田楽「わかや」さんと、かたやきのお店「鎌田製菓」さんを訪れました。取材レポート記事は、こちらからご覧いただけます。https://www.kankomie.or.jp/report/detail_179.html' where id = 'yKYE8emzhA-AX8Z8dYUHy';
update content_bodies set title = 'Iga''s Kata-yaki: Kamada Seika', description = 'I visited ''Wakaya'', a famous tofu dengaku shop in Iga, and ''Kamada Seika'', a kata-yaki store. You can find the report article here: https://www.kankomie.or.jp/report/detail_179.html' where id = 'yRRvAz5lh0BXGHUMwu9QS';
update content_bodies set title = '伊勢神宮から車で15分！伊勢夫婦岩ふれあい水族館 伊勢シーパラダイスで海獣たちと交流　その２', description = '「伊勢夫婦岩ふれあい水族館 伊勢シーパラダイス」は、世界最大の旅行サイト「トリップアドバイザー」で過去に「国内人気の水族館部門　第５位」を獲得した水族館です。海の生き物たちと触れ合える体験ができる場所として、多くの訪問者に親しまれています。詳細については、https://www.kankomie.or.jp/report/detail_181.htmlをご覧ください。' where id = 'EARkGSO_nfjEcfg3s5c2Y';
update content_bodies set title = 'Ise Sea Paradise: A 15-Minute Drive from Ise Jingu to Interact with Marine Animals', description = 'Ise Sea Paradise, known as Ise Fufu-Iwa Fureai Aquarium, is a popular aquarium that has ranked fifth in the domestic aquarium category on TripAdvisor. It offers visitors the chance to interact with marine animals. For more details, visit https://www.kankomie.or.jp/report/detail_181.html.' where id = 'VueC0kB39MyPnb37gVHTU';
update content_bodies set title = '指宿天然砂むし温泉を体験してみた！', description = '世界的にも珍しい「指宿砂むし温泉」の体験レポートです。砂むしとは何か、どのような服装で入るのか、砂に埋もれる感覚はどうなのかなど、写真だけでは伝わらない砂むし温泉の魅力をお届けします。ぜひ、ここでしか味わえない温泉の魅力を体感しに、指宿へお越しください。' where id = 'Bhq7eTZ3yFWRajOGyNoVk';
update content_bodies set title = 'Experience the Unique Ibusuki Sand Bath!', description = 'This report details the rare experience of the ''Ibusuki Sand Bath,'' a unique type of hot spring found only in a few places worldwide. What exactly is a ''sand bath''? What should you wear? What does it feel like to be buried in sand? This article provides insights into the sand bath experience that cannot be conveyed through photos alone. Come and experience the charm of this one-of-a-kind hot spring in Ibusuki!' where id = 'oR4f6qwtNQefoy9AvEBSO';
update content_bodies set title = '【鹿児島県指宿市】ふるさとチョイス大感謝祭！初めての生配信はうまくいったのか？！', description = '「ふるさとチョイス大感謝祭」はオンラインで生配信された動画です。指宿の魅力が詰まった内容で、砂むし温泉に入ったり、しゃぶしゃぶを楽しんだりする様子が紹介されています。クイズコーナーや砂の温かさを表現する実験など、ワクワクする要素が満載の30分間となっており、視聴者を楽しませる内容です。' where id = 'Ptl_ViM2EkhZeKXvBlnjy';
update content_bodies set title = 'Ibusuki City Hometown Choice Grand Thanksgiving Festival! Did the first live broadcast go well?!', description = 'The ''Hometown Choice Grand Thanksgiving Festival'' is an online live broadcast video. It features the charm of Ibusuki, including experiences like entering a sand bath and enjoying shabu-shabu. The content is packed with excitement, including a quiz corner and experiments to express the warmth of the sand, promising an exhilarating 30 minutes!' where id = 'Kt5TxjvxXm-USijNtzwvX';
update content_bodies set title = '「読めない、指宿」', description = '鹿児島県指宿市は、全国の約4割の人が読めないとされる難読地名「指宿」で知られています。「読めない、指宿」では、沸き立つ砂浜やテーブルの上でぐるぐる回るそうめんなど、他の地域では想像できないユニークな素材が紹介されています。この難読さを逆手に取り、指宿出身のお笑い芸人が「読めない、指宿」をテンポの良い曲調でコミカルに紹介しています。インパクトのあるキャラクターとリズムは、脳内で繰り返し再生されること間違いなしです！' where id = '08FyS0thO9XiZhUr0mO_L';
update content_bodies set title = 'Ibusuki, a Hard-to-Read Place Name', description = 'Ibusuki, located in Kagoshima Prefecture, is known for its difficult-to-read name, with about 40% of people nationwide unable to pronounce it correctly. The campaign ''Read the Unreadable, Ibusuki'' showcases unique local attractions, such as bubbling sandy beaches and swirling somen noodles on tables, which are hard to imagine in other regions. Leveraging the challenge of its name, a local comedian from Ibusuki presents ''Read the Unreadable, Ibusuki'' in a catchy and humorous musical style. The impactful characters and rhythm are sure to stick in your mind!' where id = 'vV-O-MwWDASjErptMWJ-1';
update content_bodies set title = '伊勢神宮から車で15分！伊勢夫婦岩ふれあい水族館 伊勢シーパラダイスで海獣たちと交流　その１', description = '世界最大の旅行サイト「トリップアドバイザー」で、過去に「国内人気の水族館部門　第５位」を獲得した「伊勢夫婦岩ふれあい水族館 伊勢シーパラダイス」を訪れました。海の生き物たちと触れ合えるこの水族館は、伊勢神宮から車でわずか15分の距離にあります。詳細は、こちらのリンクをご覧ください。https://www.kankomie.or.jp/report/detail_181.html' where id = 'boOpXBDh91iGqd5sQikEK';
update content_bodies set title = 'Ise Sea Paradise: A 15-Minute Drive from Ise Jingu! Interact with Marine Animals - Part 1', description = 'I visited the Ise Sea Paradise, which was ranked 5th in the domestic popular aquarium category by TripAdvisor, the world''s largest travel site. For more details, visit https://www.kankomie.or.jp/report/detail_181.html' where id = 'Q6N_k03_nPPk1VerQ3NfG';